import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 2:
        print("Error: Please provide exactly one argument - the path to the XML configuration file.", file=sys.stderr)
        sys.exit(1)

    xml_file_path = sys.argv[1]

    try:
        with open(xml_file_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        print(f"Error: File not found - {xml_file_path}", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied - {xml_file_path}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: Could not read file - {str(e)}", file=sys.stderr)
        sys.exit(1)

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as e:
        print(f"Error: Invalid XML format - {str(e)}", file=sys.stderr)
        sys.exit(1)

    services = []
    for service_elem in root.findall('service'):
        name = service_elem.get('name')
        if not name:
            print("Error: Missing 'name' attribute in service element", file=sys.stderr)
            sys.exit(1)

        host_elem = service_elem.find('host')
        port_elem = service_elem.find('port')

        if host_elem is None or port_elem is None:
            print("Error: Missing 'host' or 'port' element in service", file=sys.stderr)
            sys.exit(1)

        host = host_elem.text if host_elem.text else ""
        port_text = port_elem.text if port_elem.text else ""

        try:
            port = int(port_text)
        except ValueError:
            print(f"Error: Invalid port value '{port_text}' - must be an integer", file=sys.stderr)
            sys.exit(1)

        services.append({
            "name": name,
            "host": host,
            "port": port
        })

    print(json.dumps(services, indent=2))

