import sys
import xml.etree.ElementTree as ET

def xml_config_to_json(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()

        result = {}

        for child in root:
            tag_name = child.tag
            value = None

            # Check for 'value' attribute
            if child.get('value') is not None:
                value = child.get('value')
            else:
                # Use text content with leading and trailing whitespace removed
                text = child.text.strip() if child.text is not None else ""
                value = text

            result[tag_name] = value

        # Print JSON object with 2 spaces indentation and newline
        import json
        print(json.dumps(result, indent=2))

    except ET.ParseError:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_config_to_json(sys.argv[1])

