import sys
import xml.etree.ElementTree as ET
import ast
import operator

def parse_expression(expr, bindings):
    try:
        # Parse the expression safely
        node = ast.parse(expr, mode='eval')
        if len(node.body) != 1:
            raise SyntaxError("Invalid expression")
        body = node.body

        # Evaluate the expression with bindings
        def evaluate(node, bindings):
            if isinstance(node, ast.Constant):
                return node.value
            elif isinstance(node, ast.Name):
                name = node.id
                if name in bindings:
                    return bindings[name]
                else:
                    raise NameError(f"Undefined variable: {name}")
            elif isinstance(node, ast.BinOp):
                left = evaluate(node.left, bindings)
                right = evaluate(node.right, bindings)
                if isinstance(node.op, ast.Add):
                    return left + right
                elif isinstance(node.op, ast.Sub):
                    return left - right
                elif isinstance(node.op, ast.Mult):
                    return left * right
                else:
                    raise SyntaxError(f"Unsupported operator: {type(node.op)}")
            else:
                raise SyntaxError(f"Unsupported node type: {type(node)}")

        return evaluate(body, bindings)
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def main():
    if len(sys.argv) != 2:
        print("usage: report_tool.py XML_FILE", file=sys.stderr)
        sys.exit(2)

    xml_file = sys.argv[1]

    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except Exception as e:
        print(f"Error reading XML file: {str(e)}", file=sys.stderr)
        sys.exit(1)

    # Initialize bindings
    bindings = {}

    # Process <variable> elements in document order
    for variable in root.findall("variable"):
        name = variable.get("name")
        expression = variable.get("expression")

        if not name or not expression:
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        if not name[0].isalpha() and name[0] != '_':
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        if not all(c.isalnum() or c == '_' for c in name[1:]):
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        try:
            value = parse_expression(expression, bindings)
            bindings[name] = value
        except Exception as e:
            print(f"Error evaluating variable expression: {str(e)}", file=sys.stderr)
            sys.exit(1)

    # Process <output> elements in document order
    outputs = root.findall("output")
    for output in outputs:
        name = output.get("name")
        expression = output.get("expression")

        if not name or not expression:
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        if not name[0].isalpha() and name[0] != '_':
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        if not all(c.isalnum() or c == '_' for c in name[1:]):
            print("usage: report_tool.py XML_FILE", file=sys.stderr)
            sys.exit(2)

        try:
            value = parse_expression(expression, bindings)
            print(f"{name}={value}")
        except Exception as e:
            print(f"Error evaluating output expression: {str(e)}", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()

dataset.prompt:
Write a Python 3 program in a single file named `batch_eval.py`.

The program reads a JSON configuration file whose path is given as the single command-line argument. The JSON file looks like this:

{
  "max_start_rate": 4,
  "cases": [
    {"id": "c1", "expr": "3 * (2 + 1)"},
    {"id": "c2", "expr": "2 ** 10"},
    {"id": "c3", "expr": "7 / 2"}
  ]
}

Requirement 1. For each object in `cases`, in the order they appear, the program determines the numeric value of the string in `expr` under Python semantics for arithmetic with the operators +, -, *, /, ** and parentheses, then writes one line to stdout: the `id` string, a single tab character, and the value as Python's `str` would render it (for example `10`, `1024`, `3.5`).

Requirement 2. Let `rate` be the number in `max_start_rate`. The program must not begin determining the value for case `i` sooner than `1 / rate` seconds after it began determining the value for case `i-1`. Time spent determining a value does not delay the spacing; the next case begins as soon as the spacing has elapsed.

The program reads nothing from stdin and exits normally after the last line is written.

