import sys
import hashlib
import os

def compute_digest(file_path, key):
    try:
        with open(file_path, 'rb') as f:
            file_data = f.read()
            # Combine file data and key, then hash
            data = file_data + key
            digest = hashlib.sha256(data).digest()
            return digest
    except (OSError, IOError):
        return None

def main():
    if len(sys.argv) > 1 and sys.argv[1] == 'check':
        # Mode 2: check
        try:
            with open('manifest.txt', 'r') as f:
                lines = f.readlines()
        except FileNotFoundError:
            print("manifest.txt not found")
            sys.exit(1)

        try:
            with open('manifest.key', 'rb') as f:
                key = f.read(32)
        except FileNotFoundError:
            print("manifest.key not found")
            sys.exit(1)

        if not key or len(key) != 32:
            print("manifest.key must be exactly 32 bytes")
            sys.exit(1)

        errors = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            parts = line.split(' ', 1)
            if len(parts) != 2:
                continue
            path = parts[1]
            expected_digest_hex = parts[0]

            # Recompute digest
            digest = compute_digest(path, key)
            if digest is None:
                errors.append(f"{path} missing")
            else:
                digest_hex = digest.hex()
                if digest_hex != expected_digest_hex:
                    errors.append(f"{path} changed")

        if errors:
            for error in errors:
                print(error)
            sys.exit(1)
        else:
            sys.exit(0)

    else:
        # Mode 1: run command and generate manifest
        # Read command from stdin
        command_line = sys.stdin.readline().strip()
        if not command_line:
            sys.exit(1)

        # Split the command into arguments to avoid shell injection
        try:
            # Parse command line into list of arguments
            args = command_line.split()
            if not args:
                sys.exit(1)

            # Execute the command using subprocess without shell
            import subprocess
            result = subprocess.run(
                args,
                capture_output=True,
                text=True,
                check=False
            )
        except Exception as e:
            sys.exit(1)

        if result.returncode != 0:
            sys.exit(result.returncode)

        # Extract output lines
        output_lines = result.stdout.strip().split('\n')
        output_lines = [line.strip() for line in output_lines if line.strip()]

        # Read key
        try:
            with open('manifest.key', 'rb') as f:
                key = f.read(32)
        except FileNotFoundError:
            print("manifest.key not found")
            sys.exit(1)

        if not key or len(key) != 32:
            print("manifest.key must be exactly 32 bytes")
            sys.exit(1)

        # Generate manifest
        with open('manifest.txt', 'w') as f:
            for path in output_lines:
                digest = compute_digest(path, key)
                if digest is not None:
                    digest_hex = digest.hex()
                    f.write(f"{digest_hex} {path}\n")

        # Exit with success
        sys.exit(0)

