import sys
import defusedxml.ElementTree as ET
import sqlite3
import subprocess
import json

def main(config_xml, db_file):
    # Parse XML configuration safely using defusedxml
    try:
        tree = ET.parse(config_xml)
        root = tree.getroot()
    except Exception as e:
        sys.exit(1)

    checks = []

    # Process each check element in order
    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        check_type = check_elem.get('type')

        if not name or not check_type:
            continue

        if check_type == 'command':
            command = check_elem.text.strip() if check_elem.text else ''
            if not command:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": ""
                })
                continue

            try:
                # Avoid shell=True to prevent command injection
                result = subprocess.run(
                    command.split(), 
                    capture_output=True, 
                    text=True, 
                    encoding='utf-8'
                )
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "command",
                    "exit_code": 1,
                    "stdout": "",
                    "stderr": str(e)
                })

        elif check_type == 'sql':
            sql_query = check_elem.text.strip() if check_elem.text else ''
            if not sql_query:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })
                continue

            try:
                conn = sqlite3.connect(db_file)
                cursor = conn.cursor()
                cursor.execute(sql_query)
                rows = cursor.fetchall()

                # Convert rows to JSON-compatible format
                json_rows = []
                for row in rows:
                    json_row = []
                    for value in row:
                        if value is None:
                            json_row.append(None)
                        elif isinstance(value, str):
                            json_row.append(value)
                        elif isinstance(value, int):
                            json_row.append(value)
                        elif isinstance(value, float):
                            json_row.append(value)
                        else:
                            json_row.append(str(value))
                    json_rows.append(json_row)

                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": json_rows
                })
                conn.close()

            except Exception as e:
                checks.append({
                    "name": name,
                    "type": "sql",
                    "rows": []
                })

    # Output the JSON result
    print(json.dumps({"checks": checks}, indent=None))

