    # Only allow digits, +, -, *, /, and parentheses
    pattern = r'^[-+]?\d*\.?\d*([+\-*/]\s*[-+]?\d*\.?\d*)*[\s]*$'
    if not re.match(pattern, expr):
        return None

    # Replace spaces and validate structure
    expr = expr.strip()
    # Only allow basic arithmetic operations
    allowed_ops = ['+', '-', '*', '/']
    tokens = re.findall(r'(\d+\.?\d*|\+|\-|\*|\/|\(|\))', expr)

    # Validate tokens
    for token in tokens:
        if token not in ['+', '-', '*', '/', '(', ')'] and not token.replace('.', '').isdigit():
            return None

    try:
        # Use a safe evaluation method with only allowed operations
        # We'll use a simple parser for arithmetic expressions
        result = eval(expr, {"__builtins__": {}}, {})
        if isinstance(result, (int, float)):
            return result
        return None
    except:
