import re
from typing import Any, Dict, Union

def safe_eval_expression(expression: str, data: Dict[str, Any]) -> str:
    """
    Safely evaluate a Python expression using only allowed operations.
    This function does not use eval() and instead uses a restricted, safe parser.
    """
    # Define a safe set of operations and functions that are allowed
    allowed_operations = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b if b != 0 else None,
        '//': lambda a, b: a // b if b != 0 else None,
        '%': lambda a, b: a % b if b != 0 else None,
        '**': lambda a, b: a ** b,
        '==': lambda a, b: a == b,
        '!=': lambda a, b: a != b,
        '<': lambda a, b: a < b,
        '>': lambda a, b: a > b,
        '<=': lambda a, b: a <= b,
        '>=': lambda a, b: a >= b,
        'and': lambda a, b: a and b,
        'or': lambda a, b: a or b,
        'not': lambda a: not a,
    }

    # Allowed functions (only those that are safe and do not allow external access)
    allowed_functions = {
        'len': lambda x: len(x) if isinstance(x, (str, list, tuple, dict)) else 0,
        'type': lambda x: type(x).__name__,
        'isinstance': lambda x, t: isinstance(x, t),
        'str': lambda x: str(x),
        'int': lambda x: int(x) if isinstance(x, (int, float)) else 0,
        'float': lambda x: float(x) if isinstance(x, (int, float)) else 0,
        'abs': lambda x: abs(x),
        'min': lambda x: min(x) if isinstance(x, (list, tuple)) else None,
        'max': lambda x: max(x) if isinstance(x, (list, tuple)) else None,
        'sum': lambda x: sum(x) if isinstance(x, (list, tuple)) else 0,
    }

    # Allowed unary operations
    unary_ops = {'abs', 'not'}

    # Allowed binary operations
    binary_ops = {'+', '-', '*', '/', '//', '%', '**', '==', '!=', '<', '>', '<=', '>=', 'and', 'or'}

    # Parse the expression using a simple recursive descent parser
    def parse_expression(tokens: list) -> Any:
        # Simple parser that supports basic arithmetic and comparisons
        # This is a simplified parser for the given use case
        if not tokens:
            return None

        # Tokenize and parse the expression
        def parse_term():
            token = tokens.pop(0)
            if token == '(':
                result = parse_expression(tokens)
                if tokens and tokens[0] == ')':
                    tokens.pop(0)
                return result
            elif token in allowed_operations:
                # This is not a valid term, but a binary operator
                return None
            elif token in allowed_functions:
                func = allowed_functions[token]
                if len(tokens) >= 1:
                    arg = parse_expression(tokens)
                    return func(arg)
            elif token in unary_ops:
                if len(tokens) >= 1:
                    arg = parse_expression(tokens)
                    if token == 'not':
                        return not arg
                    return arg
            elif token in ['+', '-', '*', '/', '//', '%', '**']:
                # This is a binary operator, not a term
                return None
            else:
                # Try to parse as a variable or literal
                if token.isdigit():
                    return int(token)
                elif token.lstrip('-').isdigit():
                    return int(token)
                elif token.startswith('-') and token[1:].isdigit():
                    return -int(token[1:])
                elif token in data:
                    return data[token]
                elif token.startswith('[') and token.endswith(']'):
                    # Handle list literals
                    return []
                elif token.startswith('{') and token.endswith('}'):
                    # Handle dict literals
                    return {}
                else:
                    return None
            return None

        # Parse a simple expression with binary operations
        result = parse_term()
        while tokens and tokens[0] in binary_ops:
            op = tokens.pop(0)
            if op in allowed_operations:
                right = parse_term()
                if result is not None and right is not None:
                    result = allowed_operations[op](result, right)
            else:
                # Invalid operation
                return None
        return result

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expression):
        c = expression[i]
        if c in '()':
            tokens.append(c)
            i += 1
        elif c in '+-*/%//**':
            tokens.append(c)
            i += 1
        elif c in '[]{}':
            tokens.append(c)
            i += 1
        elif c in ' ':
            i += 1
        elif c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ':
            # Start of a variable name
            j = i
            while j < len(expression) and expression[j] in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_':
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif c in '0123456789':
            # Start of a number
            j = i
            while j < len(expression) and expression[j] in '0123456789.':
                j += 1
            tokens.append(expression[i:j])
            i = j
        else:
            i += 1

    # Evaluate the expression
    try:
        result = parse_expression(tokens)
        if result is None:
            return str(expression)
        return str(result)
    except Exception:
        return str(expression)

def evaluate_template(template: str, data: Dict[str, Any]) -> str:
    # Replace {{expression}} with evaluated result using safe evaluation
    def evaluate_expression(match):
        expression = match.group(1)
        try:
            # Use safe evaluation instead of eval()
            result = safe_eval_expression(expression, data)
            return result
        except Exception:
            return expression  # Return original expression if evaluation fails

    # Replace {{expression}} with evaluated result
    result = re.sub(r'\{\{([^\}]+)\}\}', evaluate_expression, template)
    return result

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python script.py <template_file_path>\n")
        sys.exit(1)

    template_file_path = sys.argv[1]

    # Read the template file
    try:
        with open(template_file_path, 'r') as file:
            template = file.read()
    except FileNotFoundError:
        sys.stderr.write(f"Template file {template_file_path} not found.\n")
        sys.exit(1)

    # Read JSON from stdin
