        data = json.loads(json_input)
    except json.JSONDecodeError as e:
        sys.stderr.write(f"Invalid JSON: {e}\n")
        sys.exit(1)

    # Evaluate the template
    result = evaluate_template(template, data)

    # Print the result
    print(result)

if __name__ == "__main__":
