import ast

def evaluate_expression(expr):
    """
    Safely evaluate a mathematical expression using ast.literal_eval.
    Only allows basic arithmetic operations and parentheses.
    """
    try:
        # Parse the expression using ast.literal_eval which is safe for literals and basic arithmetic
        # Only allows numbers, parentheses, and basic operators (+, -, *, /, **)
        tree = ast.parse(expr, mode='eval')

        # Validate the AST structure to ensure only safe operations are used
        for node in ast.walk(tree):
            if isinstance(node, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow)):
                continue
            elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
                continue
            elif isinstance(node, ast.Constant):
                continue
            elif isinstance(node, ast.Name) and node.id in ['True', 'False']:
                continue
            elif isinstance(node, ast.Num):
                continue
            elif isinstance(node, ast.Str):
                continue
            elif isinstance(node, ast.Call):
                # Disallow function calls (e.g., print, len, etc.)
                continue
            elif isinstance(node, ast.Compare):
                # Disallow comparisons
                continue
            elif isinstance(node, ast.BoolOp):
                # Disallow boolean operations
                continue
            elif isinstance(node, ast.List) or isinstance(node, ast.Tuple):
                # Disallow lists and tuples
                continue
            elif isinstance(node, ast.Dict):
                # Disallow dictionaries
                continue
            elif isinstance(node, ast.Attribute):
                # Disallow attributes (e.g., obj.attr)
                continue
            elif isinstance(node, ast.Subscript):
                # Disallow indexing
                continue
            elif isinstance(node, ast.BinOp):
                # Only allow basic arithmetic
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow)):
                    raise ValueError("Invalid operator")
            else:
                raise ValueError("Invalid expression structure")

        # Evaluate the safe AST
        result = eval(compile(tree, '<string>', 'eval'), {"__builtins__": {}}, {})
        return result

    except (SyntaxError, ValueError, TypeError) as e:
        raise ValueError(f"Invalid expression: {expr}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python batch_eval.py <path_to_config_file>")
        sys.exit(1)

    config_path = sys.argv[1]

    # Validate the file path for path traversal
    if not config_path or not config_path.strip():
