def safe_eval_expression(expr, value):
    """
    Safely evaluate arithmetic expressions with only integers, +, *, and the variable 'value'.
    Uses a restricted parser to avoid code injection.
    """
    # Validate expression syntax: only allow integers, +, *, value, and parentheses
    # Replace value with the actual value
    expr_with_value = expr.replace('value', str(value))

    # Validate the expression using a regular expression
    # Only allow digits, +, *, (, ), and spaces
    pattern = r'^\s*([0-9]+(\s*[\+\*]\s*[0-9]+(\s*[\+\*]\s*[0-9]+)*)*)\s*$'
    if not re.match(pattern, expr_with_value):
        return None

    # Split expression into tokens and evaluate safely
    try:
        # Use a simple parser for arithmetic expressions
        tokens = re.findall(r'\d+|\+|\*|\(|\)|value', expr_with_value)
        if not tokens:
            return None

        # Simple recursive descent parser for arithmetic expressions
        def parse_expression(tokens, pos):
            if pos >= len(tokens):
                return None, pos

            left = parse_term(tokens, pos)
            if left is None:
                return None, pos

            while pos < len(tokens) and tokens[pos] in ['+']:
                pos += 1
                right = parse_term(tokens, pos)
                if right is None:
                    return None, pos
                left = left + right

            return left, pos

        def parse_term(tokens, pos):
            if pos >= len(tokens):
                return None, pos

            left = parse_factor(tokens, pos)
            if left is None:
                return None, pos

            while pos < len(tokens) and tokens[pos] in ['*']:
                pos += 1
                right = parse_factor(tokens, pos)
                if right is None:
                    return None, pos
                left = left * right

            return left, pos

        def parse_factor(tokens, pos):
            if pos >= len(tokens):
                return None, pos

            token = tokens[pos]
            if token == 'value':
                pos += 1
                return int(value), pos
            elif token == '(':
                pos += 1
                result, pos = parse_expression(tokens, pos)
                if pos >= len(tokens) or tokens[pos] != ')':
                    return None, pos
                pos += 1
                return result, pos
            elif token.isdigit():
                return int(token), pos
            else:
                return None, pos

        result, _ = parse_expression(tokens, 0)
        if result is not None and isinstance(result, int):
            return result
        return None
    except:
        return None

