    if not url.startswith(('http://', 'https://')):
        print("Invalid URL: must start with http:// or https://", file=sys.stderr)
        sys.exit(1)

    # Validate token file path: prevent path traversal
    if '..' in token_file or '~' in token_file or os.path.isabs(token_file):
        print("Invalid token file path: path traversal or absolute path detected", file=sys.stderr)
        sys.exit(1)

    # Read token with validation
    try:
        with open(token_file, 'r', encoding='utf-8') as f:
            token = f.read().strip()
            if not token:
                print("Token file is empty", file=sys.stderr)
                sys.exit(1)
    except FileNotFoundError:
        print("Token file not found", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("Permission denied when reading token file", file=sys.stderr)
        sys.exit(1)

    # Validate token format: ensure it's a valid Bearer token (basic structure)
    if not token.startswith('Bearer ') and not token.startswith('bearer '):
        print("Invalid token format: must start with 'Bearer ' or 'bearer '", file=sys.stderr)
        sys.exit(1)

    # Prepare headers
    headers = {
