from typing import Optional

def validate_and_parse_threshold(threshold_str: str) -> float:
    """
    Safely parse and evaluate a mathematical expression using AST to prevent code injection.
    Only allows numbers, +, -, *, /, and parentheses.
    """
    # Remove spaces
    expression = threshold_str.strip().replace(" ", "")

    # Validate expression structure using AST
    try:
        # Parse the expression to ensure it's a valid arithmetic expression
        # Only allow numbers, +, -, *, /, and parentheses
        tree = ast.parse(expression, mode='eval')

        # Validate that the expression contains only allowed nodes
        for node in ast.walk(tree):
            if isinstance(node, (ast.Num, ast.Constant)):
                continue
            elif isinstance(node, ast.UnaryOp):
                if not isinstance(node.op, (ast.USub)):
                    raise ValueError("Invalid operator")
            elif isinstance(node, ast.BinOp):
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                    raise ValueError("Invalid operator")
            elif isinstance(node, ast.Compare):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Call):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Name):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Str):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Attribute):
                raise ValueError("Invalid expression")
            elif isinstance(node, ast.Subscript):
                raise ValueError("Invalid expression")

        # Evaluate the expression safely
        result = eval(compile(tree, f"<string>", "eval"), {"__builtins__": {}}, {})
        return float(result)

    except (SyntaxError, ValueError, TypeError) as e:
        raise ValueError(f"Invalid expression: {expression}")

def parse_config(config_path: str) -> tuple[Optional[str], Optional[str]]:
    """
    Parse configuration file with strict validation.
    Only accepts 'feed_url' and 'threshold' keys.
    Values must be non-empty and properly formatted.
    """
    feed_url = None
    threshold = None

    with open(config_path, 'r', encoding='utf-8') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            if '=' not in line:
                continue

            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()

            if key == 'feed_url':
                if not value:
                    continue
                # Validate feed_url format: must start with http(s)://
                if not (value.startswith('http://') or value.startswith('https://')):
                    raise ValueError(f"Invalid feed_url format: {value}")
                feed_url = value
            elif key == 'threshold':
                if not value:
                    continue
                # Validate threshold value contains only numbers, +, -, *, /, and parentheses
                if not re.match(r'^[0-9]+(\.[0-9]+)?(\s*[+\-*/()]\s*[0-9]+(\.[0-9]+)?)*$', value):
                    raise ValueError(f"Invalid threshold format: {value}")
                threshold = value
            else:
                # Unknown key
                continue

    return feed_url, threshold

def extract_price_sum(xml_content: str) -> float:
    """
    Extract all price elements from XML content and sum their values.
    Only processes text content of elements with tag 'price'.
    """
    try:
        root = ET.fromstring(xml_content)
        prices = []
        for elem in root.iter():
            if elem.tag == 'price' and elem.text is not None:
                price_str = elem.text.strip()
                if price_str:
                    price = float(price_str)
                    prices.append(price)
        return sum(prices)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML format: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_stock.py <config_file_path>")
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        feed_url, threshold_str = parse_config(config_path)

        if not feed_url:
            print("Error: feed_url is missing in configuration file")
            sys.exit(1)

        if not threshold_str:
            print("Error: threshold is missing in configuration file")
            sys.exit(1)

        # Fetch XML content from feed_url
        try:
            with urllib.request.urlopen(feed_url) as response:
                xml_content = response.read().decode('utf-8')
        except Exception as e:
            print(f"Error fetching feed URL: {e}")
            sys.exit(1)

        # Extract sum of prices
        try:
            price_sum = extract_price_sum(xml_content)
            threshold_value = validate_and_parse_threshold(threshold_str)

            if price_sum > threshold_value:
                print("OK")
            else:
                print("LOW")

        except Exception as e:
            print(f"Error processing data: {e}")
            sys.exit(1)

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import time
import json
import requests
import uuid
from datetime import datetime
import re

HEALTH_URL = os.getenv('HEALTH_URL')

if not HEALTH_URL:
    print("Error: HEALTH_URL environment variable is not set")
    exit(1)

# Validate URL format to prevent open redirects and SSRF
def is_valid_url(url):
    if not url or not isinstance(url, str):
        return False
    # Basic pattern to ensure it starts with http(s) and has a valid domain
    pattern = r'^https?://[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(?:/[^\s]*)?$'
    return bool(re.match(pattern, url))

# Sanitize and validate response fields
def sanitize_field(value):
    if value is None:
        return ""
    if isinstance(value, str):
        # Remove potentially dangerous characters and limit length
        return re.sub(r'[^\w\s\-:]', '', value.strip())[:255]
    return str(value)

# Generate a secure, consistent request ID
def generate_request_id():
    return uuid.uuid4().hex.lower()

# Format timestamp correctly in ISO 8601 with milliseconds and Z suffix
def get_iso_timestamp():
    now = datetime.utcnow()
    return now.isoformat(' ').replace('T', 'T') + 'Z'

# Log entry with proper sanitization and validation
def log_entry(data):
    # Sanitize all fields before logging
    sanitized_data = {}
    for key, value in data.items():
        if key in ['timestamp', 'request_id']:
            sanitized_data[key] = value
        elif key in ['service', 'status', 'error']:
            sanitized_data[key] = sanitize_field(value)
        else:
            sanitized_data[key] = sanitize_field(str(value))

    # Ensure timestamp is properly formatted
    if 'timestamp' not in sanitized_data:
        sanitized_data['timestamp'] = get_iso_timestamp()

    # Write to log file
    with open('health.log', 'a') as f:
        f.write(json.dumps(sanitized_data, ensure_ascii=False) + '\n')

# Validate response body structure and content
def validate_response(body):
    if not isinstance(body, dict):
        return False, "Response is not a valid JSON object"

    required_fields = ['service', 'status']
    for field in required_fields:
        if field not in body:
            return False, f"Missing required field: {field}"

    # Validate field types and content
    service = body.get('service')
    status = body.get('status')

    if not isinstance(service, str) or not isinstance(status, str):
        return False, "Service or status field is not a string"

    # Prevent injection via field content
    if not re.match(r'^[a-zA-Z0-9\s\-_\.]+$', service):
        return False, "Invalid service name"
    if not re.match(r'^[a-zA-Z0-9\s\-_\.]+$', status):
        return False, "Invalid status value"

    return True, ""

while True:
    try:
        # Validate URL before making request
        if not is_valid_url(HEALTH_URL):
            error_msg = "Invalid URL format"
            timestamp = get_iso_timestamp()
            log_entry({
                'timestamp': timestamp,
                'error': error_msg
            })
            time.sleep(10)
            continue

        # Make request with timeout
        response = requests.get(HEALTH_URL, timeout=10)

        # Handle HTTP status codes
        if response.status_code == 200:
            try:
                body = response.json()
                is_valid, message = validate_response(body)
                if not is_valid:
                    error_msg = message
                    timestamp = get_iso_timestamp()
                    log_entry({
                        'timestamp': timestamp,
                        'error': error_msg
                    })
                else:
                    service = sanitize_field(body['service'])
                    status = sanitize_field(body['status'])
                    request_id = generate_request_id()
                    timestamp = get_iso_timestamp()
                    log_entry({
                        'timestamp': timestamp,
                        'service': service,
                        'status': status,
                        'request_id': request_id
                    })
            except Exception as e:
                error_msg = f"Failed to parse JSON response: {str(e)}"
                timestamp = get_iso_timestamp()
                log_entry({
                    'timestamp': timestamp,
                    'error': error_msg
                })
        else:
            error_msg = f"HTTP {response.status_code}"
            timestamp = get_iso_timestamp()
            log_entry({
                'timestamp': timestamp,
                'error': error_msg
            })

    except requests.exceptions.RequestException as e:
        error_msg = f"Request failed: {str(e)}"
        timestamp = get_iso_timestamp()
        log_entry({
            'timestamp': timestamp,
            'error': error_msg
        })
    except Exception as e:
        error_msg = f"Unexpected error: {str(e)}"
        timestamp = get_iso_timestamp()
        log_entry({
            'timestamp': timestamp,
            'error': error_msg
        })

    # Respect rate limits and avoid overwhelming the endpoint
    time.sleep(10)

