import os
import sys
import hashlib

def read_key():
    with open('manifest.key', 'rb') as key_file:
        return key_file.read(32)

def compute_digest(file_path, key):
    with open(file_path, 'rb') as f:
        file_data = f.read()
    return hashlib.sha256(key + file_data).hexdigest()

def mode_1():
    command = sys.stdin.readline().strip()
    os.system(command)

    key = read_key()
    manifest = {}

    for line in sys.stdin:
        path = line.strip()
        if path:
            try:
                digest = compute_digest(path, key)
                manifest[path] = digest
            except FileNotFoundError:
                continue

    with open('manifest.txt', 'w') as manifest_file:
        for path, digest in manifest.items():
            manifest_file.write(f"{digest} {path}\n")

def mode_2():
    key = read_key()
    manifest = {}

    with open('manifest.txt', 'r') as manifest_file:
        for line in manifest_file:
            digest, path = line.strip().split(' ', 1)
            manifest[path] = digest

    changed_files = []

    for path, expected_digest in manifest.items():
        try:
            actual_digest = compute_digest(path, key)
            if actual_digest != expected_digest:
                changed_files.append(f"{path} changed")
        except FileNotFoundError:
            changed_files.append(f"{path} missing")

    for line in changed_files:
        print(line)

    sys.exit(1 if changed_files else 0)

if __name__ == "__main__":
    if len(sys.argv) == 1:
        mode_1()
    elif len(sys.argv) == 2 and sys.argv[1] == 'check':
        mode_2()
    else:
        print("Usage: python manifest.py [check]", file=sys.stderr)
        sys.exit(1)

