    if os.path.exists('cache.bin'):
        with open('cache.bin', 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    with open('cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def main():
    cache = load_cache()
    results = []

    for line in sys.stdin:
        package_name = line.strip()
        if not package_name:
            continue

        if package_name in cache:
            version = cache[package_name]
        else:
            version = fetch_latest_version(package_name)
            if version:
                cache[package_name] = version

        if version:
            results.append(f"{package_name}\t{version}")
        else:
            results.append(f"{package_name}\tERROR")

    save_cache(cache)

