import sys
import sqlite3
import subprocess
import json
import os
import shlex

def load_cache():
    cache_path = 'row_runner.cache'
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    with open('row_runner.cache', 'w') as f:
        json.dump(cache, f)

def main():
    if len(sys.argv) != 3:
        print("Usage: python row_runner.py <db_path> <table_name>")
        sys.exit(1)

    db_path, table_name = sys.argv[1], sys.argv[2]
    cache = load_cache()
    results = []

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT id, command FROM ? ORDER BY id ASC", (table_name,))

    for row_id, command in cursor.fetchall():
        if command in cache:
            output = cache[command]
        else:
            try:
                output = subprocess.check_output(shlex.split(command), text=True)
                cache[command] = output
            except subprocess.CalledProcessError as e:
                output = f"Error: {e}"

        results.append({"id": row_id, "output": output})

    conn.close()
    save_cache(cache)

    print(json.dumps(results))

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import shlex
import os

def load_state():
    if os.path.exists('report_state.json'):
        with open('report_state.json', 'r') as f:
            return json.load(f)
    return {}

def save_state(state):
    with open('report_state.json', 'w') as f:
        json.dump(state, f, indent=2)

def run_command(command):
    try:
        process = subprocess.Popen(shlex.split(command), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = process.communicate()
        return process.returncode, stdout, stderr
    except Exception as e:
        return -1, '', str(e)

def main(jobs_file, report_file):
    with open(jobs_file, 'r') as f:
        jobs_data = json.load(f)

    jobs = jobs_data['jobs']
    state = load_state()

    for job in jobs:
        name = job['name']
        command = job['command']

        if name in state:
            exit_code = state[name]['exit_code']
            stdout = state[name]['stdout']
            stderr = state[name]['stderr']
        else:
            exit_code, stdout, stderr = run_command(command)
            state[name] = {
                'exit_code': exit_code,
                'stdout': stdout,
                'stderr': stderr
            }

    save_state(state)

    with open(report_file, 'w') as f:
        f.write('<!DOCTYPE html>\n<html>\n<head>\n<title>Job Report</title>\n</head>\n<body>\n')
        f.write('<h1>Job Report</h1>\n')
        f.write('<table border="1">\n')
        f.write('<tr><th>Name</th><th>Exit code</th><th>Stdout</th><th>Stderr</th></tr>\n')

        for job in jobs:
            name = job['name']
            job_state = state[name]
            f.write(f'<tr><td>{name}</td><td>{job_state["exit_code"]}</td><td>{job_state["stdout"]}</td><td>{job_state["stderr"]}</td></tr>\n')

        f.write('</table>\n')
        f.write('</body>\n</html>\n')

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python build_report.py <jobs_file> <report_file>')
        sys.exit(1)

    jobs_file = sys.argv[1]
    report_file = sys.argv[2]
    main(jobs_file, report_file)

import os
import sys
import json
import time
import subprocess
import requests

def load_config(config_path):
    with open(config_path, 'r') as file:
        return json.load(file)

def fetch_pending_jobs(api_base_url, token):
    headers = {'Authorization': f'Bearer {token}'}
    response = requests.get(f'{api_base_url}/jobs?status=pending', headers=headers, timeout=10)
    response.raise_for_status()
    return response.json().get('jobs', [])

def run_command(command, working_dir, timeout_seconds):
    try:
        result = subprocess.run(
            command,
            cwd=working_dir,
            shell=False,
            capture_output=True,
            text=True,
            timeout=timeout_seconds
        )
        return {
            'exit_code': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr,
            'timed_out': False
        }
    except subprocess.TimeoutExpired:
        return {
            'exit_code': None,
            'stdout': '',
            'stderr': '',
            'timed_out': True
        }

def report_result(api_base_url, token, job_id, result):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }
    response = requests.post(
        f'{api_base_url}/jobs/{job_id}/result',
        headers=headers,
        json=result,
        timeout=10
    )
    response.raise_for_status()

def main():
    if len(sys.argv) != 2:
        print("Usage: CI_API_TOKEN=abc123 python jobrunner.py config.json")
        sys.exit(1)

    config_path = sys.argv[1]
    config = load_config(config_path)

    api_base_url = config['api_base_url']
    token_env_var = config['token_env_var']
    working_dir = config['working_dir']
    timeout_seconds = config['timeout_seconds']

    token = os.getenv(token_env_var)
    if not token:
        print(f"Environment variable {token_env_var} not set.")
        sys.exit(1)

    jobs = fetch_pending_jobs(api_base_url, token)
    for job in jobs:
        job_id = job['id']
        command = job['command'].split()
        result = run_command(command, working_dir, timeout_seconds)
        report_result(api_base_url, token, job_id, result)
        if result['timed_out']:
            print(f"{job_id} timeout")
        else:
            print(f"{job_id} {result['exit_code']}")

if __name__ == '__main__':
    main()

