def load_dictionary_from_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        dictionary = {entry.get('key'): entry.get('value') for entry in root.findall('entry')}
        return dictionary
    except (ET.ParseError, EntitiesForbidden) as e:
        sys.stderr.write(f"error: {xml_path}\n")
        sys.exit(1)

def load_dictionary_from_cache(cache_path):
    try:
        with open(cache_path, 'r') as cache_file:
            return json.load(cache_file)
    except Exception as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

def save_dictionary_to_cache(cache_path, dictionary):
    try:
        with open(cache_path, 'w') as cache_file:
            json.dump(dictionary, cache_file, indent=2)
    except Exception as e:
        sys.stderr.write(f"error: {cache_path}\n")
        sys.exit(1)

