import ast

def fetch_formulas():
    formula_url = os.getenv('FORMULA_URL')
    formula_token = os.getenv('FORMULA_TOKEN')

    if not formula_url or not formula_token:
        print("Environment variables FORMULA_URL and FORMULA_TOKEN must be set.", file=sys.stderr)
        sys.exit(1)

    headers = {'Authorization': f'Bearer {formula_token}'}
    req = urllib.request.Request(formula_url, headers=headers)

    try:
        with urllib.request.urlopen(req) as response:
            if response.status != 200:
                print("fetch failed", file=sys.stderr)
                sys.exit(1)
            return json.loads(response.read().decode())
    except urllib.error.URLError as e:
        print("fetch failed", file=sys.stderr)
        sys.exit(1)

def evaluate_formulas(formulas):
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            a, b = map(float, line.split())
        except ValueError:
            continue

        for name, expression in formulas.items():
            try:
                value = ast.literal_eval(expression)
                if isinstance(value, (int, float)):
                    print(f"{name}={repr(value)}")
                else:
                    print(f"{name}={repr(eval(expression, {'a': a, 'b': b}))}")
            except (SyntaxError, ValueError):
                continue

