import sys
import re
import time
import ast
import operator

def evaluate_expression(expression):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return allowed_operators[type(node.op)](operand)
        else:
            raise ValueError("Unsupported operation")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def process_line(line, line_number):
    pattern = r'\{\{(.+?)\}\}'
    matches = re.finditer(pattern, line)
    for match in matches:
        expression = match.group(1).strip()
        try:
            result = evaluate_expression(expression)
            line = line.replace(match.group(0), str(result))
        except Exception as e:
            sys.stderr.write(f"line {line_number}: {str(e)}\n")
            return None
    return line

def main():
    error_count = 0
    line_number = 0

    for line in sys.stdin:
        line_number += 1
        if line_number > 1:
            time.sleep(0.2)

        processed_line = process_line(line, line_number)
        if processed_line is not None:
            sys.stdout.write(processed_line)
        else:
            sys.stdout.write(line)
            error_count += 1

    if error_count > 0:
        sys.stderr.write(f"errors: {error_count}\n")

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import shlex
import os

def execute_command(command, input_string):
    try:
        # Use shlex.quote to safely escape the input_string
        safe_input = shlex.quote(input_string)
        # Use list comprehension to safely construct the command
        safe_command = [shlex.quote(cmd) for cmd in command] + [safe_input]
        result = subprocess.run(
            safe_command,
            capture_output=True,
            text=True,
            check=True
        )
        return {
            "input": input_string,
            "stdout": result.stdout.strip(),
            "stderr": result.stderr.strip(),
            "returncode": result.returncode
        }
    except subprocess.CalledProcessError as e:
        return {
            "input": input_string,
            "stdout": e.stdout.strip() if e.stdout else "",
            "stderr": e.stderr.strip() if e.stderr else "",
            "returncode": e.returncode
        }
    except Exception as e:
        return {
            "input": input_string,
            "stdout": "",
            "stderr": "An unexpected error occurred.",
            "returncode": -1
        }

def validate_config(config):
    if not isinstance(config, dict):
        raise ValueError("Configuration must be a dictionary.")
    if not isinstance(config.get("command"), list) or not all(isinstance(cmd, str) for cmd in config["command"]):
        raise ValueError("Command must be a list of strings.")
    if not isinstance(config.get("inputs"), list) or not all(isinstance(inp, str) for inp in config["inputs"]):
        raise ValueError("Inputs must be a list of strings.")
    if not isinstance(config.get("output_file"), str):
        raise ValueError("Output file must be a string.")

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <config_path>")
        sys.exit(1)

    config_path = sys.argv[1]

    with open(config_path, 'r') as config_file:
        config = json.load(config_file)

    try:
        validate_config(config)
    except ValueError as e:
        print(f"Configuration error: {e}")
        sys.exit(1)

    command = config["command"]
    inputs = config["inputs"]
    output_file = config["output_file"]

    # Ensure the output file path is absolute and within a safe directory
    safe_output_dir = os.path.abspath(os.path.dirname(output_file))
    if not safe_output_dir.startswith(os.path.abspath(os.curdir)):
        print("Error: Output file path is not within the current directory.")
        sys.exit(1)

    results = [execute_command(command, input_string) for input_string in inputs]

    with open(output_file, 'w') as out_file:
        json.dump(results, out_file, indent=2)

if __name__ == "__main__":
    main()

import sys
import urllib.request
import xml.etree.ElementTree as ET
import ssl
import re
from defusedxml.ElementTree import fromstring

def fetch_exchange_rate(currency_code):
    url = "https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml"
    context = ssl.create_default_context(ssl.Purpose.SERVER_AUTH)

    if not re.match(r'^[A-Z]{3}$', currency_code):
        print("Invalid currency code")
        raise SystemExit(1)

    try:
        with urllib.request.urlopen(url, context=context, timeout=10) as response:
            xml_data = response.read()
    except urllib.error.URLError:
        print("Request failed")
        raise SystemExit(2)
    except ssl.SSLError:
        print("SSL certificate verification failed")
        raise SystemExit(2)
    except TimeoutError:
        print("Request timed out")
        raise SystemExit(2)

    try:
        root = fromstring(xml_data)
    except ET.ParseError:
        print("XML parsing failed")
        raise SystemExit(2)

    for cube in root.findall(".//{*}Cube[@currency]"):
        if cube.get("currency") == currency_code:
            try:
                rate = float(cube.get("rate"))
            except (TypeError, ValueError):
                print("Invalid rate data")
                raise SystemExit(2)
            print(f"{rate:.4f}")
            raise SystemExit(0)

    print("Currency not found")
    raise SystemExit(1)

