import sys
import os
import requests
import re

def is_valid_package_name(package_name):
    # Basic validation for package names: alphanumeric, underscores, and hyphens
    return re.match(r'^[A-Za-z0-9_-]+$', package_name) is not None

def main():
    print("Package file: ", end="")
    file_path = sys.stdin.readline().strip()

    # Validate file path to prevent path traversal
    if not os.path.isfile(file_path) or not os.path.abspath(file_path).startswith(os.getcwd()):
        print("Invalid file path")
        return

    with open(file_path, 'r') as file:
        package_names = [line.strip() for line in file if line.strip() and is_valid_package_name(line.strip())]

    results = []
    for package in package_names:
        try:
            response = requests.get(f"https://pypi.org/pypi/{package}/json", timeout=10)
            if response.status_code == 200:
                version = response.json().get('info', {}).get('version', 'unavailable')
                if version != 'unavailable':
                    print(f"{package}=={version}")
                    results.append(f"{package}=={version}")
                else:
                    print(f"{package}: unavailable")
                    results.append(f"{package}: unavailable")
            else:
                print(f"{package}: unavailable")
                results.append(f"{package}: unavailable")
        except requests.RequestException:
            print(f"{package}: unavailable")
            results.append(f"{package}: unavailable")

