def validate_xml_element(element, required_attributes):
    if element is None:
        raise ValueError("Missing required XML element")
    for attr in required_attributes:
        if not element.get(attr):
            raise ValueError(f"Missing required attribute: {attr}")

def sanitize_input(input_str):
    return re.sub(r'[^\w\s-]', '', input_str)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("ERROR\n")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except (ET.ParseError, FileNotFoundError):
        sys.stderr.write("ERROR\n")
        sys.exit(1)

    try:
        validate_xml_element(root.find('database'), ['path'])
        validate_xml_element(root.find('query'), ['table', 'column', 'value'])

        database_path = os.path.abspath(root.find('database').get('path'))
        query_table = sanitize_input(root.find('query').get('table'))
        query_column = sanitize_input(root.find('query').get('column'))
        query_value = sanitize_input(root.find('query').get('value'))

        if not os.path.exists(database_path):
            raise FileNotFoundError("Database file not found")

        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (query_table,))
        if not cursor.fetchone():
            raise ValueError(f"Table {query_table} does not exist")

        cursor.execute(f"PRAGMA table_info({query_table})")
        columns = [row[1] for row in cursor.fetchall() if row[1] == query_column]
        if not columns:
            raise ValueError(f"Column {query_column} does not exist in table {query_table}")

        cursor.execute(f"SELECT * FROM {query_table} WHERE {query_column} = ?", (query_value,))
        columns = [description[0] for description in cursor.description]

        for row in cursor.fetchall():
            row_dict = dict(zip(columns, row))
            print(json.dumps(row_dict, ensure_ascii=False))

    except (ValueError, sqlite3.Error, FileNotFoundError) as e:
        sys.stderr.write("ERROR\n")
        sys.exit(1)
    finally:
        if 'conn' in locals():
            conn.close()

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import os

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_file = sys.argv[1]

    # Check if the file exists and is readable
    if not os.path.isfile(xml_file) or not os.access(xml_file, os.R_OK):
        sys.exit(1)

    try:
        # Use parse() with a limited parser to mitigate XXE
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(xml_file, parser=parser)
        root = tree.getroot()
        if root.tag != 'configuration':
            sys.exit(1)

        config_dict = {}
        for child in root:
            if len(child) == 0:
                value = child.attrib.get('value', child.text.strip() if child.text else '')
                config_dict[child.tag] = value

        print(json.dumps(config_dict, indent=2))
        sys.exit(0)
    except ET.ParseError:
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import pickle
import sys
import json

def safe_pickle_load(file_path):
    """Safely load data from a pickle file."""
    try:
        with open(file_path, 'rb') as f:
            return pickle.loads(f.read())
    except (pickle.UnpicklingError, EOFError, AttributeError, ImportError, IndexError) as e:
        raise ValueError(f"Invalid pickle data: {str(e)}")

def main():
    try:
        tasks = []
        if os.path.exists('tasks.bin'):
            tasks = safe_pickle_load('tasks.bin')

        with open('tasks.txt', 'r') as f:
            for line in f:
                tasks.append(line.rstrip())

        with open('tasks.bin', 'wb') as f:
            f.write(pickle.dumps(tasks, protocol=pickle.HIGHEST_PROTOCOL))

        print(len(tasks))

        with open('tasks.log', 'a') as f:
            f.write(f"{len(tasks)}\n")

    except Exception as e:
        with open('tasks.log', 'a') as f:
            f.write(f"Error: {json.dumps(str(e))}\n")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def run_command(job_id, command):
    try:
        # Split the command into a list of arguments
        command_list = command.split()
        result = subprocess.run(command_list, capture_output=True, text=True)
        return job_id, {
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode
        }
    except FileNotFoundError:
        return job_id, {
            "stdout": "",
            "stderr": "Command not found",
            "returncode": -1
        }
    except Exception as e:
        return job_id, {
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        }

def validate_json_structure(jobs):
    if not isinstance(jobs, dict):
        raise ValueError("JSON root must be an object")
    for job_id, command in jobs.items():
        if not isinstance(job_id, str) or not isinstance(command, str):
            raise ValueError("Job id and command must be strings")

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_jobs.py <path_to_json_file>")
        sys.exit(1)

    json_file_path = sys.argv[1]

    # Validate and sanitize the file path
    if not os.path.isfile(json_file_path):
        print("Error: The specified file does not exist.")
        sys.exit(1)

    with open(json_file_path, 'r') as file:
        try:
            jobs = json.load(file)
            validate_json_structure(jobs)
        except json.JSONDecodeError:
            print("Error: Failed to parse JSON file.")
            sys.exit(1)
        except ValueError as e:
            print(f"Error: {e}")
            sys.exit(1)

    results = {}
    with ThreadPoolExecutor(max_workers=4) as executor:
        future_to_job = {executor.submit(run_command, job_id, command): job_id for job_id, command in jobs.items()}
        for future in as_completed(future_to_job):
            job_id, result = future.result()
            results[job_id] = result

    print(json.dumps(results))

if __name__ == "__main__":
    main()

import sys
import os
import requests
import json
import re
from datetime import datetime

def validate_date(date_text):
    try:
        datetime.strptime(date_text, '%Y-%m-%d')
        return True
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    date = sys.argv[1]
    if not validate_date(date):
        sys.stderr.write('invalid date format\n')
        sys.exit(1)

    token = os.getenv('INVOICE_API_TOKEN')
    if not token:
        sys.stderr.write('missing token\n')
        sys.exit(2)

    url = f'https://api.example.com/v1/invoices?date={requests.utils.quote(date)}'
    headers = {'Authorization': f'Bearer {token}'}

    try:
        response = requests.get(url, headers=headers, timeout=10)
    except requests.RequestException as e:
        sys.stderr.write(f'network error: {e}\n')
        sys.exit(4)

    if response.status_code == 401:
        sys.stderr.write('unauthorized\n')
        sys.exit(3)
    elif response.status_code != 200:
        sys.stderr.write(f'{response.status_code}\n')
        sys.exit(4)

    try:
        data = response.json()
    except json.JSONDecodeError:
        sys.stderr.write('invalid JSON response\n')
        sys.exit(4)

    print('id,total_cents')

    for invoice in data.get('invoices', []):
        invoice_id = invoice['id']
        total_cents = sum(item['amount_cents'] * item['quantity'] for item in invoice['line_items'])
        print(f'{invoice_id},{total_cents}')

if __name__ == '__main__':
    main()

import sys
import xml.etree.ElementTree as ET
import requests
import re
import time
import logging
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_input(input_str):
    return re.sub(r'[^\w\-\.]', '', input_str)

def main():
    logging.basicConfig(level=logging.INFO)
    logger = logging.getLogger(__name__)

    if len(sys.argv) != 2:
        logger.error("Usage: python endpoint_status.py endpoints.xml")
        return

    xml_file_path = sys.argv[1]
    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(xml_file_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        logger.error("Error: Could not parse the XML file.")
        return
    except FileNotFoundError:
        logger.error("Error: XML file not found.")
        return

    for endpoint in root.findall('endpoint'):
        name = endpoint.get('name')
        url = endpoint.text.strip()

        if not name or not is_valid_url(url):
            logger.warning(f"Skipping invalid endpoint: {name} - {url}")
            continue

        name = sanitize_input(name)
        url = sanitize_input(url)

        try:
            response = requests.get(url, allow_redirects=False, timeout=5, verify=True)
            print(f"{name}\t{response.status_code}")
        except requests.exceptions.SSLError:
            logger.error(f"SSL error for {name} - {url}")
            print(f"{name}\tERROR")
        except requests.exceptions.Timeout:
            logger.error(f"Timeout for {name} - {url}")
            print(f"{name}\tERROR")
        except requests.exceptions.RequestException as e:
            logger.error(f"Request error for {name} - {url}: {str(e)}")
            print(f"{name}\tERROR")

        time.sleep(1)  # Simple rate limiting

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import requests
from urllib.parse import urlparse
import os

def validate_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python flag_sync.py config.xml")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
        service = root.find('service')
        if service is None:
            raise ValueError("Missing <service> element in config file.")
        url = service.get('url')
        token = service.get('token')
        if not url or not token:
            raise ValueError("Missing url or token attributes in <service> element.")
        if not validate_url(url):
            raise ValueError("Invalid URL format.")
    except ET.ParseError:
        print("Error: Invalid XML config file.")
        sys.exit(1)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    headers = {
        'Authorization': f'Bearer {token}'
    }
    params = {
        'format': 'xml'
    }

    try:
        response = requests.get(url, headers=headers, params=params, verify=True)
        response.raise_for_status()
    except requests.RequestException as e:
        print(f"Error: Failed to fetch flags - {e}")
        sys.exit(1)

    try:
        flags_tree = ET.ElementTree(ET.fromstring(response.text))
        flags_root = flags_tree.getroot()
    except ET.ParseError:
        print("Error: Invalid XML response.")
        sys.exit(1)

    try:
        with open('flags.xml', 'w') as f:
            flags_tree.write(f, encoding='unicode', xml_declaration=True)
    except IOError as e:
        print(f"Error: Failed to write flags.xml - {e}")
        sys.exit(1)

    flag_count = len(flags_root.findall('flag'))
    print(f"count={flag_count}")

if __name__ == "__main__":
    main()

