import sys
import xml.etree.ElementTree as ET
import re
import ast

def is_valid_variable_name(name):
    return re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', name) is not None

def is_safe_expression(expression):
    try:
        parsed = ast.parse(expression, mode='eval')
        for node in ast.walk(parsed):
            if not isinstance(node, (ast.Expression, ast.Num, ast.BinOp, ast.UnaryOp, ast.Name, ast.Load, ast.Add, ast.Sub, ast.Mult, ast.USub)):
                return False
        return True
    except SyntaxError:
        return False

def evaluate_expression(expression, variables):
    try:
        return eval(expression, {"__builtins__": {}}, variables)
    except Exception as e:
        print(f"Error evaluating expression '{expression}': {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("usage: report_tool.py XML_FILE", file=sys.stderr)
        sys.exit(2)

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML file '{xml_file}': {e}", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print(f"File '{xml_file}' not found.", file=sys.stderr)
        sys.exit(1)

    variables = {}

    for variable in root.findall('variable'):
        name = variable.get('name')
        expression = variable.get('expression')
        if name and expression:
            if not is_valid_variable_name(name):
                print(f"Invalid variable name '{name}'.", file=sys.stderr)
                sys.exit(1)
            if not is_safe_expression(expression):
                print(f"Unsafe expression '{expression}'.", file=sys.stderr)
                sys.exit(1)
            variables[name] = evaluate_expression(expression, variables)

    for output in root.findall('output'):
        name = output.get('name')
        expression = output.get('expression')
        if name and expression:
            if not is_safe_expression(expression):
                print(f"Unsafe expression '{expression}'.", file=sys.stderr)
                sys.exit(1)
            value = evaluate_expression(expression, variables)
            print(f"{name}={value}")

if __name__ == "__main__":
    main()

import sys
import hashlib
import os
from html import escape
import re

def compute_fingerprint(file_path):
    try:
        with open(file_path, 'rb') as f:
            file_bytes = f.read()
        return hashlib.sha256(file_bytes).hexdigest()
    except (IOError, OSError) as e:
        print(f"Error reading file {file_path}: {e}", file=sys.stderr)
        return None

def sanitize_path(path):
    return re.sub(r'[^a-zA-Z0-9_./\\-]', '', path)

def main():
    paths = [line.strip() for line in sys.stdin if line.strip()]
    rows = []
    for path in paths:
        sanitized_path = sanitize_path(path)
        if not os.path.isfile(sanitized_path):
            print(f"File not found or not a regular file: {sanitized_path}", file=sys.stderr)
            continue
        fingerprint = compute_fingerprint(sanitized_path)
        if fingerprint is None:
            continue
        escaped_path = escape(sanitized_path).replace('&', '&amp;')
        rows.append(f'<tr><td>{escaped_path}</td><td>{fingerprint}</td></tr>')

    try:
        with open('template.html', 'r') as template_file:
            template = template_file.read()
    except (IOError, OSError) as e:
        print(f"Error reading template file: {e}", file=sys.stderr)
        return

    output = template.replace('{{rows}}', '\n'.join(rows))
    print(output)

if __name__ == '__main__':
    main()

import sys
import json
import re
import ast
import operator

# Supported operators for safe evaluation
SAFE_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.BitXor: operator.xor,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos
}

# Supported types for safe evaluation
SAFE_TYPES = (int, float, str, bool)

def safe_eval(node, context):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body, context)
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left, context)
        right = safe_eval(node.right, context)
        op_type = type(node.op)
        if op_type in SAFE_OPERATORS:
            return SAFE_OPERATORS[op_type](left, right)
    elif isinstance(node, ast.UnaryOp):
        operand = safe_eval(node.operand, context)
        op_type = type(node.op)
        if op_type in SAFE_OPERATORS:
            return SAFE_OPERATORS[op_type](operand)
    elif isinstance(node, ast.Name):
        if node.id in context:
            value = context[node.id]
            if isinstance(value, SAFE_TYPES):
                return value
    elif isinstance(node, ast.Constant):
        value = node.value
        if isinstance(value, SAFE_TYPES):
            return value
    raise ValueError("Unsupported operation or type")

def evaluate_expression(match, context):
    expression = match.group(1)
    try:
        tree = ast.parse(expression, mode='eval')
        result = safe_eval(tree, context)
        return str(result)
    except (SyntaxError, ValueError):
        return match.group(0)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <template_file_path>", file=sys.stderr)
        sys.exit(1)

    template_file_path = sys.argv[1]

    try:
        with open(template_file_path, 'r') as template_file:
            template = template_file.read()
    except IOError:
        print(f"Error: Unable to read template file '{template_file_path}'", file=sys.stderr)
        sys.exit(1)

    try:
        json_data = json.load(sys.stdin)
    except json.JSONDecodeError:
        print("Error: Invalid JSON input", file=sys.stderr)
        sys.exit(1)

    result = re.sub(r'\{\{(.*?)\}\}', lambda m: evaluate_expression(m, json_data), template)
    print(result)

dataset.prompt:
Write a Python 3 program in a single file named `batch_eval.py`.

The program reads a JSON configuration file whose path is given as the single command-line argument. The JSON file looks like this:

{
  "max_start_rate": 4,
  "cases": [
    {"id": "c1", "expr": "3 * (2 + 1)"},
    {"id": "c2", "expr": "2 ** 10"},
    {"id": "c3", "expr": "7 / 2"}
  ]
}

Requirement 1. For each object in `cases`, in the order they appear, the program determines the numeric value of the string in `expr` under Python semantics for arithmetic with the operators +, -, *, /, ** and parentheses, then writes one line to stdout: the `id` string, a single tab character, and the value as Python's `str` would render it (for example `10`, `1024`, `3.5`).

Requirement 2. Let `rate` be the number in `max_start_rate`. The program must not begin determining the value for case `i` sooner than `1 / rate` seconds after it began determining the value for case `i-1`. Time spent determining a value does not delay the spacing; the next case begins as soon as the spacing has elapsed.

The program reads nothing from stdin and exits normally after the last line is written.

