import sys
import json
import time
import ast
import operator

def safe_eval(expr, allowed_operators):
    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return operator.add(left, right)
            elif isinstance(op, ast.Sub):
                return operator.sub(left, right)
            elif isinstance(op, ast.Mult):
                return operator.mul(left, right)
            elif isinstance(op, ast.Div):
                return operator.truediv(left, right)
            elif isinstance(op, ast.Pow):
                return operator.pow(left, right)
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Expression):
            return _eval(node.body)
        else:
            raise ValueError("Unsupported operation")

    tree = ast.parse(expr, mode='eval')
    return _eval(tree.body)

def main():
    if len(sys.argv) != 2:
        print("Usage: python batch_eval.py <config_file>")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as file:
            config = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading or parsing config file: {e}")
        sys.exit(1)

    if not isinstance(config, dict) or 'max_start_rate' not in config or 'cases' not in config:
        print("Invalid config file structure")
        sys.exit(1)

    max_start_rate = config['max_start_rate']
    cases = config['cases']

    if not isinstance(max_start_rate, (int, float)) or max_start_rate <= 0:
        print("Invalid max_start_rate value")
        sys.exit(1)

    if not isinstance(cases, list):
        print("Invalid cases structure")
        sys.exit(1)

    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow
    }

    for i, case in enumerate(cases):
        if not isinstance(case, dict) or 'id' not in case or 'expr' not in case:
            print(f"Invalid case structure at index {i}")
            continue

        if i > 0:
            time.sleep(1 / max_start_rate)

        try:
            result = safe_eval(case['expr'], allowed_operators)
            print(f"{case['id']}\t{result}")
        except Exception as e:
            print(f"Error evaluating expression for case {case['id']}: {e}")

if __name__ == "__main__":
    main()

import os
import sys
import requests
import subprocess
import re
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_path(path):
    return re.sub(r'[^a-zA-Z0-9_/.-]', '', path)

def main():
    if len(sys.argv) != 4:
        print("Usage: python fetch_report.py <url_file> <output_dir> <executable>")
        sys.exit(1)

    url_file_path = sys.argv[1]
    output_dir = sanitize_path(sys.argv[2].rstrip('/'))
    executable_path = sys.argv[3]

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    with open(url_file_path, 'r', encoding='utf-8') as url_file:
        urls = [line.strip() for line in url_file if line.strip()]

    report_data = []

    for index, url in enumerate(urls, start=1):
        if not is_valid_url(url):
            print(f"Invalid URL {url}")
            continue

        try:
            response = requests.get(url, verify=True)
            response.raise_for_status()
            body_file_path = os.path.join(output_dir, f"{index}.body")
            with open(body_file_path, 'wb') as body_file:
                body_file.write(response.content)

            result = subprocess.run(
                [executable_path, body_file_path],
                capture_output=True,
                text=True,
                check=True,
                shell=False
            )
            byte_count = int(result.stdout.split()[0])

            report_data.append((url, body_file_path, byte_count))

        except requests.RequestException as e:
            print(f"Error fetching URL {url}: {e}")
        except subprocess.CalledProcessError as e:
            print(f"Error executing {executable_path} for URL {url}: {e}")
        except ValueError as e:
            print(f"Error parsing byte count for URL {url}: {e}")
        except Exception as e:
            print(f"Unexpected error processing URL {url}: {e}")

