import os
import sys
import hashlib
import subprocess
import re

def read_key():
    try:
        with open('manifest.key', 'rb') as key_file:
            key = key_file.read(32)
            if len(key) != 32:
                raise ValueError("Key file must be exactly 32 bytes long.")
            return key
    except (FileNotFoundError, IOError, ValueError) as e:
        print(f"Error reading key file: {e}", file=sys.stderr)
        sys.exit(1)

def compute_digest(file_path, key):
    try:
        with open(file_path, 'rb') as f:
            file_data = f.read()
        return hashlib.sha256(key + file_data).hexdigest()
    except (FileNotFoundError, IOError) as e:
        print(f"Error reading file {file_path}: {e}", file=sys.stderr)
        return None

def sanitize_path(path):
    # Normalize path and ensure it's within the current directory
    normalized_path = os.path.normpath(path)
    if not normalized_path.startswith('.'):
        raise ValueError("Invalid path detected.")
    return normalized_path

def mode_1():
    command = sys.stdin.readline().strip()
    if not command:
        print("No command provided.", file=sys.stderr)
        sys.exit(1)

    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
    except subprocess.CalledProcessError as e:
        print(f"Command execution failed: {e}", file=sys.stderr)
        sys.exit(1)

    key = read_key()
    manifest = {}

    for line in result.stdout.splitlines():
        path = line.strip()
        if path:
            try:
                sanitized_path = sanitize_path(path)
                digest = compute_digest(sanitized_path, key)
                if digest:
                    manifest[sanitized_path] = digest
            except ValueError as e:
                print(f"Skipping invalid path {path}: {e}", file=sys.stderr)

    with open('manifest.txt', 'w') as manifest_file:
        for path, digest in manifest.items():
            manifest_file.write(f"{digest} {path}\n")

def mode_2():
    key = read_key()
    manifest = {}

    try:
        with open('manifest.txt', 'r') as manifest_file:
            for line in manifest_file:
                digest, path = line.strip().split(' ', 1)
                manifest[path] = digest
    except (FileNotFoundError, IOError, ValueError) as e:
        print(f"Error reading manifest.txt: {e}", file=sys.stderr)
        sys.exit(1)

    changed_files = []

    for path, expected_digest in manifest.items():
        try:
            sanitized_path = sanitize_path(path)
            actual_digest = compute_digest(sanitized_path, key)
            if actual_digest is None:
                changed_files.append(f"{path} missing")
            elif actual_digest != expected_digest:
                changed_files.append(f"{path} changed")
        except ValueError as e:
            print(f"Skipping invalid path {path}: {e}", file=sys.stderr)

    for line in changed_files:
        print(line)

    sys.exit(1 if changed_files else 0)

if __name__ == "__main__":
    if len(sys.argv) == 1:
        mode_1()
    elif len(sys.argv) == 2 and sys.argv[1] == 'check':
        mode_2()
    else:
        print("Usage: python manifest.py [check]", file=sys.stderr)
        sys.exit(1)

import sys
import os
import subprocess
from html import escape
import shlex

def read_template(template_path):
    try:
        with open(template_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        print(f"Template file '{template_path}' not found.")
        sys.exit(1)

def execute_command(command):
    try:
        args = shlex.split(command)
        result = subprocess.run(args, capture_output=True, text=True)
        return {
            'command': command,
            'stdout': escape(result.stdout),
            'stderr': escape(result.stderr),
            'exit_code': result.returncode
        }
    except FileNotFoundError:
        return {
            'command': command,
            'stdout': '',
            'stderr': escape(f"Command not found: {command}"),
            'exit_code': 127
        }
    except Exception as e:
        return {
            'command': command,
            'stdout': '',
            'stderr': escape(str(e)),
            'exit_code': -1
        }

def generate_html(results):
    html_sections = []
    for result in results:
        section = f"""
<section>
<h2>{escape(result['command'])}</h2>
<pre>{result['stdout']}</pre>
<pre>{result['stderr']}</pre>
<p>Exit status: {result['exit_code']}</p>
</section>
"""
        html_sections.append(section)
    return ''.join(html_sections)

def sanitize_path(path):
    return os.path.abspath(os.path.normpath(path))

def main():
    if len(sys.argv) > 1:
        template_path = sanitize_path(sys.argv[1])
    else:
        template_path = sanitize_path('report_template.html')

    template = read_template(template_path)

    results = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            results.append(execute_command(line))

    if results:
        html_results = generate_html(results)
        final_html = template.replace('<!--RESULTS-->', html_results)
    else:
        final_html = template

    with open('build-report.html', 'w') as file:
        file.write(final_html)

if __name__ == '__main__':
    main()

import sys
import sqlite3
import subprocess
import json
import os
import shlex

def load_cache():
    cache_path = os.path.join(os.getcwd(), 'row_runner.cache')
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    cache_path = os.path.join(os.getcwd(), 'row_runner.cache')
    with open(cache_path, 'w') as f:
        json.dump(cache, f)

def main():
    if len(sys.argv) != 3:
        print("Usage: python row_runner.py <db_path> <table_name>")
        sys.exit(1)

    db_path, table_name = sys.argv[1], sys.argv[2]
    if not isinstance(db_path, str) or not isinstance(table_name, str):
        print("Error: Invalid input types.")
        sys.exit(1)

    cache = load_cache()
    results = []

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT id, command FROM ? ORDER BY id ASC", (table_name,))

    for row_id, command in cursor.fetchall():
        if command in cache:
            output = cache[command]
        else:
            try:
                command_parts = shlex.split(command)
                output = subprocess.check_output(command_parts, text=True)
                cache[command] = output
            except subprocess.CalledProcessError as e:
                output = f"Error: {e.output}"
            except FileNotFoundError:
                output = "Error: Command not found."

        results.append({"id": row_id, "output": output})

    conn.close()
    save_cache(cache)

    print(json.dumps(results))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import subprocess
import sqlite3
import json
import os
import re

def validate_file_path(file_path):
    # Ensure the file path is absolute and within a safe directory
    abs_path = os.path.abspath(file_path)
    if not abs_path.startswith(os.getcwd()):
        raise ValueError("Invalid file path")
    return abs_path

def run_command(command):
    # Use a list to avoid shell=True and prevent command injection
    result = subprocess.run(command.split(), capture_output=True, text=True)
    return {
        "name": command,
        "type": "command",
        "exit_code": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr
    }

def run_sql_query(query, db_path):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    try:
        cursor.execute(query)
        rows = [
            [
                None if value is None else (int(value) if isinstance(value, int) else float(value) if isinstance(value, float) else str(value))
                for value in row
            ]
            for row in cursor.fetchall()
        ]
    except sqlite3.Error as e:
        raise ValueError(f"SQL error: {e}")
    finally:
        conn.close()
    return {
        "name": query,
        "type": "sql",
        "rows": rows
    }

def parse_xml_config(config_file):
    tree = ET.parse(config_file)
    root = tree.getroot()
    checks = []

    for check in root.findall('check'):
        name = check.get('name')
        check_type = check.get('type')
        if not name or not check_type:
            raise ValueError("Invalid check element")
        if check_type not in ('command', 'sql'):
            raise ValueError(f"Invalid check type: {check_type}")
        checks.append((name, check_type, check.text.strip()))

    return checks

def main(config_file, db_file):
    try:
        config_file = validate_file_path(config_file)
        db_file = validate_file_path(db_file)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    try:
        checks = parse_xml_config(config_file)
    except ET.ParseError as e:
        print(f"Error parsing XML: {e}")
        sys.exit(1)
    except ValueError as e:
        print(f"Error in XML config: {e}")
        sys.exit(1)

    results = []
    for name, check_type, content in checks:
        try:
            if check_type == 'command':
                if not re.match(r'^[a-zA-Z0-9_\-./ ]+$', content):
                    raise ValueError("Invalid command characters")
                results.append(run_command(content))
            elif check_type == 'sql':
                results.append(run_sql_query(content, db_file))
        except ValueError as e:
            print(f"Error processing check '{name}': {e}")
            sys.exit(1)

    result = {"checks": results}
    print(json.dumps(result))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python check_runner.py <config.xml> <database.db>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

import sys
import json
import subprocess
import requests
import os
import time
import logging
from urllib.parse import urlparse

def validate_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_command(command):
    # Basic sanitation: only allow alphanumeric characters, spaces, and common shell operators
    return ''.join(c for c in command if c.isalnum() or c in ' .&|')

def main():
    logging.basicConfig(level=logging.INFO)

    if len(sys.argv) != 2:
        logging.error("Usage: python service_probe.py <config_file>")
        sys.exit(1)

    config_file = sys.argv[1]

    if not os.path.isfile(config_file):
        logging.error("Config file does not exist")
        sys.exit(1)

    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
    except json.JSONDecodeError:
        logging.error("Error decoding JSON from config file")
        sys.exit(1)

    if 'url' not in config or 'command' not in config:
        logging.error("Config file must contain 'url' and 'command' keys")
        sys.exit(1)

    url = config['url']
    command = config['command']

    if not validate_url(url):
        logging.error("Invalid URL provided")
        sys.exit(1)

    command = sanitize_command(command)

    try:
        response = requests.get(url, timeout=10)
