import sys
import os
import ast
import operator

def read_cache(cache_file):
    if not os.path.exists(cache_file):
        return {}
    with open(cache_file, 'r') as f:
        cache = {}
        for line in f:
            expr, value = line.strip().split(' = ')
            cache[expr] = float(value)
        return cache

def write_cache(cache_file, cache):
    with open(cache_file, 'w') as f:
        for expr, value in cache.items():
            f.write(f"{expr} = {value}\n")

class SafeEvaluator(ast.NodeVisitor):
    def __init__(self):
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.USub: operator.neg
        }
        self.result = None

    def visit_BinOp(self, node):
        self.visit(node.left)
        left = self.result
        self.visit(node.right)
        right = self.result
        op_type = type(node.op)
        if op_type in self.operators:
            self.result = self.operators[op_type](left, right)
        else:
            raise ValueError("Unsupported operation")

    def visit_UnaryOp(self, node):
        self.visit(node.operand)
        operand = self.result
        op_type = type(node.op)
        if op_type in self.operators:
            self.result = self.operators[op_type](operand)
        else:
            raise ValueError("Unsupported operation")

    def visit_Num(self, node):
        self.result = node.n

    def visit_Expr(self, node):
        self.visit(node.value)

    def evaluate(self, expr):
        tree = ast.parse(expr, mode='eval')
        self.visit(tree.body)
        return self.result

def evaluate_expression(expr):
    try:
        evaluator = SafeEvaluator()
        return evaluator.evaluate(expr)
    except ZeroDivisionError:
        return "Error: Division by zero"
    except Exception as e:
        return f"Error: {str(e)}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python calc_cache.py <cache_file>")
        sys.exit(1)

    cache_file = sys.argv[1]
    if not os.path.isfile(cache_file):
        print(f"Error: {cache_file} is not a valid file.")
        sys.exit(1)

    cache = read_cache(cache_file)

    for line in sys.stdin:
        expr = line.strip()
        if not expr:
            continue
        if expr in cache:
            print(f"{expr} = {cache[expr]}")
        else:
            value = evaluate_expression(expr)
            print(f"{expr} = {value}")
            cache[expr] = value

    write_cache(cache_file, cache)

if __name__ == "__main__":
    main()

