def is_valid_formula(formula, context):
    allowed_names = set(context.keys())
    allowed_operators = {'+', '-', '*', '/', '//', '%', '**', '(', ')'}
    tokens = re.findall(r'\b\w+\b|[+\-*/%()]+', formula)
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            continue
        if token in allowed_names or token in allowed_operators:
            continue
        return False
    return True

def evaluate_formula(formula, context):
