def main():
    # Check if access.xml exists
    try:
        with open('access.xml', 'r', encoding='utf-8') as f:
            xml_content = f.read()
    except FileNotFoundError:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    # Parse XML
    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError:
        print("ERROR: configuration", file=sys.stderr)
        sys.exit(2)

    # Extract user data into a dictionary: token -> user info
    user_map = {}
    for user_elem in root.findall('user'):
        name = user_elem.get('name')
        token = user_elem.get('token')
        resources = user_elem.get('resources', '').split()
        if token:
            user_map[token] = {
                'name': name,
                'resources': resources
            }

    # Process input lines
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            continue
        token, resource = parts[0], parts[1]

        # Check if token exists and if resource is in resources
        if token in user_map:
            user_info = user_map[token]
            if resource in user_info['resources']:
                decision = 'ALLOW'
            else:
                decision = 'DENY'
        else:
            decision = 'DENY'
            user_info = {'name': 'null'}

        # Print output
        print(decision)

        # Append to access.log
        user_name = user_info['name'] if user_info['name'] else 'null'
        log_line = f"user={user_name} resource={resource} decision={decision}"
        with open('access.log', 'a', encoding='utf-8') as log_file:
            log_file.write(log_line + '\n')

