import sys
import xml.etree.ElementTree as ET
import json
import time

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    try:
        token_id = sys.stdin.readline().strip()
        service_name = sys.stdin.readline().strip()
    except Exception:
        sys.exit(1)

    if not token_id or not service_name:
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except Exception:
        sys.exit(1)

    if root.get('name') is None or root.get('limit') is None:
        sys.exit(1)

    limit = int(root.get('limit'))
    service_name_attr = root.get('name')

    # Check if token ID matches any token element
    token_found = False
    for token_elem in root.findall('.//token'):
        if token_elem.get('id') == token_id:
            token_found = True
            break

    if not token_found:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Check if requested service name matches
    if service_name != service_name_attr:
        print(f"DENY {service_name}")
        sys.exit(0)

    # Process token bucket
    now = time.time()

    try:
        with open(json_path, 'r') as f:
            state = json.load(f)
        tokens = state.get('tokens', 0)
        last_refill = state.get('last_refill', 0)
    except (FileNotFoundError, json.JSONDecodeError):
        tokens = limit
        last_refill = now

    elapsed = now - last_refill
    tokens = min(limit, tokens + elapsed * limit // 60)

    if tokens >= 1:
        print(f"ALLOW {service_name_attr}")
        tokens -= 1
        new_state = {'tokens': tokens, 'last_refill': now}
        with open(json_path, 'w') as f:
            json.dump(new_state, f)
    else:
        print(f"DENY {service_name_attr}")

if __name__ == "__main__":
    main()

import sys
import json
import hashlib
import re

def load_json(file_path):
    with open(file_path, 'r') as f:
        return json.load(f)

def load_text(file_path):
    with open(file_path, 'r') as f:
        return f.read().strip()

def evaluate_expr(expr, attributes):
    try:
        # Replace all occurrences of keys in attributes in the expression
        for key, value in attributes.items():
            expr = expr.replace(f'{{"{key}"}}', str(value))
        # Evaluate the expression
        return eval(expr, {"__builtins__": {}}, {})
    except:
        return False

def compute_signature(payload_str, key_str):
    # Create a hash of the payload string using the key as a salt
    # We use SHA-256 and include the key in the hash
    return hashlib.sha256((payload_str + key_str).encode()).hexdigest()

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    flags_path = sys.argv[1]
    token_path = sys.argv[2]
    key_path = sys.argv[3]

    flags = load_json(flags_path)
    payload_str = load_text(token_path).splitlines()[0]
    signature_str = load_text(token_path).splitlines()[1]
    key_str = load_text(key_path)

    # Validate signature
    expected_signature = compute_signature(payload_str, key_str)
    if signature_str != expected_signature:
        sys.exit(0)

    # Parse payload
    try:
        payload = json.loads(payload_str)
    except json.JSONDecodeError:
        sys.exit(0)

    # Process flags in order of keys
    for flag_name in flags:
        flag = flags[flag_name]
        if payload.get("role") == flag["role"]:
            result = evaluate_expr(flag["expr"], payload.get("attributes", {}))
            print(f"{flag_name}: {result}")

