import sys
import time
import requests
import os
import json

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <path_to_job_ids_file>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]

    # Read API token from environment
    api_token = os.getenv('API_TOKEN')
    if not api_token:
        print("Error: API_TOKEN environment variable is not set", file=sys.stderr)
        sys.exit(1)

    # Read job IDs from file
    job_ids = []
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.rstrip('\n')
                if line:
                    job_ids.append(line)
    except Exception as e:
        print(f"Error reading job IDs file: {e}", file=sys.stderr)
        sys.exit(1)

    if not job_ids:
        sys.exit(0)

    # Rate limiting: at most 5 requests per second
    requests_per_second = 5
    requests_in_second = 0
    current_second = int(time.time())  # Start with current time

    for job_id in job_ids:
        # Wait if we've already sent 5 requests in the current second
        now = int(time.time())
        if now == current_second:
            requests_in_second += 1
            if requests_in_second >= requests_per_second:
                time.sleep(1)
                current_second += 1
                requests_in_second = 1
        else:
            current_second = now
            requests_in_second = 1

        try:
            response = requests.post(
                "https://api.example.com/jobs",
                json={"job_id": job_id},
                headers={"Authorization": f"Bearer {api_token}"}
            )
            if response.status_code == 200:
                print(f"job_id={job_id} status=200", file=sys.stderr)
            else:
                print(f"error job_id={job_id} message={response.status_code}", file=sys.stderr)
        except requests.exceptions.RequestException as e:
            print(f"error job_id={job_id} message={str(e)}", file=sys.stderr)

    sys.exit(0)

