import sys
import os
import json
import base64
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad
import xml.etree.ElementTree as ET
import ast

def encrypt(text, passphrase):
    key = passphrase.encode('utf-8')
    cipher = AES.new(key, AES.MODE_CBC)
    ciphertext = cipher.encrypt(pad(text.encode('utf-8'), AES.block_size))
    return base64.b64encode(cipher.iv + ciphertext).decode('utf-8')

def decrypt(encrypted_text, passphrase):
    key = passphrase.encode('utf-8')
    encrypted_data = base64.b64decode(encrypted_text)
    iv = encrypted_data[:16]
    ciphertext = encrypted_data[16:]
    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size)
    return plaintext.decode('utf-8')

def render_xml(config_file):
    passphrase = os.environ.get('CONFIG_PASSPHRASE')
    if not passphrase:
        raise ValueError("CONFIG_PASSPHRASE environment variable is not set")

    tree = ET.parse(config_file)
    root = tree.getroot()

    settings = {}
    for setting in root.findall('setting'):
        name = setting.get('name')
        value = setting.text
        if not value:
            continue
        decrypted_value = decrypt(value, passphrase)
        if decrypted_value.startswith('{{') and decrypted_value.endswith('}}'):
            expr = decrypted_value[2:-2]
            try:
                resolved_value = ast.literal_eval(expr)
            except (SyntaxError, ValueError):
                resolved_value = expr
        else:
            resolved_value = decrypted_value
        settings[name] = resolved_value

    return json.dumps(settings, indent=2)

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    action = sys.argv[1]

    if action == 'encrypt':
        if sys.stdin.isatty():
            sys.exit(1)
        text = sys.stdin.read()
        passphrase = os.environ.get('CONFIG_PASSPHRASE')
        if not passphrase:
            sys.exit(1)
        encrypted = encrypt(text, passphrase)
        print(encrypted)

    elif action == 'render':
        if len(sys.argv) != 3:
            sys.exit(1)
        config_file = sys.argv[2]
        if not os.path.exists(config_file):
            sys.exit(1)
        result = render_xml(config_file)
        print(result)

if __name__ == '__main__':
    main()

import sys
import json
import re
import xml.etree.ElementTree as ET

def evaluate_expression(expr, field_values):
    try:
        # Replace field names with their values
        expr = expr.replace('(', ' ( ').replace(')', ' ) ').replace(' ', '')
        expr = re.sub(r'(\w+)', lambda m: str(field_values.get(m.group(1), None)), expr)

        # Evaluate the expression
        # We need to handle the case where field names are used in expressions
        # We'll use eval with a safe environment
        # But we must ensure that only numbers and previously defined field names are used
        # We'll create a safe eval environment
        safe_env = {}
        for name, value in field_values.items():
            safe_env[name] = value

        # Evaluate the expression
        result = eval(expr, {"__builtins__": {}}, safe_env)

        # Check if result is a number
        if isinstance(result, (int, float)):
            return result
        else:
            return None
    except:
        return None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except Exception as e:
        sys.stderr.write(f"ERROR parsing configuration file: {e}\n")
        sys.exit(1)

    field_values = {}
    field_names = []

    # Process each field in document order
    for field_elem in root.findall('field'):
        name = field_elem.get('name')
        expr = field_elem.get('expr')

        if not name or not expr:
            sys.stderr.write(f"ERROR {name}\n")
            continue

        # Evaluate the expression
        value = evaluate_expression(expr, field_values)

        if value is not None:
            field_values[name] = value
            sys.stderr.write(f"INFO {name} {value}\n")
        else:
            sys.stderr.write(f"ERROR {name}\n")

    # Output JSON to stdout
    result = {name: value for name, value in field_values.items()}
    print(json.dumps(result))

    # Exit status
