import sys
import re
from xml.etree import ElementTree as ET
from threading import Lock, Thread
from queue import Queue

def evaluate_expression(expr, w, h):
    try:
        # Replace w and h with their values
        expr = expr.replace('w', str(w)).replace('h', str(h))
        # Evaluate the expression safely
        result = eval(expr, {"__builtins__": {}}, {})
        return int(result)
    except:
        return 0

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()

        if root.tag != 'transform':
            sys.exit(1)

        max_concurrency = int(root.get('max-concurrency'))
        if max_concurrency <= 0:
            sys.exit(1)

        expr_elem = root.find('expr')
        if expr_elem is None or expr_elem.text is None:
            sys.exit(1)

        expression = expr_elem.text.strip()

        # Use a thread pool to process input lines
        input_queue = Queue()
        output_queue = Queue()
        results = []

        # Create worker threads
        threads = []
        for _ in range(max_concurrency):
            thread = Thread(target=worker, args=(input_queue, output_queue, expression, max_concurrency))
            thread.daemon = True
            thread.start()
            threads.append(thread)

        # Process input lines
        for line in sys.stdin:
            line = line.strip()
            if line:
                match = re.match(r'w=(\d+) h=(\d+)', line)
                if match:
                    w, h = int(match.group(1)), int(match.group(2))
                    input_queue.put((w, h))

        # Wait for all input to be processed
        for _ in range(max_concurrency):
            input_queue.put(None)  # Signal end of input

        # Collect results
        while True:
            try:
                result = output_queue.get(timeout=1)
                if result is None:
                    break
                results.append(result)
            except:
                break

        # Output results
        for result in results:
            print(result)

    except Exception as e:
        sys.exit(1)

def worker(input_queue, output_queue, expression, max_concurrency):
    while True:
        item = input_queue.get()
        if item is None:
            output_queue.put(None)
            break

        w, h = item
        result = evaluate_expression(expression, w, h)
        output_queue.put(result)
        input_queue.task_done()

if __name__ == '__main__':
    main()

import sys
import os
import hashlib
import time
from collections import defaultdict

DEDUP_KEY = os.getenv('DEDUP_KEY', '')

def compute_hash(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
            # Create a hash using the DEDUP_KEY as a salt
            key = DEDUP_KEY.encode() if DEDUP_KEY else b''
            hash_obj = hashlib.sha256()
            hash_obj.update(key)
            hash_obj.update(data)
            return hash_obj.hexdigest()[:32].lower()
    except Exception as e:
        return None

def create_marker(path, hash_val):
    marker_name = f"{hash_val}.marker"
    marker_path = os.path.join(os.getcwd(), marker_name)

    # Check rate limiting: no more than 10 markers in any 1-second window
    now = time.time()
    if 'marker_times' not in globals():
        marker_times = defaultdict(list)
    else:
        marker_times = globals()['marker_times']

    # Check if we already have a marker for this hash in the current second
    current_second = int(now)
    if marker_times[hash_val] and current_second == marker_times[hash_val][0]:
        # If we already have 10 markers in this second, skip
        if len(marker_times[hash_val]) >= 10:
            return False

    # Add the current time to the list for this hash
    marker_times[hash_val].append(current_second)

    # If we have more than 10 entries in this second, remove the oldest
    if len(marker_times[hash_val]) > 10:
        marker_times[hash_val].pop(0)

    # Create the marker file
    try:
        with open(marker_path, 'w') as f:
            f.write('')  # Empty file
        return True
    except Exception as e:
        return False

def main():
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            paths.append(line)

    marker_count = 0
    marker_times = defaultdict(list)

    for path in paths:
        try:
            hash_val = compute_hash(path)
            if not hash_val:
                print(f"ERROR {path}: failed to read file", file=sys.stderr)
                continue

            if create_marker(path, hash_val):
                marker_count += 1
        except Exception as e:
            print(f"ERROR {path}: {str(e)}", file=sys.stderr)
            continue

    print(f"OK {marker_count}")

if __name__ == "__main__":
    main()

import sys
import subprocess
import threading
from queue import Queue
import os

def ping_host(hostname, result_queue):
    try:
        result = subprocess.run(
            ['ping', '-c', '1', hostname],
            capture_output=True,
            text=True,
            timeout=5
        )
        result_queue.put((hostname, result.returncode, result.stdout))
    except subprocess.TimeoutExpired:
        result_queue.put((hostname, 1, "Timeout"))
    except Exception as e:
        result_queue.put((hostname, 1, f"Error: {str(e)}"))

def main():
    input_lines = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            input_lines.append(line)

    if not input_lines:
        return

    result_queue = Queue()
    threads = []
    max_concurrent = 4

    # Start ping threads
    for i, hostname in enumerate(input_lines):
        thread = threading.Thread(target=ping_host, args=(hostname, result_queue))
        thread.start()
        threads.append(thread)

        # Limit concurrent threads
        if len(threads) >= max_concurrent:
            # Wait for one to finish before starting another
            while len([t for t in threads if t.is_alive()]) >= max_concurrent:
                time.sleep(0.1)

    # Wait for all threads to complete
    for thread in threads:
        thread.join()

    # Collect results
    results = []
    while not result_queue.empty():
        hostname, status, output = result_queue.get()
        results.append((hostname, "OK" if status == 0 else "FAILED", output))

    # Write report.html
    try:
        with open('report.html', 'w') as f:
            f.write('<html><body><table>\n')
            f.write('<tr><th>Host</th><th>Status</th><th>Output</th></tr>\n')
            for row in results:
                f.write(f'<tr><td>{row[0]}</td><td>{row[1]}</td><td>{row[2]}</td></tr>\n')
            f.write('</table></body></html>\n')
    except Exception as e:
        print(f"Error writing report.html: {str(e)}", file=sys.stderr)
        sys.exit(1)

    # Write run.log
    try:
        with open('run.log', 'a') as f:
            for row in results:
                f.write(f"{row[0]} {row[1]}\n")
    except Exception as e:
        print(f"Error writing run.log: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import re
import json

def parse_expression(expr, env):
    # Parse and evaluate expression using provided environment
    try:
        # Replace key references with their values
        for key, value in env.items():
            expr = expr.replace(f"{key}", str(value))

        # Use safe evaluation with ast.literal_eval to avoid code injection
        import ast
        # Validate that the expression is a simple literal or arithmetic expression
        # Only allow literals, integers, and basic operations (addition, subtraction, multiplication, division)
        node = ast.parse(expr, mode='eval')

        # Validate the AST node structure
        if not isinstance(node.body, (ast.Num, ast.BinOp)):
            raise ValueError("Expression contains unsupported operations or structure")

        # Check for only allowed operations
        allowed_ops = (ast.Add, ast.Sub, ast.Mult, ast.Div)
        if isinstance(node.body, ast.BinOp):
            if not isinstance(node.body.op, allowed_ops):
                raise ValueError("Expression contains unsupported operation")

        # Evaluate the expression safely
        result = eval(expr, {"__builtins__": {}}, env)
        if isinstance(result, int):
            return result
        else:
            raise ValueError(f"Expression evaluated to non-integer: {result}")
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    path = sys.argv[1]

    # Read the file
    try:
        with open(path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
    except FileNotFoundError:
        sys.exit(1)

    # Environment to store key-value pairs
    env = {}

    # Process each line
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Match key = expr pattern
        match = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$', line)
        if not match:
            continue

        key = match.group(1)
        expr = match.group(2)

        # Validate expression syntax
        # The expression should only contain integers, operators, and previously defined keys
        # We'll use a simple parser that checks for valid tokens
        try:
            # Evaluate the expression safely using ast.literal_eval
            import ast
            # Parse the expression to ensure it's a valid literal or simple arithmetic
            node = ast.parse(expr, mode='eval')

            # Validate the AST node structure
            if isinstance(node.body, ast.Num):
                # Simple number
                value = node.body.n
                if isinstance(value, int):
                    env[key] = value
                else:
                    raise ValueError(f"Expression evaluated to non-integer: {value}")
            elif isinstance(node.body, ast.BinOp):
                # Binary operation
                op = node.body.op
                left = node.body.left
                right = node.body.right

                # Validate operation type
                allowed_ops = (ast.Add, ast.Sub, ast.Mult, ast.Div)
                if not isinstance(op, allowed_ops):
                    raise ValueError("Expression contains unsupported operation")

                # Evaluate left and right operands
                left_val = evaluate_ast(left, env)
                right_val = evaluate_ast(right, env)

                # Perform operation
                if isinstance(op, ast.Add):
                    result = left_val + right_val
                elif isinstance(op, ast.Sub):
                    result = left_val - right_val
                elif isinstance(op, ast.Mult):
                    result = left_val * right_val
                elif isinstance(op, ast.Div):
                    if right_val == 0:
                        raise ValueError("Division by zero")
                    result = left_val / right_val

                if isinstance(result, int):
                    env[key] = result
                else:
                    raise ValueError(f"Expression evaluated to non-integer: {result}")
            else:
                raise ValueError("Expression contains unsupported structure")
        except Exception as e:
            sys.exit(f"Error parsing line: {line} - {e}")

    # Output the result as JSON
    print(json.dumps(env, indent=None))

def evaluate_ast(node, env):
    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.BinOp):
        op = node.op
        left = evaluate_ast(node.left, env)
        right = evaluate_ast(node.right, env)

        if isinstance(op, ast.Add):
            return left + right
        elif isinstance(op, ast.Sub):
            return left - right
        elif isinstance(op, ast.Mult):
            return left * right
        elif isinstance(op, ast.Div):
            if right == 0:
                raise ValueError("Division by zero")
            return left / right
    else:
        # Handle key references
        key = node.id
        if key in env:
            return env[key]
        else:
            raise ValueError(f"Undefined key: {key}")

