    template_path = sys.argv[2]

    # Send HTTP GET request to the URL with a timeout
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
    except requests.exceptions.RequestException as e:
        sys.exit(1)
    except json.JSONDecodeError as e:
        sys.exit(1)

    # Read the template file
    try:
        with open(template_path, 'r', encoding='utf-8') as file:
            template_content = file.read()
    except FileNotFoundError:
        sys.exit(1)

    # Replace each {{ expr }} placeholder with the evaluated result
    result = template_content
    pattern = r'\{\{([^}]+)\}\}'

    def replace_match(match):
        expr = match.group(1)
        try:
            # Replace variable names like "price" with their values from the JSON data
            expr = expr.strip()
            for var_name in data.keys():
                expr = expr.replace(f'{{{{ {var_name} }}}}', str(data[var_name]))

            # Remove spaces and handle simple expressions
            expr = expr.replace(' ', '')

            # Use safe evaluation with only allowed variables from data
            # We create a local namespace with only the data values
            local_vars = {k: v for k, v in data.items()}

            # Use ast.literal_eval for safe evaluation of expressions
            import ast
            # Validate that the expression only contains literals and supported operations
            # We only allow safe operations like +, -, *, /, and comparisons
            # We also ensure that only data variables are used
            try:
                # Parse the expression to ensure it's safe
                node = ast.parse(expr, mode='eval')
                # Validate that the expression only uses safe operations and variables
                # We only allow variables from local_vars and basic arithmetic
                for node in ast.walk(node):
                    if isinstance(node, ast.Name):
                        if node.id not in local_vars:
                            raise ValueError(f"Unknown variable: {node.id}")
                    elif isinstance(node, ast.BinOp):
                        if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                            raise ValueError(f"Unsupported operation: {type(node.op).__name__}")
                # Evaluate safely
                result = ast.literal_eval(expr, {"__builtins__": {}}, local_vars)
                return str(result)
            except (SyntaxError, ValueError) as e:
                sys.exit(1)
        except Exception as e:
            sys.exit(1)

    result = re.sub(pattern, replace_match, result)
    print(result)

