def download_url(url, n):
    try:
        response = requests.get(url, timeout=30)
        if response.status_code // 100 == 2:
            filename = f"{n}.dat"
            with open(filename, 'wb') as f:
                f.write(response.content)
            return filename, response.status_code
        else:
            return None, response.status_code
    except Exception:
        return None, -1

def run_command(filename, n, command):
    try:
        # Use subprocess to safely execute the command without shell injection
        import subprocess
        # Split the command into components to avoid shell injection
        cmd_parts = command.split()
        if not cmd_parts:
            return -1
        # Execute the command with the filename as an argument
        result = subprocess.run(cmd_parts + [filename], capture_output=True, text=True)
        return result.returncode
    except Exception:
        return -1

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    urls_file = sys.argv[1]
