    main()

import sys
import re
import logging
from typing import Dict, Any

def parse_assignment(line: str) -> tuple[str, int]:
    line = line.strip()
    if not line:
        return None, None
    match = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)=(-?\d+)$', line)
    if not match:
        raise ValueError(f"Invalid assignment format: {line}")
    name = match.group(1)
    value = int(match.group(2))
    return name, value

def evaluate_expression(expr: str, variables: Dict[str, int]) -> Any:
    try:
        # Replace variables in the expression
        expr = expr.strip()
        # Remove whitespace inside braces
        expr = re.sub(r'\s+', '', expr)
        # Replace {{var}} with variables
        # Use safe evaluation with only allowed operations and variables
        # We'll use ast.literal_eval for safe evaluation of expressions
        import ast
        # Validate that the expression only contains safe operations and variables
        try:
            # Parse the expression to ensure it's safe
            node = ast.parse(expr, mode='eval')
            # Check that all nodes are safe
            for node in ast.walk(node):
                if isinstance(node, (ast.BinOp, ast.UnaryOp, ast.Compare, ast.BoolOp, ast.Constant)):
                    continue
                elif isinstance(node, ast.Name):
                    # Check if the name is in the allowed variables
                    if node.id not in variables:
                        raise ValueError(f"Unknown variable: {node.id}")
                else:
                    raise ValueError(f"Unsupported expression node: {type(node)}")
            # Evaluate safely
            result = eval(expr, {"__builtins__": {}}, variables)
            return result
        except Exception as e:
            raise ValueError(f"Invalid expression: {expr} -> {str(e)}")
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {expr} -> {str(e)}")

def render_template(template: str, variables: Dict[str, int]) -> str:
    # Find all placeholders: {{ ... }}
    placeholders = re.finditer(r'\{\{([^}]*)\}\}', template)
    result = template
    log_lines = []

    for match in placeholders:
        expr = match.group(1)
        placeholder_text = match.group(0)

        try:
            # Evaluate the expression safely
            value = evaluate_expression(expr, variables)
            # Replace the placeholder with the result
            result = result.replace(placeholder_text, str(value))
            log_lines.append(f"{placeholder_text} -> {value}")
        except Exception as e:
            log_lines.append(f"{placeholder_text} ERROR {str(e)}")

    # Write log lines
    with open('render.log', 'a') as log_file:
        for line in log_lines:
            log_file.write(line + '\n')

    return result

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python render.py <template_file_path>\n")
        sys.exit(1)

    template_path = sys.argv[1]

    # Read template file
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            template = f.read()
    except Exception as e:
        sys.stderr.write(f"Error reading template file: {e}\n")
        sys.exit(1)

    # Read variable assignments from stdin
    variables: Dict[str, int] = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            name, value = parse_assignment(line)
            variables[name] = value
        except Exception as e:
            sys.stderr.write(f"Error parsing assignment: {line} -> {e}\n")
            continue

    # Render the template
    rendered = render_template(template, variables)
    print(rendered)

if __name__ == "__main__":
    main()

