def copy_file(source_path, dest_path, result_queue):
    try:
        # Validate source path: must be absolute and within a trusted directory
        if not os.path.isabs(source_path):
            raise ValueError("Source path must be absolute")

        # Validate destination path: must be within dest_dir and not traverse
        dest_dir = os.path.dirname(dest_path)
        if not os.path.commonpath([dest_dir, os.path.abspath(source_path)]) == dest_dir:
            raise ValueError("Destination path traversal detected")

        # Check if source file exists and is readable
        if not os.path.exists(source_path):
            raise FileNotFoundError(f"Source file not found: {source_path}")
        if not os.access(source_path, os.R_OK):
            raise PermissionError(f"Source file not readable: {source_path}")

        # Check if destination directory exists and is writable
        dest_dir_path = os.path.dirname(dest_path)
        if not os.path.exists(dest_dir_path):
            raise FileNotFoundError(f"Destination directory not found: {dest_dir_path}")
        if not os.access(dest_dir_path, os.W_OK):
            raise PermissionError(f"Destination directory not writable: {dest_dir_path}")

        # Perform the copy
        with open(source_path, 'rb') as src, open(dest_path, 'wb') as dst:
            dst.write(src.read())

        result_queue.put(True)

    except Exception as e:
        # Log error (in production, this would go to a secure logging system)
        result_queue.put(False)

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    dest_dir = sys.argv[1]
    max_concurrent = int(sys.argv[2])

    # Validate destination directory
    if not os.path.exists(dest_dir):
        sys.exit(1)
    if not os.path.isdir(dest_dir):
        sys.exit(1)
    if max_concurrent < 1:
        sys.exit(1)

    # Validate that dest_dir is a trusted, absolute path
    if not os.path.isabs(dest_dir):
        sys.exit(1)

    input_queue = Queue()
    result_queue = Queue()
    completed_count = 0
    active_count = 0
    copy_threads = []

    # Read input until EOF
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split('\t', 1)  # Split on first tab only
        if len(parts) != 2:
            continue  # Skip malformed lines

        source_path, dest_name = parts
        source_path = source_path.strip()
        dest_name = dest_name.strip()

        # Validate source and destination names
        if not source_path or not dest_name:
            continue

        # Ensure source and dest names are safe (no path traversal)
        if '..' in source_path or '../' in source_path or '/' in source_path:
            continue
        if '..' in dest_name or '../' in dest_name or '/' in dest_name:
            continue

        dest_path = os.path.join(dest_dir, dest_name)

        # Validate that the destination path is within dest_dir
        if not os.path.commonpath([dest_dir, dest_path]) == dest_dir:
            continue

        input_queue.put((source_path, dest_path))

    # Start copy operations
    def worker():
        nonlocal completed_count
        while True:
            try:
                source_path, dest_path = input_queue.get(timeout=1)
                if input_queue.empty():
                    break
                # Start copy in background
                copy_file(source_path, dest_path, result_queue)
                input_queue.task_done()
            except Exception as e:
                # Handle worker errors gracefully
                input_queue.task_done()
                continue

    # Start worker threads
    for _ in range(max_concurrent):
        t = threading.Thread(target=worker)
        t.daemon = True
        t.start()
        copy_threads.append(t)

    # Process completed copies
    while True:
        try:
            result = result_queue.get(timeout=1)
            if result is None:
                break
            if result:
                completed_count += 1
            result_queue.task_done()
        except Exception:
            break

    # Wait for all threads to finish
    for t in copy_threads:
        t.join()

