    file_path = Path(xml_file_path)
    if not file_path.is_absolute():
        # Resolve relative path to current directory to prevent traversal
        file_path = Path.cwd() / file_path
    if not file_path.is_file():
        sys.exit(1)

    # Ensure the file path is within a trusted directory (e.g., current directory)
    trusted_dir = Path.cwd()
    if not file_path.parent == trusted_dir:
        sys.exit(1)

    try:
        with open(xml_file_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()

        root = ET.fromstring(xml_content)
        cert_pem = root.text.strip() if root.text else ""

        if not cert_pem:
            sys.exit(1)

        # Validate PEM structure: must be valid base64 and start with proper PEM header
        if not cert_pem.startswith('-----BEGIN CERTIFICATE-----'):
            sys.exit(1)

        # Parse the PEM-encoded certificate with strict validation
        try:
            cert = x509.load_pem_x509_certificate(cert_pem.encode('utf-8'))

            # Validate certificate validity (not before, not after, and not expired)
            current_time = x509.datetime.datetime.now()
            if cert.not_valid_before > current_time or cert.not_valid_after < current_time:
                sys.exit(1)

            # Validate certificate signature (trusted chain is not required, but signature must be valid)
            # The cryptography library will validate the signature internally if the certificate is well-formed

            # Extract the common name from the subject
            subject = cert.subject
            common_name = None

            for name in subject.get_attributes_for_oid(x509.oid.NameOID.COMMON_NAME):
                common_name = str(name.value)
                break

            if common_name:
