import sys
import os
import re
import hashlib

def parse_expression(expression):
    # Validate expression using a strict regex pattern
    # Only allows digits, +, -, *, (, ), and spaces
    pattern = r'^\s*([0-9]+(\s*[+\-*/]\s*[0-9]+(\s*[\(\)]*\s*[+\-*/]\s*[0-9]+(\s*[\(\)]*)*)*)|\s*[\(\)]\s*[0-9]+(\s*[+\-*/]\s*[0-9]+(\s*[\(\)]*\s*[+\-*/]\s*[0-9]+(\s*[\(\)]*)*)*)\s*)\s*$'
    if not re.match(pattern, expression.strip()):
        raise ValueError("Invalid expression: contains unsupported tokens")

    # Remove all whitespace
    expr = re.sub(r'\s+', '', expression)

    # Validate that the expression is well-formed using a stack-based parser
    try:
        # Use a simple recursive descent parser to validate parentheses and structure
        stack = 0
        for char in expr:
            if char == '(':
                stack += 1
            elif char == ')':
                stack -= 1
                if stack < 0:
                    raise ValueError("Invalid expression: unmatched parentheses")
        if stack != 0:
            raise ValueError("Invalid expression: unmatched parentheses")

        # Evaluate the expression safely using a restricted environment
        # We use a custom parser to avoid eval()
        return evaluate_expression(expr)
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def evaluate_expression(expr):
    # Use a simple recursive descent parser to evaluate arithmetic expressions
    # This avoids eval() and prevents arbitrary code execution

    def parse_number(s, pos):
        num = ""
        while pos < len(s) and s[pos].isdigit():
            num += s[pos]
            pos += 1
        return int(num), pos

    def parse_expression(s, pos):
        left, pos = parse_term(s, pos)
        while pos < len(s) and s[pos] in ['+', '-']:
            op = s[pos]
            pos += 1
            right, pos = parse_term(s, pos)
            if op == '+':
                left += right
            else:
                left -= right
        return left, pos

    def parse_term(s, pos):
        left, pos = parse_factor(s, pos)
        while pos < len(s) and s[pos] in ['*', '/']:
            op = s[pos]
            pos += 1
            right, pos = parse_factor(s, pos)
            if op == '*':
                left *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                left //= right
        return left, pos

    def parse_factor(s, pos):
        if pos >= len(s):
            raise ValueError("Unexpected end of expression")
        if s[pos] == '(':
            pos += 1
            result, pos = parse_expression(s, pos)
            if pos >= len(s) or s[pos] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return result, pos
        else:
            num, pos = parse_number(s, pos)
            return num, pos

    try:
        result, _ = parse_expression(expr, 0)
        return result
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def generate_tag(value, secret):
    # Convert value to hex string, remove '0x' prefix, and pad to 16 characters
    value_hex = hex(value)[2:].zfill(16)

    # Use a secure, cryptographically strong hash function with proper input
    # Combine value hex and secret, then hash to produce a 16-character tag
    combined = value_hex + secret
    hash_obj = hashlib.sha256(combined.encode('utf-8'))
    return hash_obj.hexdigest()[:16].lower()

def main():
    secret = os.environ.get('RENDERER_KEY')
    if not secret or secret == '':
        print("RENDERER_KEY is not set", file=sys.stderr)
        sys.exit(2)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        try:
            value = parse_expression(line)
            tag = generate_tag(value, secret)
            print(f"{value}|{tag}")
        except ValueError as e:
            # Log error but do not exit with status 1 to avoid breaking the pipeline
            print(f"Error evaluating expression: {e}", file=sys.stderr)
