        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()
    except (PermissionError, FileNotFoundError, OSError, IOError) as e:
        # Only catch specific, expected exceptions
        return None

def is_safe_path(path):
    """Check if the path contains path traversal sequences like '../' or '//'."""
    path = Path(path)
    # Check for path traversal attempts
    if '..' in str(path) or '~' in str(path) or ':' in str(path) and str(path).split(':')[0] == '':
        return False
    # Ensure the path is within the current directory
    if path.is_absolute():
        # If absolute, ensure it's not pointing outside the current directory
        return path.parts[0] == ''
    return True

def main():
    input_file = "input_paths.txt"
    output_file = "digest.log"

    processed_count = 0
    error_count = 0

    # Read paths from input_paths.txt
    try:
        with open(input_file, 'r', encoding='utf-8') as f:
            paths = [line.strip() for line in f if line.strip()]
    except Exception as e:
        # Log error if input file cannot be read
        with open(output_file, 'w') as log:
            log.write(f"ERROR reading input file: {e}\n")
        return

    # Write to digest.log with proper permissions and safety
    try:
        with open(output_file, 'w', encoding='utf-8') as log:
            for path in paths:
                # Validate path for traversal and existence
                if not is_safe_path(path):
                    log.write(f"ERROR {path}\n")
                    error_count += 1
                    continue

                if os.path.exists(path) and os.path.isfile(path):
                    digest = compute_hex_digest(path)
                    if digest:
                        log.write(f"{path}\t{digest}\n")
                        processed_count += 1
                    else:
                        log.write(f"ERROR {path}\n")
                        error_count += 1
                else:
                    log.write(f"ERROR {path}\n")
                    error_count += 1

            # Final summary line
            log.write(f"Completed: {processed_count} processed, {error_count} errors")

    except Exception as e:
        # In case of write failure, log error
        with open(output_file, 'a', encoding='utf-8') as log:
            log.write(f"ERROR writing log: {e}\n")

