import sys
import json
import re
import ast
import os

def safe_eval_expression(expr, json_data):
    # Validate expression syntax using AST
    try:
        # Parse the expression to ensure it's a valid arithmetic expression
        # Only allow integers, variables from json_data, and basic arithmetic
        tree = ast.parse(expr, mode='eval')

        # Validate the AST nodes
        for node in ast.walk(tree):
            if isinstance(node, (ast.Num, ast.Constant)):
                continue
            elif isinstance(node, ast.Name):
                # Check if the name is a valid variable from json_data
                if node.id not in json_data:
                    return None
            elif isinstance(node, ast.BinOp):
                # Only allow +, -, *
                if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult)):
                    return None
            elif isinstance(node, ast.UnaryOp):
                # Only allow + and - (positive/negative)
                if not isinstance(node.op, (ast.USub, ast.UAdd)):
                    return None
            elif isinstance(node, ast.Call):
                # No function calls allowed
                return None
            elif isinstance(node, ast.Attribute):
                # No attribute access allowed
                return None
            elif isinstance(node, ast.Compare):
                # No comparisons allowed
                return None
            elif isinstance(node, ast.BoolOp):
                # No boolean operations allowed
                return None
            elif isinstance(node, ast.List):
                # No lists allowed
                return None
            elif isinstance(node, ast.Dict):
                # No dictionaries allowed
                return None
            elif isinstance(node, ast.Subscript):
                # No indexing allowed
                return None

        # Replace variables in the expression with their values
        # We need to evaluate the expression safely
        # Create a safe environment with only the variables from json_data
        safe_env = {key: value for key, value in json_data.items()}

        # Evaluate the expression using the safe environment
        result = eval(compile(tree, '<string>', 'eval'), safe_env)

        # Check if result is an integer
        if not isinstance(result, int):
            return None

        return result

    except (SyntaxError, ValueError, TypeError):
        return None

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    template_path = sys.argv[1]
    json_path = sys.argv[2]

