import sys
import json
import subprocess
import os
import xml.etree.ElementTree as ET
from pathlib import Path

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_file_path = sys.argv[1]

    try:
        tree = ET.parse(xml_file_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

    # Define safe character sets and validation rules
    SAFE_NAME_CHARS = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-')

    for job in root.findall('job'):
        name = job.get('name')
        command = job.get('command')

        # Validate name attribute
        if not name:
            continue

        # Validate command attribute
        if not command:
            continue

        # Sanitize name to prevent path traversal
        sanitized_name = ""
        for char in name:
            if char in SAFE_NAME_CHARS:
                sanitized_name += char
            else:
                sanitized_name += "_"

        # Ensure name is not empty after sanitization
        if not sanitized_name:
            continue

        # Create a safe cache file name
        cache_file = f"{sanitized_name}.cache"

        # Validate cache file path to prevent traversal
        cache_path = Path(cache_file)
        if not cache_path.is_absolute() and not cache_path.parts[0] == '.':
            # If the path is not absolute and doesn't start with current directory, reject
            continue

        # Check if cache file exists and is readable
        if cache_path.exists():
            try:
                with open(cache_path, 'r', encoding='utf-8') as f:
                    cache_data = json.load(f)
                result = cache_data.get('output')
                if result is None:
                    result = ""
            except (json.JSONDecodeError, IOError) as e:
                # Handle corrupted or invalid cache file gracefully
                result = ""
        else:
            # Run the command safely with shell=False and validated arguments
            try:
                # Validate command: only allow safe characters and avoid shell metacharacters
                safe_command = []
                for arg in command.split():
                    # Validate each argument
                    arg_sanitized = ""
                    for char in arg:
                        if char in SAFE_NAME_CHARS or char in ' \t':
                            arg_sanitized += char
                        else:
                            arg_sanitized += "_"
                    if arg_sanitized.strip():
                        safe_command.append(arg_sanitized.strip())

                if not safe_command:
                    result = ""
                else:
                    result = subprocess.run(
                        safe_command,
                        capture_output=True,
                        text=True,
                        check=False
                    ).stdout or ""

            except subprocess.CalledProcessError as e:
                result = e.stdout or e.stderr or ""
            except Exception as e:
                result = str(e)

        # Write result to cache file with proper error handling
        try:
            cache_data = {"output": result}
            with open(cache_path, 'w', encoding='utf-8') as f:
                json.dump(cache_data, f, ensure_ascii=False)
        except (IOError, OSError) as e:
            # Log error but continue processing other jobs
            pass

        # Print output
        print(f"--- {sanitized_name} ---")
        print(result)
        print()

