import re
from pathlib import Path
from typing import List, Dict, Any

def evaluate_expression(expr: str) -> int:
    """Safely evaluate a simple arithmetic expression with * and +, where * has higher precedence."""
    if not expr or not expr.strip():
        return 0

    # Validate that the expression contains only digits, +, and *
    if not re.match(r'^\d+(\s*(\*|\+)\s*\d+)*$', expr.replace(' ', '')):
        return 0

    # Split by * first (higher precedence)
    parts = re.split(r'(\*|\+)', expr)
    tokens = []
    i = 0
    while i < len(parts):
        if parts[i] == '*':
            tokens.append(('*', parts[i+1]))
            i += 2
        else:
            tokens.append((parts[i], ''))
            i += 1

    # Evaluate multiplication first
    current_product = 1
    current_sum = 0
    i = 0
    while i < len(tokens):
        if tokens[i][0] == '*':
            if i + 1 < len(tokens):
                try:
                    next_val = int(tokens[i+1][0])
                    current_product *= next_val
                except (ValueError, IndexError):
                    current_product = 1
                i += 2
            else:
                i += 1
        else:
            if tokens[i][0].isdigit():
                try:
                    current_sum += int(tokens[i][0])
                except ValueError:
                    current_sum += 0
            i += 1

    return current_sum + current_product

def replace_placeholders(command: str, expr_values: Dict[str, int]) -> str:
    """Replace {{expr}} placeholders with evaluated values. Only safe expressions are used."""
    result = command
    for key, value in expr_values.items():
        # Ensure the key is safe (only alphanumeric, no shell metacharacters)
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', key):
            continue
        # Replace with the evaluated value
        result = result.replace(f"{{{key}}}", str(value))
    return result

def run_command(command: str) -> Dict[str, Any]:
    """Run a command safely without shell injection."""
    try:
        # Split the command into arguments to avoid shell injection
        # This ensures that only valid arguments are passed
        # We assume the command is a simple shell command with no shell metacharacters
        # If the command contains spaces, we split by space and validate
        parts = command.strip().split()
        if not parts:
            return {
                "command": command,
                "output": "Empty command",
                "exit_code": 1
            }

        # Validate that the command does not contain shell metacharacters
        # This is a basic check - we assume the command is safe if it's a simple command
        # with no pipes, redirections, or other shell features
        for part in parts:
            if any(metachar in part for metachar in [';', '|', '&', '>', '<', '$(', '$)', '$', '&&', '||']):
                return {
                    "command": command,
                    "output": "Command contains unsafe shell metacharacters",
                    "exit_code": 1
                }

        # Run the command using a list of arguments
        result = subprocess.run(
            parts,
            capture_output=True,
            text=True,
            timeout=30,
            shell=False
        )
        return {
            "command": command,
            "output": result.stdout + result.stderr,
            "exit_code": result.returncode
        }
    except subprocess.TimeoutExpired:
        return {
            "command": command,
            "output": "Command timed out",
            "exit_code": -1
        }
    except Exception as e:
        return {
            "command": command,
            "output": f"Error: {str(e)}",
            "exit_code": -1
        }

def main():
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing file path"}))
        sys.exit(1)

    file_path = sys.argv[1]
    concurrency = 1

    # Parse concurrency argument
    i = 2
    while i < len(sys.argv):
        if sys.argv[i] == '--concurrency':
            if i + 1 < len(sys.argv):
                try:
                    concurrency = int(sys.argv[i + 1])
                    if concurrency <= 0:
                        concurrency = 1
                except ValueError:
                    concurrency = 1
                i += 2
            else:
                i += 1
        else:
            i += 1

    # Validate file path
    try:
        path = Path(file_path)
        if not path.is_file():
            print(json.dumps({"error": f"File not found: {file_path}"}))
            sys.exit(1)

        # Check for path traversal attempts
        if '..' in str(path) or '~' in str(path):
            print(json.dumps({"error": "Invalid file path: path traversal detected"}))
            sys.exit(1)

        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except PermissionError:
        print(json.dumps({"error": f"Permission denied: {file_path}"}))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({"error": f"Error reading file: {str(e)}"}))
        sys.exit(1)

    # Process each line
    commands = []
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Extract expressions like {{expr}} and evaluate them
        expr_matches = re.findall(r'\{\{(\w+)\}\}', line)
        expr_values = {}

        for expr in expr_matches:
            # Validate expression identifier
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', expr):
                expr_values[expr] = 0
                continue

            # Evaluate the expression safely
            try:
                value = evaluate_expression(expr)
                expr_values[expr] = value
            except Exception:
                expr_values[expr] = 0

        # Replace placeholders in the command
        processed_command = replace_placeholders(line, expr_values)
        commands.append(processed_command)

    # Run commands with concurrency
    results = []
    with subprocess.Popen(['python3'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE) as proc:
        # Use a thread pool to run commands in parallel
        from concurrent.futures import ThreadPoolExecutor, as_completed
        with ThreadPoolExecutor(max_workers=concurrency) as executor:
            future_to_command = {executor.submit(run_command, cmd): cmd for cmd in commands}
            for future in as_completed(future_to_command):
                result = future.result()
                results.append(result)

    # Output JSON objects
    for result in results:
        print(json.dumps(result))

