import sys
import subprocess
import os

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    manifest_path = sys.argv[1]
    max_parallel = int(sys.argv[2])

    if max_parallel <= 0:
        sys.exit(1)

    # Read and filter manifest lines
    with open(manifest_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Filter out empty or whitespace-only lines
    commands = []
    for line in lines:
        stripped = line.strip()
        if stripped:
            # Validate command content: only allow safe, non-injectable tokens
            # Split by whitespace and check for dangerous patterns
            parts = stripped.split()
            # Check for common injection patterns (e.g., semicolon, pipe, dollar sign)
            if any(part in [';', '|', '&', '&&', '||', '$(', '$( ', '&&', '||', '>', '<', '>>', '<<'] for part in parts):
                # Skip if dangerous pattern detected
                continue
            # Only accept commands that are simple and do not contain shell metacharacters
            # For safety, we assume the command is a simple argument list
            commands.append(stripped)

    if not commands:
        sys.exit(0)

    # Execute commands in order with at most max_parallel running at once
    results = []
    running_count = 0
    command_index = 0

    def execute_next():
        nonlocal command_index, running_count
        while command_index < len(commands):
            # Get next command
            command = commands[command_index]
            command_index += 1

            # Validate command again to ensure no shell metacharacters
            if any(part in [';', '|', '&', '&&', '||', '>', '<', '>>', '<<', '$(', '$( ', '$', '(', ')'] for part in command.split()):
                # Skip if dangerous pattern detected
                continue

            # Execute the command without shell
            try:
                # Split the command into arguments to avoid shell injection
                args = command.split()
                # Use subprocess with shell=False to avoid shell injection
                result = subprocess.run(args, capture_output=True, text=True, timeout=30)
                results.append((command_index - 1, result.returncode))
            except subprocess.TimeoutExpired:
                results.append((command_index - 1, "error"))
            except FileNotFoundError:
                results.append((command_index - 1, "error"))
            except PermissionError:
                results.append((command_index - 1, "error"))
            except Exception as e:
                results.append((command_index - 1, "error"))

            running_count -= 1
            # If we have fewer than max_parallel running, start the next one
            if running_count < max_parallel and command_index < len(commands):
                # Start next command
                execute_next()
            break

    # Execute commands sequentially with at most max_parallel running at once
    # We simulate parallel execution by running commands in batches
    # But without shell injection or unsafe threading
    for i in range(0, len(commands), max_parallel):
        batch = commands[i:i + max_parallel]
        for cmd in batch:
            # Validate command again
            if any(part in [';', '|', '&', '&&', '||', '>', '<', '>>', '<<', '$(', '$( ', '$', '(', ')'] for part in cmd.split()):
                continue

            try:
                args = cmd.split()
                result = subprocess.run(args, capture_output=True, text=True, timeout=30)
                results.append((commands.index(cmd), result.returncode))
            except subprocess.TimeoutExpired:
                results.append((commands.index(cmd), "error"))
            except FileNotFoundError:
                results.append((commands.index(cmd), "error"))
            except PermissionError:
                results.append((commands.index(cmd), "error"))
            except Exception as e:
                results.append((commands.index(cmd), "error"))

    # Print DONE messages as commands finish
    for cmd_index, exit_code in results:
        if isinstance(exit_code, int) and exit_code != 0:
            print(f"DONE {cmd_index} exit={exit_code}")
        elif exit_code == "error":
            print(f"DONE {cmd_index} exit=error")

    # Check final exit status
    all_success = True
    for cmd_index, exit_code in results:
        if isinstance(exit_code, int) and exit_code != 0:
            all_success = False
        elif exit_code == "error":
            all_success = False

    sys.exit(0 if all_success else 1)

