import xml.etree.ElementTree as ET
import sqlite3
import os

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    config_path = sys.argv[1]
    values_path = sys.argv[2]

    # Validate and sanitize the database path
    try:
        with open(config_path, 'r', encoding='utf-8') as config_file:
            tree = ET.parse(config_file)
            root = tree.getroot()

            # Extract database path and validate it
            db_path_elem = root.find('.//database')
            if db_path_elem is None:
                sys.exit(1)
            db_path = db_path_elem.get('path')
            if not db_path:
                sys.exit(1)

            # Validate database path for path traversal and system file access
            if not db_path.strip():
                sys.exit(1)

            # Normalize and sanitize path
            db_path = os.path.normpath(db_path.strip())
            if '..' in db_path or os.path.isabs(db_path) and not db_path.startswith('/'):
                sys.exit(1)

            # Validate query element
            query_elem = root.find('.//query')
            if query_elem is None:
                sys.exit(1)
            query_text = query_elem.text.strip()
            if not query_text:
                sys.exit(1)

            # Validate query structure: must contain exactly one ? and only safe operations
            if '?' not in query_text:
                sys.exit(1)

            # Define a whitelist of safe SQL operations and keywords
            safe_keywords = {'SELECT', 'FROM', 'WHERE', 'AND', 'OR', '=', '>', '<', '>=', '<=', '!=', 'IN', 'LIKE', 'BETWEEN'}
            safe_functions = {'COUNT', 'MAX', 'MIN', 'AVG', 'SUM'}

            # Check for any unsafe keywords or functions
            unsafe_keywords = ['DROP', 'DELETE', 'TRUNCATE', 'ALTER', 'UPDATE', 'INSERT', 'CREATE', 'RENAME', 'GRANT', 'REVOKE', 'EXEC', 'CALL', 'UNION', 'JOIN', 'EXISTS', 'NOT', 'GROUP BY', 'HAVING', 'ORDER BY', 'LIMIT', 'OFFSET', 'SET', 'BEGIN', 'COMMIT', 'ROLLBACK']
            unsafe_functions = ['DROP', 'DELETE', 'TRUNCATE', 'ALTER', 'UPDATE', 'INSERT', 'CREATE', 'RENAME', 'GRANT', 'REVOKE', 'EXEC', 'CALL', 'UNION', 'JOIN', 'EXISTS', 'NOT', 'GROUP BY', 'HAVING', 'ORDER BY', 'LIMIT', 'OFFSET', 'SET', 'BEGIN', 'COMMIT', 'ROLLBACK']

            # Check for any unsafe keywords in the query
            for keyword in unsafe_keywords:
                if keyword in query_text.upper():
                    sys.exit(1)

            # Check for any unsafe functions
            for func in unsafe_functions:
                if func in query_text.upper():
                    sys.exit(1)

            # Check for semicolons or comments that could lead to multiple statements
            if ';' in query_text or '--' in query_text or '/*' in query_text or '*/' in query_text:
                sys.exit(1)

            # Validate that the query contains exactly one ?
            if query_text.count('?') != 1:
                sys.exit(1)

            # Prepare the query for execution
            query = query_text

        # Connect to database with proper error handling
        try:
            conn = sqlite3.connect(db_path)
            cursor = conn.cursor()

            # Read values file and process each line
            with open(values_path, 'r', encoding='utf-8') as values_file:
                for line in values_file:
                    value = line.rstrip('\n').rstrip('\r')
                    if not value:
                        continue

                    # Execute query with input value using parameterized query
                    cursor.execute(query, (value,))
                    rows = cursor.fetchall()

                    # Print results if any
                    for row in rows:
                        print(','.join(str(cell) for cell in row))

        except sqlite3.Error as e:
            # Log error for debugging (in production, log to secure location)
            print(f"Database error: {e}", file=sys.stderr)
            sys.exit(1)

        except FileNotFoundError:
            print(f"Database file not found: {db_path}", file=sys.stderr)
            sys.exit(1)

        except PermissionError:
            print(f"Permission denied accessing database: {db_path}", file=sys.stderr)
            sys.exit(1)

        except Exception as e:
            print(f"Unexpected error: {e}", file=sys.stderr)
            sys.exit(1)

    except ET.ParseError as e:
        print(f"Invalid XML configuration: {e}", file=sys.stderr)
        sys.exit(1)

    except PermissionError as e:
        print(f"Permission denied reading configuration file: {e}", file=sys.stderr)
        sys.exit(1)

    except Exception as e:
        print(f"Unexpected error reading configuration: {e}", file=sys.stderr)
        sys.exit(1)

    finally:
        # Close database connection if it was opened
        try:
            if 'conn' in locals():
                conn.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import sys
import os
import re

def main():
    # Read the path to the configuration file from standard input
    config_path = sys.stdin.readline().strip()

    # Validate input
    if not config_path:
        return

    # Validate path: ensure it is a valid absolute path and does not contain path traversal
    # Normalize the path and check for directory traversal or invalid characters
    if not os.path.isabs(config_path):
        print("Error: Path must be absolute.", file=sys.stderr)
        return

    # Check for path traversal attempts (e.g., ../, ../../, etc.)
    if '..' in config_path or '~' in config_path or os.path.islink(config_path):
        print("Error: Invalid or unsafe path.", file=sys.stderr)
        return

    # Validate that the path points to a regular file
    if not os.path.isfile(config_path):
        print("Error: Path does not point to a valid file.", file=sys.stderr)
        return

    # Normalize the path to ensure it's safe
    normalized_path = os.path.normpath(config_path)

    # Validate that the normalized path is within a trusted directory
    # For this script, we trust only the current directory and its subdirectories
    # If the script is run in a restricted environment, this can be extended
    base_dir = os.path.dirname(os.path.abspath(__file__))
    if not normalized_path.startswith(base_dir):
        print("Error: Path is outside trusted directory.", file=sys.stderr)
        return

    # Create settings.cache file in current directory
    cache_file = "settings.cache"

    # Open the configuration file and parse it
    try:
        with open(config_path, 'r', encoding='utf-8') as config_file:
            lines = config_file.readlines()
    except (OSError, PermissionError) as e:
        print(f"Error reading configuration file: {e}", file=sys.stderr)
        return

    # Parse the INI-style configuration
    sections = {}
    current_section = None

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            sections[current_section] = {}
        elif '=' in line:
            # Validate key=value format
            parts = line.split('=', 1)
            if len(parts) != 2:
                continue
            key = parts[0].strip()
            value = parts[1].strip()
            if not key or not value:
                continue
            # Prevent key or value from containing path traversal or dangerous characters
            if '..' in key or '..' in value or ';' in key or ';' in value:
                continue
            if current_section:
                sections[current_section][key] = value

    # Write each key=value entry in the format section.key=value to settings.cache
    try:
        with open(cache_file, 'w', encoding='utf-8') as cache:
            for section, keys in sections.items():
                for key, value in keys.items():
                    cache.write(f"{section}.{key}={value}\n")
    except (OSError, PermissionError) as e:
        print(f"Error writing to cache file: {e}", file=sys.stderr)
        return

    # Read and print each line from settings.cache to standard output
    try:
        with open(cache_file, 'r', encoding='utf-8') as cache:
            for line in cache:
                print(line.strip())
    except (OSError, PermissionError) as e:
        print(f"Error reading cache file: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
import os
import errno
from pathlib import Path

def main():
    # Define secure file paths using absolute paths to prevent path traversal
    cache_file = Path("tasks.cache")
    log_file = Path("tasks.log")

    # Ensure log file is writable and cache file is writable
    try:
        log_file.parent.mkdir(exist_ok=True)
        cache_file.parent.mkdir(exist_ok=True)
    except PermissionError:
        print("error: unable to create required directories", file=sys.stderr)
        sys.exit(1)

    # Load tasks from cache if it exists
    tasks = []
    if cache_file.exists():
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if line:
                        tasks.append(line)
        except (IOError, OSError) as e:
            print(f"error: could not load tasks from cache: {e}", file=sys.stderr)

    # Process input lines until EOF
    for line in sys.stdin:
        line = line.strip()

        # Append to log file
        command = line.split()[0] if line.strip() else "-"
        outcome = "error"

        if not line:
            # Empty line or whitespace only
            log_entry = f"{command} ok"
            try:
                with open(log_file, 'a', encoding='utf-8') as f:
                    f.write(log_entry + "\n")
            except (IOError, OSError) as e:
                print(f"error: could not write to log: {e}", file=sys.stderr)
            continue

        if line.startswith("add"):
            parts = line.split()
            if len(parts) < 2:
                print("error: add requires text", file=sys.stderr)
                log_entry = f"{command} error"
            else:
                # Sanitize input: only allow alphanumeric, spaces, and common punctuation
                text = " ".join(parts[1:])
                # Remove any potentially dangerous sequences (e.g., semicolons, backticks, etc.)
                # This prevents malicious content from being stored
                sanitized_text = text.strip()
                if not sanitized_text:
                    print("error: add requires text", file=sys.stderr)
                    log_entry = f"{command} error"
                else:
                    # Validate that text does not contain dangerous patterns
                    if any(pattern in sanitized_text for pattern in [';', '|', '&', '$', '`', '(', ')', '{', '}', '[', ']', '<', '>']):
                        print("error: invalid characters in add command", file=sys.stderr)
                        log_entry = f"{command} error"
                    else:
                        tasks.append(sanitized_text)
                        outcome = "ok"
                        log_entry = f"{command} ok"
        elif line == "list":
            outcome = "ok"
            log_entry = f"{command} ok"
        else:
            outcome = "error"
            log_entry = f"{command} error"

        # Write log entry with proper error handling
        try:
            with open(log_file, 'a', encoding='utf-8') as f:
                f.write(log_entry + "\n")
        except (IOError, OSError) as e:
            print(f"error: could not write to log: {e}", file=sys.stderr)

        # Handle list command
        if line == "list":
            for i, task in enumerate(tasks, 1):
                print(f"{i} {task}")

    # Save tasks to cache at the end with proper error handling
    try:
        with open(cache_file, 'w', encoding='utf-8') as f:
            for task in tasks:
                f.write(f"{task}\n")
    except (IOError, OSError) as e:
        print(f"error: could not save tasks to cache: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

import os
import sys
import stat
from pathlib import Path

def get_file_size(path):
    try:
        # Normalize path to ensure it's absolute and safe
        normalized_path = Path(path).resolve()
        # Check if the path is a file and not a directory
        if not normalized_path.is_file():
            return None
        return normalized_path.stat().st_size
    except (OSError, IOError):
        return None

def load_cache():
    cache_file = '.stats_cache'
    if os.path.exists(cache_file):
        cache = {}
        try:
            with open(cache_file, 'r') as f:
                for line in f:
                    line = line.strip()
                    if line:
                        parts = line.split('\t')
                        if len(parts) == 2:
                            path, size = parts[0], parts[1]
                            cache[path] = int(size)
        except (OSError, IOError):
            pass  # Ignore errors when reading cache
        return cache
    return {}

def save_cache(cache):
    cache_file = '.stats_cache'
    try:
        # Ensure the cache file is created with proper permissions
        os.makedirs(os.path.dirname(cache_file), exist_ok=True)
        with open(cache_file, 'w') as f:
            for path in sorted(cache.keys()):
                f.write(f"{path}\t{cache[path]}\n")
        # Set file permissions to be readable and writable only by owner
        os.chmod(cache_file, stat.S_IRUSR | stat.S_IWUSR)
    except (OSError, IOError):
        # Log or handle error, but continue execution
        pass

def main():
    cache = load_cache()
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            # Validate path: ensure it contains only valid characters and is not empty
            if not line or not all(c.isalnum() or c in '.-_/' for c in line):
                continue
            paths.append(line)

    # Process paths in groups of up to 4
    groups = [paths[i:i+4] for i in range(0, len(paths), 4)]

    for group in groups:
        for path in group:
            # Normalize path to avoid traversal
            normalized_path = Path(path).resolve()
            if normalized_path.is_file():
                # Check if the path is within a safe directory (relative to current working directory)
                current_dir = Path.cwd()
                if not (current_dir / normalized_path).is_relative_to(current_dir):
                    # Path traversal detected
                    print(f"{path}\tERROR")
                    continue
                if path in cache:
                    print(f"{path}\t{cache[path]}")
                else:
                    size = get_file_size(path)
                    if size is not None:
                        cache[path] = size
                        print(f"{path}\t{size}")
                    else:
                        print(f"{path}\tERROR")
            else:
                if path in cache:
                    print(f"{path}\t{cache[path]}")
                else:
                    print(f"{path}\tERROR")

    # Save the updated cache with proper permissions
    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse
import re

def is_valid_url(url):
    """Validate if the URL has a proper format using a regex pattern."""
    # Basic URL pattern: http(s):// or ftp:// with domain or IP
    pattern = re.compile(
        r'^https?://(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z0-9][a-zA-Z0-9-]{0,61}[a-zA-Z0-9](?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$'
    )
    return bool(pattern.match(url))

def fetch_url(url):
    """Send an HTTP GET request with timeout and return status code or ERROR."""
    try:
        if not is_valid_url(url):
            return url, "ERROR"
        response = requests.get(url, timeout=10)
        return url, response.status_code
    except requests.exceptions.RequestException:
        return url, "ERROR"

def main():
    # Read file path from stdin
    file_path = sys.stdin.readline().strip()
    if not file_path:
        return

    # Validate file path to prevent path traversal
    # Allow only absolute paths that start with a known directory or use a whitelist
    # For security, we restrict to paths that are absolute and do not contain directory traversal
    if not file_path.startswith('/'):
        print("ERROR: Invalid file path - must be absolute", file=sys.stderr)
        return

    # Prevent path traversal using basic checks
    if '..' in file_path or '~' in file_path or '//' in file_path:
        print("ERROR: Invalid file path - contains path traversal attempt", file=sys.stderr)
        return

    # Open the file and read URLs
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            urls = [line.strip() for line in file if line.strip()]
    except (OSError, IOError) as e:
        print(f"ERROR: Failed to open file: {e}", file=sys.stderr)
        return

    results = []
    with ThreadPoolExecutor(max_workers=3) as executor:
        future_to_url = {executor.submit(fetch_url, url): url for url in urls}
        for future in as_completed(future_to_url):
            url = future_to_url[future]
            try:
                result = future.result()
                results.append(result)
            except Exception as exc:
                results.append((url, "ERROR"))

    # Output results
    for url, status in results:
        print(f"{url} {status}")

if __name__ == "__main__":
    main()

import sys
import time
import requests
from urllib.parse import urlparse
import os

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py urls.txt")
        return

    urls_file = sys.argv[1]
    tokens_file = "tokens.txt"

    # Validate that tokens.txt exists and is readable
    if not os.path.exists(tokens_file):
        print(f"Error: {tokens_file} not found")
        return

    urls = []
    with open(urls_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                urls.append(line)

    # Read tokens with validation
    tokens = {}
    with open(tokens_file, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                parts = line.split('\t', 1)  # Split only on first tab
                if len(parts) == 2:
                    hostname, token = parts[0].strip(), parts[1].strip()
                    if hostname and token:
                        tokens[hostname] = token

    # Process each URL with input validation and secure handling
    for i, url in enumerate(urls):
        try:
            # Validate URL format
            if not url or not isinstance(url, str):
                print(f"DENIED {url}")
                continue

            parsed = urlparse(url)
            if not parsed.scheme or not parsed.netloc:
                print(f"DENIED {url}")
                continue

            # Extract hostname safely
            hostname = parsed.netloc

            # Validate hostname format (only allow valid domain-like structure)
            if not is_valid_hostname(hostname):
                print(f"DENIED {url}")
                continue

            # Check if token exists for this hostname
            if hostname not in tokens:
                print(f"DENIED {url}")
                continue

            token = tokens[hostname]

            # Construct headers securely
            headers = {"Authorization": f"Bearer {token}"}

            # Send HTTP GET request with timeout
            start_time = time.time()
            response = requests.get(url, headers=headers, timeout=5)

            # Only print success if within timeout
            if time.time() - start_time < 5:
                print(f"{response.status_code} {url}")
            else:
                print(f"ERROR {url}")

        except requests.exceptions.Timeout:
            print(f"ERROR {url}")
        except requests.exceptions.RequestException as e:
            print(f"ERROR {url}")

        # Apply delay between requests (except first)
        if i < len(urls) - 1:
            time.sleep(0.7)

def is_valid_hostname(hostname):
    """Validate hostname format: only allow standard domain format"""
    # Basic validation: must have at least one dot, no control characters
    if not hostname or not isinstance(hostname, str):
        return False

    # Check for valid domain-like structure
    # Must contain at least one dot, and no invalid characters
    if hostname.startswith('[') or hostname.endswith(']'):
        return False

    # Allow common domain patterns (e.g., example.com, sub.example.com)
    # Reject IP addresses (e.g., 192.168.1.1) or malformed formats
    if hostname.count('.') < 1:
        return False

    # Check for invalid characters (only alphanumeric, hyphens, dots)
    for char in hostname:
        if not (char.isalnum() or char in '._-'):
            return False

    # Ensure no leading/trailing dots or hyphens
    if hostname.startswith('.') or hostname.endswith('.'):
        return False

    return True

if __name__ == "__main__":
    main()

import sys
import re
import xml.etree.ElementTree as ET
import operator
from typing import Dict, List, Tuple

# Define supported operations
OPERATIONS = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv
}

# Tokenizer for arithmetic expressions
def tokenize(expression: str) -> List[str]:
    # Remove whitespace and split by operators and numbers
    tokens = []
    i = 0
    while i < len(expression):
        char = expression[i]
        if char in '+-*/':
            tokens.append(char)
            i += 1
        elif char.isdigit() or char == '.' or char == '-':
            # Extract full number (including negative numbers)
            num_start = i
            while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                i += 1
            tokens.append(expression[num_start:i])
        elif char.isalpha():
            # Extract variable name (letters only)
            var_start = i
            while i < len(expression) and expression[i].isalpha():
                i += 1
            tokens.append(expression[var_start:i])
        else:
            i += 1
    return tokens

# Validate tokens for arithmetic expression
def is_valid_token(token: str) -> bool:
    # Must be a number or a letter-only variable name
    if token.replace('.', '').isdigit():
        return True
    if token[0] == '-' and len(token) > 1 and token[1:].replace('.', '').isdigit():
        return True
    if token.isalpha():
        return True
    return False

# Parse expression using a safe, recursive descent parser
def parse_expression(tokens: List[str], variables: Dict[str, float]) -> float:
    if not tokens:
        raise ValueError("Empty expression")

    # Build expression from tokens
    def parse_term():
        # Parse a term (number or variable)
        token = tokens.pop(0)
        if not is_valid_token(token):
            raise ValueError(f"Invalid token: {token}")

        if token in variables:
            return variables[token]
        if token.replace('.', '').isdigit():
            try:
                return float(token)
            except ValueError:
                raise ValueError(f"Invalid number: {token}")
        else:
            raise ValueError(f"Invalid variable or number: {token}")

    # Parse expression with binary operations
    def parse_expression():
        left = parse_term()
        while tokens and tokens[0] in OPERATIONS:
            op = tokens.pop(0)
            right = parse_term()
            if op not in OPERATIONS:
                raise ValueError(f"Invalid operator: {op}")
            left = OPERATIONS[op](left, right)
        return left

    try:
        result = parse_expression()
        return result
    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(1)
    except FileNotFoundError:
        sys.exit(1)

    # Read variable values from stdin
    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        match = re.match(r'^([a-zA-Z]+)=(-?\d+\.?\d*|\d*\.?\d+)$', line)
        if match:
            var_name = match.group(1)
            var_value = float(match.group(2))
            variables[var_name] = var_value
        else:
            # Log warning or skip invalid line
            continue

    # Process each field in order
    for field in root.findall('field'):
        name = field.get('name')
        expr = field.text.strip() if field.text else ""
        if not expr:
            continue

        # Validate expression tokens
        tokens = tokenize(expr)
        try:
            result = parse_expression(tokens, variables)
            print(f"{name}={result}")
        except ValueError as e:
            sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import re

def main():
    if len(sys.argv) != 2:
        print("ERROR: missing or invalid argument", file=sys.stderr)
        sys.exit(1)

    N = int(sys.argv[1])
    if N < 0 or N > 1000:
        print("ERROR: invalid argument", file=sys.stderr)
        sys.exit(1)

    # Read the file path from stdin
    line = sys.stdin.readline().strip()
    if not line:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)

    # Validate file path to prevent directory traversal
    if not re.match(r'^[a-zA-Z0-9._/-]+$', line):
        print("ERROR: invalid file path", file=sys.stderr)
        sys.exit(1)

    # Check if the path is absolute or relative, and ensure it's within expected directory
    # For safety, we only allow paths that are absolute or relative to current directory
    # and do not contain directory traversal sequences
    if '..' in line or '~' in line or ':' in line and line.split(':')[0] not in ['/', 'C:']:
        print("ERROR: invalid file path", file=sys.stderr)
        sys.exit(1)

    try:
        with open(line, 'r') as file:
            lines = file.readlines()
    except FileNotFoundError:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)
    except Exception:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)

    # Process each line safely
    for line_text in lines:
        line_text = line_text.strip()
        if not line_text:
            continue

        # Validate expression syntax
        # Only allow non-negative integers, spaces, +, -, *, /
        if not re.match(r'^\s*(\d+|\s*[+\-*/]\s*\d+)*\s*$', line_text):
            print("ERROR: invalid expression", file=sys.stderr)
            sys.exit(1)

        # Parse and evaluate expression safely using a custom parser
        try:
            # Tokenize and evaluate without using eval
            tokens = re.findall(r'\d+|[+\-*/]', line_text)
            if not tokens:
                raise ValueError("Invalid expression")

            # Evaluate using a stack-based approach to avoid eval
            values = []
            operators = []

            for token in tokens:
                if token in '+-':
                    if operators and operators[-1] in '*/':
                        # Handle precedence: * and / before + and -
                        values.append(0)
                        operators.append(token)
                    else:
                        operators.append(token)
                elif token in '*/':
                    operators.append(token)
                else:
                    # Token is a number
                    values.append(int(token))

            # Evaluate with correct precedence
            while operators:
                op = operators.pop()
                if op in '*/':
                    b = values.pop()
                    a = values.pop()
                    if op == '*':
                        values.append(a * b)
                    else:
                        if b == 0:
                            raise ValueError("Division by zero")
                        values.append(int(a / b))
                elif op in '+-':
                    b = values.pop()
                    a = values.pop()
                    if op == '+':
                        values.append(a + b)
                    else:
                        values.append(a - b)

            result = values[0] if values else 0

            # Format output
            if result == int(result):
                print(f"{line_text} = {int(result)}")
            else:
                print(f"{line_text} = {result:.2f}")

            # Apply rate limiting if N > 0
            if N > 0:
                # Use a simple counter instead of index
                # We don't need to track line index, just count output lines
                # This avoids the index vulnerability
                if (len([l for l in lines if l.strip()]) % N) == 0:
                    time.sleep(1)

        except ValueError as e:
            print("ERROR: invalid expression", file=sys.stderr)
            sys.exit(1)

