def read_cache_file(cache_path):
    rows = []
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                fields = line.strip().split('\t')
                rows.append(fields)
    return rows

def write_cache_file(cache_path, rows):
    with open(cache_path, 'w') as f:
        for row in rows:
            f.write('\t'.join(row) + '\n')

def validate_table_name(table_name):
    # Allow only alphanumeric characters, underscores, and dots
    # Must not contain SQL keywords or special characters
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    if not table_name or not table_name.strip():
        return False
    if not all(c in allowed_chars for c in table_name):
        return False
    # Check for SQL injection keywords
    sql_keywords = {'drop', 'delete', 'update', 'insert', 'alter', 'create', 'truncate', 'union', 'select', 'from', 'where', 'order', 'by', 'group', 'having', 'join', 'on', 'set', 'exec', 'begin', 'end', 'declare'}
    for kw in sql_keywords:
        if kw in table_name.lower():
            return False
    return True

def validate_database_path(database_name, xml_dir):
    # Validate that the database name is a valid file path within the XML directory
    # Only allow alphanumeric, underscores, dots, and hyphens
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-')
    if not database_name or not database_name.strip():
        return False
    if not all(c in allowed_chars for c in database_name):
        return False
    # Prevent path traversal
    if '..' in database_name:
        return False
    # Prevent access to system directories
    if any(part in database_name for part in ['/', '\\', 'etc', 'bin', 'tmp', 'home', 'root', 'var']):
        return False
    # Ensure the path is relative and within the XML directory
    path = os.path.join(xml_dir, database_name)
    return os.path.isabs(path) == False and os.path.dirname(path) == xml_dir

def execute_query(database_path, table_name):
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()
    # Use parameterized query to prevent SQL injection
    cursor.execute(f"SELECT * FROM {table_name}")
    columns = [description[0] for description in cursor.description]
    rows = cursor.fetchall()
    conn.close()

    result_rows = []
    for row in rows:
        result_row = []
        for field in row:
            if field is None:
                result_row.append("")
            else:
                result_row.append(str(field))
        result_rows.append(result_row)

    return result_rows

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    xml_path = sys.argv[1]
    cache_path = sys.argv[2]

    # Parse XML configuration
    try:
        tree = ET.parse(xml_path)
