import sys
import xml.etree.ElementTree as ET
import sqlite3
import hashlib
import os
import re

def parse_args(args):
    if len(args) < 3:
        return None, {}
    query_name = args[1]
    params = {}
    # Validate query_name - only allow safe, alphanumeric, underscore characters
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', query_name):
        raise ValueError("Invalid query name: contains unsafe characters")

    for arg in args[2:]:
        if '=' not in arg:
            continue
        param, value = arg.split('=', 1)
        # Validate parameter name - only allow safe, alphanumeric, underscore characters
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', param):
            raise ValueError(f"Invalid parameter name: {param}")
        params[param] = value
    return query_name, params

def read_xml(config_file):
    if not os.path.exists(config_file):
        raise FileNotFoundError(f"Configuration file not found: {config_file}")

    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        return root
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML format in {config_file}: {e}")

def validate_file_path(path, allowed_dir=None):
    """Validate file path to prevent path traversal and ensure it's within allowed directory"""
    if not path or not isinstance(path, str):
        return False

    # Normalize path
    normalized = os.path.normpath(path)

    # Check for path traversal
    if '..' in normalized:
        return False

    # Check if path is absolute and outside allowed directory
    if allowed_dir is not None:
        if os.path.isabs(path):
            if not os.path.commonpath([normalized, allowed_dir]) == allowed_dir:
                return False
        else:
            # Relative path - check if it's within allowed directory
            if not os.path.commonpath([normalized, allowed_dir]) == allowed_dir:
                return False

    # Ensure path is not empty and doesn't start with a dot
    if not normalized or normalized.startswith('.'):
        return False

    return True

def execute_query(db_path, query_sql, params):
    """Execute query using parameterized SQL to prevent injection"""
    if not validate_file_path(db_path):
        raise ValueError(f"Invalid database file path: {db_path}")

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Use parameterized query - no string replacement
        cursor.execute(query_sql, params)
        rows = cursor.fetchall()
        conn.close()
        return rows
    except sqlite3.Error as e:
        raise RuntimeError(f"Database error: {e}")

def write_output_and_mac(output_file, rows, key_file, params):
    """Write output and MAC file with secure key handling"""
    if not validate_file_path(output_file):
        raise ValueError(f"Invalid output file path: {output_file}")

    if not validate_file_path(key_file):
        raise ValueError(f"Invalid key file path: {key_file}")

    try:
        # Read key from file - ensure it's non-empty and valid
        with open(key_file, 'r', encoding='utf-8') as f:
            key_content = f.read().strip()
            if not key_content:
                raise ValueError("Key file is empty or contains only whitespace")

        # Ensure key is a valid string
        if not isinstance(key_content, str):
            raise ValueError("Key file contains invalid content")

        # Write output and MAC file
        output_path = output_file
        mac_path = output_path + '.mac'

        with open(output_path, 'w', encoding='utf-8') as out_f, \
             open(mac_path, 'w', encoding='utf-8') as mac_f:

            for row in rows:
                row_str = '|'.join(str(cell) if cell is not None else '' for cell in row)
                out_f.write(row_str + '\n')

                # Compute HMAC of row line
                row_bytes = row_str.encode('utf-8')
                h = hashlib.sha256()
                h.update(row_bytes)
                h.update(key_content.encode('utf-8'))
                mac_f.write(h.hexdigest() + '\n')

    except IOError as e:
        raise RuntimeError(f"Error writing files: {e}")

def main():
    if len(sys.argv) < 4:
        print("Usage: python report_runner.py CONFIG.xml QUERY_NAME PARAM=VALUE [PARAM=VALUE ...]")
        sys.exit(1)

    config_file = sys.argv[1]
    query_name = sys.argv[2]

    # Parse command-line arguments
    try:
        query_name, params = parse_args(sys.argv)
    except ValueError as e:
        print(f"Error parsing arguments: {e}")
        sys.exit(1)

    # Read and validate XML configuration
    try:
        root = read_xml(config_file)
    except (FileNotFoundError, ValueError) as e:
        print(f"Error reading configuration: {e}")
        sys.exit(1)

    # Find query by name
    query_element = root.find(f".//query[@name='{query_name}']")
    if query_element is None:
        print(f"Query '{query_name}' not found in configuration.")
        sys.exit(1)

    # Extract and validate file paths
    db_file = query_element.find("database")
    if db_file is None:
        print("Database file not specified in configuration.")
        sys.exit(1)
    db_path = db_file.get("file")
    if not db_path:
        print("Database file path is missing in configuration.")
        sys.exit(1)

    output_file = query_element.find("output")
    if output_file is None:
        print("Output file not specified in configuration.")
        sys.exit(1)
    output_path = output_file.get("file")
    if not output_path:
        print("Output file path is missing in configuration.")
        sys.exit(1)

    key_file = query_element.find("signing")
    if key_file is None:
        print("Signing key file not specified in configuration.")
        sys.exit(1)
    key_path = key_file.get("key_file")
    if not key_path:
        print("Signing key file path is missing in configuration.")
        sys.exit(1)

    # Validate all file paths
    try:
        validate_file_path(db_path)
        validate_file_path(output_path)
        validate_file_path(key_path)
    except ValueError as e:
        print(f"Error validating file paths: {e}")
        sys.exit(1)

    # Extract SQL query
    query_sql = query_element.get("sql")
    if not query_sql:
        print("SQL query is missing in configuration.")
        sys.exit(1)

    # Execute query and write output
    try:
        rows = execute_query(db_path, query_sql, params)
        write_output_and_mac(output_path, rows, key_path, params)
        print("Report generated successfully.")
    except RuntimeError as e:
        print(f"Error during execution: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

