        elif c.isdigit() or c == '.' or c == ' ':
            if token and token[-1] in "0123456789":
                token += c
            else:
                if token:
                    tokens.append(token)
                    token = ""
                token = c
        elif c.isalpha() or c == '_':
            if token:
                token += c
            else:
                token = c
        else:
            if token:
                tokens.append(token)
                token = ""
            # Invalid character
            return 0
        i += 1
        if token:
            tokens.append(token)
            token = ""

    # Validate tokens: only allow numbers, column names, and operators
    valid_tokens = []
    for token in tokens:
        if token in ['+', '-', '*', '/']:
            valid_tokens.append(token)
        elif token.replace('.', '').isdigit() or (token.count('.') == 1 and token.split('.')[0].isdigit() and token.split('.')[1].isdigit()):
            valid_tokens.append(token)
