        while pos < len(tokens) and tokens[pos] in ['+', '-']:
            op = tokens[pos]
            pos += 1
            right = evaluate_term(tokens, pos)
            if op == '+':
                left += right
            elif op == '-':
                left -= right
        return left, pos

    def evaluate_term(tokens, pos):
        left = evaluate_factor(tokens, pos)
        while pos < len(tokens) and tokens[pos] in ['*', '/']:
            op = tokens[pos]
            pos += 1
            right = evaluate_factor(tokens, pos)
            if op == '*':
                left *= right
            elif op == '/':
                if right == 0:
