def main():
    if len(sys.argv) != 2:
        print("Usage: python inventory_report.py <database_path>", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]

    # Initialize query start times to track concurrency
    query_starts = deque()
    max_concurrent_queries = 3

    # Open database connection
    try:
        conn = sqlite3.connect(db_path)
        conn.row_factory = sqlite3.Row  # Enable column access by name
    except Exception as e:
        print(f"ERROR: Could not open database {db_path}", file=sys.stderr)
        sys.exit(1)

    line_number = 0
    failed_queries = 0

    for line in sys.stdin:
        line = line.strip()
        line_number += 1

        if not line:
            continue

        try:
            data = json.loads(line)
        except json.JSONDecodeError as e:
            print(f"ERROR {line_number}", file=sys.stderr)
            failed_queries += 1
            continue

        # Log start of query
        print(f"INFO start {line_number}", file=sys.stderr)

        # Check concurrency limit
        while len(query_starts) >= max_concurrent_queries:
            if query_starts[0] < time.time() - 1.0:
                query_starts.popleft()
            else:
                time.sleep(0.01)  # Wait a bit before checking again

        # Add current start time
        query_starts.append(time.time())

        # Validate and sanitize input keys and values
        valid_keys = {'id', 'name', 'quantity', 'price'}
        invalid_keys = []
        for key in data:
            if key not in valid_keys:
                print(f"ERROR {line_number}", file=sys.stderr)
                failed_queries += 1
                break

        if failed_queries > 0:
            continue

        # Validate values
        invalid_values = []
        for key, value in data.items():
            if key == 'id':
                if not isinstance(value, int) or value <= 0:
                    print(f"ERROR {line_number}", file=sys.stderr)
                    failed_queries += 1
                    break
            elif key == 'quantity':
                if not isinstance(value, int) or value < 0:
                    print(f"ERROR {line_number}", file=sys.stderr)
                    failed_queries += 1
                    break
            elif key == 'price':
                if not isinstance(value, (int, float)) or value <= 0:
                    print(f"ERROR {line_number}", file=sys.stderr)
                    failed_queries += 1
                    break
            elif key == 'name':
                if not isinstance(value, str) or len(value) == 0:
                    print(f"ERROR {line_number}", file=sys.stderr)
                    failed_queries += 1
                    break

        if failed_queries > 0:
            continue

        # Build query condition with safe key names
        query_conditions = []
        params = []

        for key in data:
            query_conditions.append(f"{key} = ?")
            params.append(data[key])

        # If no conditions, query all rows
        if not query_conditions:
            query = "SELECT id, name, quantity, price FROM items"
            params = []
        else:
            query = "SELECT id, name, quantity, price FROM items WHERE " + " AND ".join(query_conditions)

        try:
            cursor = conn.execute(query, params)
            rows = cursor.fetchall()

            # Log completion
            print(f"INFO done {line_number} {len(rows)}", file=sys.stderr)

            # Output each row as JSON
            for row in rows:
                print(json.dumps({
                    "id": row["id"],
                    "name": row["name"],
                    "quantity": row["quantity"],
                    "price": row["price"]
                }))

        except Exception as e:
            print(f"ERROR {line_number}", file=sys.stderr)
            failed_queries += 1
            continue

    # Exit with status 1 if any query failed, 0 otherwise
    if failed_queries > 0:
        sys.exit(1)
    else:
        sys.exit(0)

