                data = json.load(f)
                # Validate the structure of the loaded data
                if not isinstance(data, dict):
                    return {}
                return data
        except (json.JSONDecodeError, IOError):
            # If cache is corrupted or unreadable, fall back to XML
            pass

    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()

        users = {}
        for user_elem in root.findall('user'):
            name = user_elem.get('name')
            if not name:
                continue
            token_elem = user_elem.find('token')
            token = token_elem.text if token_elem is not None else None
            if not token:
                continue
            allows = [allow.get('action') for allow in user_elem.findall('allow') if allow.get('action')]
            users[name] = {
                'token': token,
                'allows': allows
            }

        # Save to cache in a safe format
        with open(cache_file, 'w') as f:
            json.dump(users, f, indent=2)

        return users

    except (ET.ParseError, IOError) as e:
        return {}

