            sys.exit(1)

        # Validate tasks is a list of dicts
        if not isinstance(tasks_data, list):
            print("Unknown token", file=sys.stderr)
            sys.exit(1)

        for task in tasks_data:
            if not isinstance(task, dict):
                print("Unknown token", file=sys.stderr)
                sys.exit(1)

            # Validate owner is a string
            if "owner" not in task or not isinstance(task["owner"], str):
                print("Unknown token", file=sys.stderr)
                sys.exit(1)

            # Validate command is a list of strings
            if "command" not in task or not isinstance(task["command"], list):
                print("Unknown token", file=sys.stderr)
                sys.exit(1)

            for cmd in task["command"]:
                if not isinstance(cmd, str):
                    print("Unknown token", file=sys.stderr)
