        tasks = tasks_data
    else:
        tasks = []

    # Read state.json if it exists with strict validation
    state_file = "state.json"
    state: Dict[str, List[float]] = {}
    if os.path.exists(state_file):
        try:
            with open(state_file, 'r', encoding='utf-8') as f:
                state_data = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            # If state.json is malformed, start with empty state
            state_data = {}

        # Validate state is a dict with string keys and lists of numbers
        if not isinstance(state_data, dict):
            state = {}
        else:
            for owner in state_data:
                if not isinstance(owner, str):
                    state = {}
                    break
                if not isinstance(state_data[owner], list):
                    state = {}
                    break
                # Validate all timestamps are numbers (float or int)
                for timestamp in state_data[owner]:
                    if not isinstance(timestamp, (int, float)):
                        state = {}
                        break
            else:
                state = state_data
    else:
        state = {}

    # Process tasks in order
    now = time.time()

    # Ensure state has an array for current_owner if it doesn't exist
    if current_owner not in state:
        state[current_owner] = []

    for task in tasks:
        if task["owner"] != current_owner:
            continue

        # Count timestamps in the last 60 seconds
        count = 0
        for timestamp in state[current_owner]:
            if timestamp >= now - 60:
                count += 1

        if count >= 5:
            print(f"Rate limit exceeded for {current_owner}")
            continue

        # Run the command safely using subprocess with shell=False
        command = task["command"]
        cmd_str = " ".join(command)

        # Log the command for audit
        print(f"Ran {cmd_str} for {current_owner}")

        # Execute the command safely
        try:
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                shell=False,
                timeout=30  # Prevent long-running commands
            )
            if result.returncode != 0:
                # Log error if command fails
                print(f"Command failed for {current_owner}: {result.stderr}", file=sys.stderr)
        except subprocess.TimeoutExpired:
            print(f"Command timeout for {current_owner}", file=sys.stderr)
            continue
        except Exception as e:
            print(f"Command execution error for {current_owner}: {str(e)}", file=sys.stderr)
            continue

        # Append current time to the array
        state[current_owner].append(now)

    # Remove timestamps less than now - 60 from all owners' arrays
    current_time = time.time()
    cutoff = current_time - 60

    for owner in state:
        # Filter timestamps to only those >= cutoff
        state[owner] = [ts for ts in state[owner] if ts >= cutoff]

    # Write updated state to state.json with validation
    try:
        with open(state_file, 'w', encoding='utf-8') as f:
            json.dump(state, f, indent=2, separators=(',', ': '))
    except IOError as e:
        print(f"Error writing state file: {str(e)}", file=sys.stderr)
        sys.exit(1)

