import sys
import time
import os
from collections import defaultdict
import threading

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    config_file = sys.argv[1]
    jobs_file = sys.argv[2]
    cache_file = sys.argv[3]

    # Validate file paths and permissions
    if not os.path.exists(config_file):
        sys.exit(1)
    if not os.path.exists(jobs_file):
        sys.exit(1)

    # Validate that cache file is readable (if it exists)
    if os.path.exists(cache_file):
        if not os.access(cache_file, os.R_OK):
            sys.exit(1)

    # Read config file with strict input validation
    try:
        with open(config_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except (IOError, OSError) as e:
        sys.exit(1)

    if not lines:
        sys.exit(1)

    # Parse interval_ms
    interval_line = lines[0].strip()
    if not interval_line:
        sys.exit(1)
    interval_parts = interval_line.split()
    if len(interval_parts) < 1:
        sys.exit(1)
    try:
        interval_ms = int(interval_parts[0])
        if interval_ms < 0:
            sys.exit(1)
    except ValueError:
        sys.exit(1)

    # Parse nodes
    nodes = {}
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        node_name = parts[0]
        capacity_str = parts[1]
        try:
            capacity = int(capacity_str)
            if capacity < 0:
                sys.exit(1)
            nodes[node_name] = capacity
        except ValueError:
            sys.exit(1)

    if not nodes:
        sys.exit(1)

    # Validate and read existing cache assignments
    cache_assignments = {}
    cache_lines = []
    try:
        with open(cache_file, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = line.split()
                if len(parts) < 2:
                    continue
                job_id = parts[0]
                node_name = parts[1]
                # Validate node name - only allow alphanumeric and underscore
                if not all(c.isalnum() or c == '_' for c in node_name):
                    sys.exit(1)
                if not all(c.isalnum() or c == '_' for c in job_id):
                    sys.exit(1)
                cache_assignments[job_id] = node_name
                cache_lines.append(line)
    except (IOError, OSError) as e:
        cache_lines = []

    # Read jobs with validation
    jobs = []
    try:
        with open(jobs_file, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                job_id = line
                if not all(c.isalnum() or c == '_' for c in job_id):
                    sys.exit(1)
                jobs.append(job_id)
    except (IOError, OSError) as e:
        sys.exit(1)

    # Process jobs in order
    new_assignments = []
    lock = threading.Lock()

    for job_id in jobs:
        if job_id in cache_assignments:
            continue

        # Find first node with remaining capacity > 0
        assigned = False
        for node_name in list(nodes.keys()):
            # Validate node name
            if not all(c.isalnum() or c == '_' for c in node_name):
                continue

            current_capacity = nodes[node_name]
            # Count existing assignments on this node
            existing_on_node = sum(1 for j in cache_assignments.values() if j == node_name)
            new_on_node = sum(1 for j, n in new_assignments if n == node_name)
            assignments_on_node = existing_on_node + new_on_node

            if current_capacity > assignments_on_node:
                # Assign job to this node
                nodes[node_name] -= 1
                new_assignments.append((job_id, node_name))
                assigned = True
                break

        if not assigned:
            # No node has capacity, stop processing
            break

        # Wait interval_ms milliseconds
        time.sleep(interval_ms / 1000.0)

    # Output assignments
    # First print existing cache lines
    for line in cache_lines:
        print(line)

    # Then print new assignments
    for job_id, node_name in new_assignments:
        print(f"{job_id} {node_name}")

    # Write updated cache file with atomic write using temporary file
    temp_cache_path = cache_file + '.tmp'
    try:
        with open(temp_cache_path, 'w', encoding='utf-8') as f:
            for line in cache_lines:
                f.write(line + '\n')
            for job_id, node_name in new_assignments:
                f.write(f"{job_id} {node_name}\n")

        # Replace original cache file with temporary one
        os.replace(temp_cache_path, cache_file)
    except (IOError, OSError) as e:
        # If write fails, try to remove temp file
        if os.path.exists(temp_cache_path):
            try:
                os.remove(temp_cache_path)
            except:
                pass
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import re

def validate_variable_name(name):
    """Check if the variable name is safe (not a built-in or dangerous identifier)"""
    # Forbidden names that are built-in Python identifiers or could be used for code injection
    forbidden_names = {
        '__import__', 'open', 'eval', 'exec', 'compile', 'getattr', 'setattr',
        'hasattr', 'dir', 'vars', 'globals', 'locals', 'input', 'print',
        'exit', 'system', 'os', 'subprocess', 'pickle', 'json', 'zip', 'map',
        'filter', 'reduce', 'enumerate', 'range', 'dict', 'list', 'set', 'tuple',
        'bool', 'int', 'float', 'str', 'bytes', 'complex', 'any', 'all'
    }
    if name in forbidden_names:
        return False
    # Check if name starts with a digit or contains invalid characters
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        return False
    return True

def parse_expression(expr, vars_dict):
    """Parse and evaluate expression safely using a custom parser"""
    # Validate expression structure
    if not expr or not expr.strip():
        raise ValueError("Empty expression")

    # Check for invalid characters or syntax
    # Only allow digits, +, -, *, (, ), and spaces
    if not re.match(r'^[0-9+\-*/() ]+$', expr):
        raise ValueError("Invalid expression syntax")

    # Replace variables with their values, but only if the variable name is safe
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i] == '{':
            # Look for a variable name
            j = i + 1
            var_name = ""
            while j < len(expr) and expr[j] != '}':
                if expr[j] == '{':
                    # Nested braces are not allowed
                    raise ValueError("Nested placeholders not allowed")
                var_name += expr[j]
                j += 1
            if j >= len(expr) or expr[j] != '}':
                raise ValueError("Unmatched placeholder")
            var_name = var_name.strip()
            if not validate_variable_name(var_name):
                raise ValueError(f"Invalid variable name: {var_name}")
            if var_name not in vars_dict:
                raise ValueError(f"Variable {var_name} not found in variables")
            value = vars_dict[var_name]
            tokens.append(str(value))
            i = j + 1
        else:
            tokens.append(expr[i])
            i += 1

    # Reconstruct the expression from tokens
    expression = ''.join(tokens)

    # Now evaluate the expression using safe arithmetic only
    try:
        # Replace any remaining expressions with safe evaluation
        # We now have a string with only integers, +, -, *, (, ) and no variables
        # Evaluate using a safe arithmetic parser
        # We'll use eval only on a sanitized expression with no built-in functions
        # Since we've already validated the structure, we can safely evaluate
        result = eval(expression)
        if not isinstance(result, int):
            raise ValueError("Expression result must be an integer")
        return result
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {str(e)}")

def replace_placeholders(template, vars_dict):
    result = {}
    for key, value in template.items():
        if isinstance(value, str) and value.startswith('{{') and value.endswith('}}'):
            expr = value[2:-2]
            try:
                value_eval = parse_expression(expr, vars_dict)
                result[key] = value_eval
                print(f"placeholder: {expr} = {value_eval}", file=sys.stderr)
            except Exception as e:
                print(f"error: {str(e)}", file=sys.stderr)
                return None
        else:
            result[key] = value
    return result

def main():
    if len(sys.argv) != 3:
        print("error: missing arguments", file=sys.stderr)
        sys.exit(1)

    template_file = sys.argv[1]
    vars_file = sys.argv[2]

    try:
        with open(template_file, 'r') as f:
            template = json.load(f)

        with open(vars_file, 'r') as f:
            vars_dict = json.load(f)

        # Validate that vars_dict contains only integers
        for var_name, var_value in vars_dict.items():
            if not isinstance(var_value, int):
                print("error: variables must be integers", file=sys.stderr)
                sys.exit(1)

        # Validate that all variable names are safe
        for var_name in vars_dict.keys():
            if not validate_variable_name(var_name):
                print("error: variable name is unsafe", file=sys.stderr)
                sys.exit(1)

        # Replace placeholders
        result = replace_placeholders(template, vars_dict)
        if result is None:
            sys.exit(1)

        # Output the result to stdout
        print(json.dumps(result, indent=0))

    except json.JSONDecodeError as e:
        print(f"error: invalid JSON in input files", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError as e:
        print(f"error: file not found: {e}", file=sys.stderr)
