        # Convert value to string safely
        value_str = str(value)
        # Replace only if value is not a function or dangerous
        safe_expr = safe_expr.replace(f'{{"{key}"}}', value_str)
    # Validate the resulting expression
    # Only allow simple comparisons and arithmetic
    # Remove any function calls or dynamic access
    # Check for dangerous patterns
    dangerous_patterns = [
        r'\b(__import__|eval|exec|open|os|subprocess|sys|getattr|setattr|dir)\b',
        r'\b(\w+)\s*\(\s*[\w\.\[\]\s\(\)]*\s*\)',
        r'\b(\w+)\s*\[\s*\w+\s*\]'
    ]
    for pattern in dangerous_patterns:
        if re.search(pattern, safe_expr, re.IGNORECASE):
            return False
    # Evaluate only safe expressions
    try:
        # Use a restricted environment with only safe built-ins
        safe_env = {
            '__builtins__': {
                'abs': abs,
                'int': int,
                'float': float,
                'str': str,
                'len': len,
                'bool': bool,
                'type': type,
                'list': list,
                'dict': dict,
                'tuple': tuple,
                'set': set,
                'max': max,
                'min': min,
                'sum': sum,
                'all': all,
