                'isinstance': isinstance,
                'hasattr': hasattr,
                'getattr': getattr,
                'setattr': setattr,
                'dir': dir,
                'type': type,
            }
        }
        # Evaluate the expression
        result = eval(safe_expr, {"__builtins__": {}}, safe_env)
        return result
    except Exception:
