                return None
            if not isinstance(value, (int, float)):
                return None
            expr = expr.replace(metric_name, str(value))

        # Now evaluate the expression with only basic arithmetic
        # We'll use a simple recursive descent parser
        def parse_expression(tokens):
            def parse_term():
                token = tokens.pop(0)
                if token == '(':
                    result = parse_expression(tokens)
                    if tokens.pop(0) != ')':
                        return None
                    return result
                elif token.replace('.', '', 1).isdigit():
                    return float(token)
                else:
                    return None

            def parse_factor():
                result = parse_term()
                while tokens and tokens[0] in ['*', '/']:
                    op = tokens.pop(0)
                    right = parse_term()
                    if right is None:
                        return None
                    if op == '*':
                        result *= right
                    elif op == '/':
                        if right == 0:
                            return None
                        result /= right
                return result

            def parse_addition():
                result = parse_factor()
                while tokens and tokens[0] == '+':
                    tokens.pop(0)
                    right = parse_factor()
                    if right is None:
                        return None
                    result += right
                return result

            return parse_addition()

        # Tokenize the expression
        tokens = re.findall(r'\s*([0-9]+\.?[0-9]*|[+\-*/()]|[a-zA-Z_][a-zA-Z0-9_]*)\s*', expr)
        # Remove empty tokens
        tokens = [t for t in tokens if t]

        # Evaluate
        try:
            result = parse_expression(tokens)
            if result is None:
