import sys
import hashlib
import time
import os
import ast
from collections import defaultdict

def evaluate_expression_safe(expr):
    """
    Safely evaluate a mathematical expression with integer truncation toward zero.
    Uses AST parsing to avoid code injection and ensure only valid arithmetic operations.
    """
    # Validate input structure
    if not expr or not isinstance(expr, str):
        raise ValueError("Invalid expression: empty or non-string input")

    # Remove leading/trailing whitespace
    expr = expr.strip()

    # Validate expression content: only allow integers, spaces, parentheses, +, -, *, /
    for char in expr:
        if char not in '0123456789+-/*() ':
            raise ValueError(f"Invalid character: {char}")

    # Check for excessive length to prevent DoS
    if len(expr) > 1000:
        raise ValueError("Expression too long")

    # Parse using AST to ensure only safe operations
    try:
        # Convert expression to a safe AST node
        tree = ast.parse(expr, mode='eval')

        # Validate that the tree contains only safe operations
        def validate_node(node):
            if isinstance(node, ast.Num):
                return True
            if isinstance(node, ast.BinOp):
                left = validate_node(node.left)
                right = validate_node(node.right)
                if not left or not right:
                    return False
                op = type(node.op).__name__
                return op in ['Add', 'Sub', 'Mul', 'Div']
            if isinstance(node, ast.UnaryOp):
                if isinstance(node.op, ast.USub):
                    return validate_node(node.operand)
                return False
            return False

        if not validate_node(tree.body):
            raise ValueError("Expression contains unsafe operations")

        # Evaluate the AST safely
        def safe_eval(node):
            if isinstance(node, ast.Num):
                return node.n
            if isinstance(node, ast.UnaryOp):
                if isinstance(node.op, ast.USub):
                    return -safe_eval(node.operand)
                return 0
            if isinstance(node, ast.BinOp):
                left = safe_eval(node.left)
                right = safe_eval(node.right)
                op = type(node.op).__name__
                if op == 'Add':
                    return left + right
                elif op == 'Sub':
                    return left - right
                elif op == 'Mul':
                    return left * right
                elif op == 'Div':
                    # Truncate toward zero
                    if left * right >= 0:
                        return left // right
                    else:
                        return -(-left // right)
            return 0

        result = safe_eval(tree.body)
        return int(result)

    except (SyntaxError, ValueError) as e:
        raise ValueError(f"Invalid expression: {str(e)}")

def get_hash_key(expr):
    """Generate a 16-byte cryptographic hash from UTF-8 encoded expression."""
    # Use SHA-256 and take first 16 bytes
    hash_obj = hashlib.sha256(expr.encode('utf-8')).digest()
    return hash_obj[:16]

def main():
    if len(sys.argv) != 3:
        print("Usage: python evalcache.py <input_path> <output_path>")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]

    # Cache file name
    cache_file = "expr.cache"

    # Track uncached evaluations per second
    uncached_evaluations = defaultdict(int)
    last_reset_time = time.time()

    # Initialize cache if it doesn't exist
    if not os.path.exists(cache_file):
        with open(cache_file, 'wb') as f:
            f.write(b'')

    # Read input and process each line
    with open(input_path, 'r', encoding='utf-8') as infile, \
         open(output_path, 'w', encoding='utf-8') as outfile:

        for line_num, line in enumerate(infile, 1):
            line = line.strip()
            if not line:
                continue

            # Generate hash key for the expression
            expr_key = get_hash_key(line)

            # Check if result is already in cache
            cache_data = {}
            try:
                with open(cache_file, 'rb') as f:
                    cache_data = dict(
                        zip(
                            [hashlib.sha256(k.encode('utf-8')).digest()[:16] for k in cache_data.keys()],
                            cache_data.values()
                        )
                    )
            except:
                cache_data = {}

            # Check if we have a cached result
            if expr_key in cache_data:
                result = cache_data[expr_key]
                outfile.write(f"{result}\n")
                continue

            # Rate limiting: ensure at most 5 uncached evaluations per second
            current_time = time.time()
            # Reset counter every second
            if current_time - last_reset_time >= 1.0:
                uncached_evaluations.clear()
                last_reset_time = current_time

            # Check if we've exceeded the limit
            if len(uncached_evaluations) >= 5:
                # Wait until we can start another evaluation
                time.sleep(0.1)  # Small delay to allow rate limiting
                # Recheck after delay
                if len(uncached_evaluations) >= 5:
                    time.sleep(0.1)

            # Evaluate the expression
            try:
                result = evaluate_expression_safe(line)
            except Exception as e:
                # If evaluation fails, log error and skip
                print(f"Error evaluating expression {line}: {e}")
                result = 0

            # Store in cache
            try:
                with open(cache_file, 'rb') as f:
                    cache_data = {}
                    for line in f:
                        if line.strip():
                            parts = line.strip().split(b':', 1)
                            if len(parts) == 2:
                                key = parts[0]
                                value = parts[1]
                                cache_data[key] = value
                # Update cache
                cache_data[expr_key] = str(result).encode('utf-8')

                # Write updated cache
                with open(cache_file, 'wb') as f:
                    for key, value in cache_data.items():
                        f.write(key + b':' + value + b'\n')
            except Exception as e:
                print(f"Error writing to cache: {e}")

            # Write result to output
            outfile.write(f"{result}\n")

