import os
import hashlib

def compute_file_digest(file_path):
    with open(file_path, 'rb') as f:
        return hashlib.md5(f.read()).hexdigest()

def main():
    with open('input_paths.txt', 'r') as input_file, open('digest.log', 'w') as log_file:
        processed = 0
        errors = 0

        for line in input_file:
            path = line.strip()
            if os.path.isfile(path):
                try:
                    digest = compute_file_digest(path)
                    log_file.write(f"{path}\t{digest}\n")
                    processed += 1
                except IOError:
                    log_file.write(f"ERROR {path}\n")
                    errors += 1
            else:
                log_file.write(f"ERROR {path}\n")
                errors += 1

        log_file.write(f"Completed: {processed} processed, {errors} errors")

