import os

def read_notes_from_file():
    if os.path.exists('notes.dat'):
        with open('notes.dat', 'r', encoding='utf-8') as file:
            return [line.rstrip('\n') for line in file]
    return []

def write_notes_to_file(notes):
    with open('notes.dat', 'w', encoding='utf-8') as file:
        for note in notes:
            file.write(note + '\n')

def generate_html(notes, output_path):
    with open(output_path, 'w', encoding='utf-8') as file:
        file.write('<ol>\n')
        for note in notes:
            file.write(f'  <li>{note}</li>\n')
        file.write('</ol>\n')

def main():
    if len(sys.argv) != 2:
        print("Usage: python notes_app.py <output_html_path>")
        sys.exit(1)

    output_html_path = sys.argv[1]
    input_notes = [line.rstrip('\n') for line in sys.stdin]

    existing_notes = read_notes_from_file()
    updated_notes = existing_notes + input_notes
    write_notes_to_file(updated_notes)
    generate_html(updated_notes, output_html_path)

if __name__ == "__main__":
    main()

import sys
import os

def load_tasks():
    if os.path.exists('tasks.cache'):
        with open('tasks.cache', 'r') as file:
            return [line.strip() for line in file.readlines()]
    return []

def save_tasks(tasks):
    with open('tasks.cache', 'w') as file:
        for task in tasks:
            file.write(task + '\n')

def log_command(command, outcome):
    with open('tasks.log', 'a') as file:
        file.write(f"{command} {outcome}\n")

def main():
    tasks = load_tasks()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            log_command('-', 'ok')
            continue

        parts = line.split(' ', 1)
        command = parts[0]

        if command == 'add':
            if len(parts) < 2 or not parts[1].strip():
                print("error: add requires text", file=sys.stderr)
                log_command(command, 'error')
            else:
                tasks.append(parts[1].strip())
                log_command(line, 'ok')
        elif command == 'list':
            for i, task in enumerate(tasks, 1):
                print(f"{i} {task}")
            log_command(command, 'ok')
        else:
            print(f"error: unknown command {command}", file=sys.stderr)
            log_command(command, 'error')

    save_tasks(tasks)

if __name__ == "__main__":
    main()

import sys
import os

def load_cache():
    cache = {}
    if os.path.exists('.stats_cache'):
        with open('.stats_cache', 'r') as cache_file:
            for line in cache_file:
                path, size = line.strip().split('\t')
                cache[path] = int(size)
    return cache

def save_cache(cache):
    with open('.stats_cache', 'w') as cache_file:
        for path, size in cache.items():
            cache_file.write(f"{path}\t{size}\n")

def main():
    cache = load_cache()
    paths = [line.strip() for line in sys.stdin]

    for i in range(0, len(paths), 4):
        group = paths[i:i+4]
        for path in group:
            if path in cache:
                print(f"{path}\t{cache[path]}")
            else:
                try:
                    size = os.path.getsize(path)
                    print(f"{path}\t{size}")
                    cache[path] = size
                except OSError:
                    print(f"{path}\tERROR")

    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import requests

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_urls.py <file_path>")
        return

    file_path = sys.argv[1]
    successful = 0
    failed = 0

    with open(file_path, 'r') as file, open('check.log', 'w') as log_file:
        for line in file:
            url = line.strip()
            try:
                response = requests.get(url)
                status_code = response.status_code
                if 200 <= status_code <= 299:
                    successful += 1
                else:
                    failed += 1
                log_file.write(f"{url} {status_code}\n")
            except requests.RequestException as e:
                failed += 1
                log_file.write(f"{url} ERROR: {str(e)}\n")

    print(f"Processed {successful + failed} URLs: {successful} successful, {failed} failed")

