    main()

import sys
import os

def evaluate_expression(expression, variables):
    try:
        return str(eval(expression, {}, variables))
    except Exception:
        return ''

def main():
    input_lines = sys.stdin.read().strip().split('\n')
    token = input_lines[0]
    template_path = input_lines[1]
    name_to_integer = {}

    for line in input_lines[2:]:
        name, value = line.split('=')
        name_to_integer[name] = int(value)

    access_file_path = os.path.join(os.path.dirname(__file__), 'access.txt')
    with open(access_file_path, 'r') as access_file:
        first_line = access_file.readline().strip()
        if not first_line.endswith(':render') or first_line[:-7] != token:
            print('ACCESS_DENIED')
            sys.exit(1)

    with open(template_path, 'r') as template_file:
        template_content = template_file.read()

    result_content = ''
    i = 0
    while i < len(template_content):
        if template_content[i:i+2] == '{{':
            j = i + 2
            while j < len(template_content) and template_content[j:j+2] != '}}':
                j += 1
            if j < len(template_content):
                expression = template_content[i+2:j]
                result_content += evaluate_expression(expression, name_to_integer)
                i = j + 2
                continue
        result_content += template_content[i]
        i += 1

    print(result_content)
    sys.exit(0)

