import sys
import time
import requests
from urllib.parse import urlparse

def read_tokens(file_path):
    tokens = {}
    with open(file_path, 'r') as file:
        for line in file:
            if line.strip():
                hostname, token = line.strip().split('\t')
                tokens[hostname] = token
    return tokens

def get_hostname(url):
    parsed_url = urlparse(url)
    return parsed_url.hostname

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py urls.txt")
        return

    urls_file = sys.argv[1]
    tokens_file = 'tokens.txt'

    try:
        with open(urls_file, 'r') as file:
            urls = [line.strip() for line in file if line.strip()]
    except FileNotFoundError:
        print(f"Error: {urls_file} not found.")
        return

    tokens = read_tokens(tokens_file)

    for i, url in enumerate(urls):
        hostname = get_hostname(url)
        if hostname not in tokens:
            print(f"DENIED {url}")
        else:
            token = tokens[hostname]
            headers = {'Authorization': f'Bearer {token}'}
            try:
                response = requests.get(url, headers=headers, timeout=5)
                print(f"{response.status_code} {url}")
            except requests.RequestException:
                print(f"ERROR {url}")

        if i < len(urls) - 1:
            time.sleep(0.7)

if __name__ == "__main__":
    main()

import sys
import os
import xml.etree.ElementTree as ET
from cryptography.fernet import Fernet
from base64 import urlsafe_b64encode, urlsafe_b64decode

def generate_key(passphrase):
    return urlsafe_b64encode(passphrase.ljust(32)[:32].encode())

def encrypt_file(file_path, key):
    fernet = Fernet(key)
    with open(file_path, 'rb') as file:
        original = file.read()
    encrypted = fernet.encrypt(original)
    with open(file_path + '.enc', 'wb') as enc_file:
        enc_file.write(encrypted)

def main():
    if len(sys.argv) != 2:
        print("Usage: python filecrypt.py <passphrase>", file=sys.stderr)
        sys.exit(1)

    passphrase = sys.argv[1]
    key = generate_key(passphrase)

    try:
        tree = ET.parse('config.xml')
        root = tree.getroot()
    except (ET.ParseError, FileNotFoundError):
        print("config error", file=sys.stderr)
        sys.exit(1)

    for file_elem in root.findall('file'):
        file_path = file_elem.get('path')
        if not file_path:
            continue
        if not os.path.exists(file_path):
            print(f"missing file: {file_path}", file=sys.stderr)
            continue
        encrypt_file(file_path, key)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import re

def evaluate_expression(expression, variables):
    # Replace variable names with their values
    for var, value in variables.items():
        expression = re.sub(r'\b' + re.escape(var) + r'\b', str(value), expression)
    # Evaluate the expression
    return eval(expression)

def main():
    if len(sys.argv) != 2:
        print("Usage: python renderer.py <xml_file>")
        sys.exit(1)

    xml_file = sys.argv[1]
    tree = ET.parse(xml_file)
    root = tree.getroot()

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if line:
            name, value = line.split('=')
            variables[name] = float(value)

    for field in root.findall('field'):
        name = field.get('name')
        expression = field.text.strip()
        result = evaluate_expression(expression, variables)
        print(f"{name}={result}")

if __name__ == "__main__":
    main()

