import sys
import re
import ast
import operator

def evaluate_expression(expression, variables):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise NameError(f"Undefined variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise TypeError(f"Unsupported operation: {op_type}")
        else:
            raise TypeError(f"Unsupported node type: {type(node)}")

    try:
        parsed_expr = ast.parse(expression, mode='eval')
        return eval_node(parsed_expr.body)
    except Exception as e:
        raise e

def render_template(template, variables):
    pattern = re.compile(r'\{\{(.*?)\}\}')
    result = template
    log_entries = []

    for match in pattern.finditer(template):
        placeholder = match.group(0)
        expression = match.group(1).strip()
        try:
            result_value = evaluate_expression(expression, variables)
            result = result.replace(placeholder, str(result_value), 1)
            log_entries.append(f"{placeholder} -> {result_value}")
        except Exception as e:
            log_entries.append(f"{placeholder} ERROR {str(e)}")

    return result, log_entries

def main():
    if len(sys.argv) != 2:
        print("Usage: python render.py <template-file-path>")
        sys.exit(1)

    template_path = sys.argv[1]

    try:
        with open(template_path, 'r', encoding='utf-8') as file:
            template = file.read()
    except Exception as e:
        print(f"Error reading template file: {e}")
        sys.exit(1)

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            name, value = line.split('=', 1)
            if not re.match(r'^[A-Za-z_]\w*$', name):
                raise ValueError("Invalid variable name")
            variables[name] = int(value)
        except Exception as e:
            print(f"Error processing variable assignment: {e}")
            sys.exit(1)

    rendered_template, log_entries = render_template(template, variables)
    print(rendered_template)

    with open('render.log', 'w', encoding='utf-8') as log_file:
        for entry in log_entries:
            log_file.write(entry + '\n')

if __name__ == "__main__":
    main()

import sys
import time

def evaluate_expression(expression):
    try:
        result = eval(expression, {"__builtins__": None}, {})
        if result.is_integer():
            return int(result)
        else:
            return f"{result:.2f}"
    except ZeroDivisionError:
        return "ERROR: division by zero"

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py N", file=sys.stderr)
        sys.exit(1)

    try:
        N = int(sys.argv[1])
        if not (0 <= N <= 1000):
            raise ValueError
    except ValueError:
        print("N must be an integer between 0 and 1000", file=sys.stderr)
        sys.exit(1)

    file_path = sys.stdin.readline().strip()

    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
    except IOError:
        print("ERROR: cannot read file", file=sys.stderr)
        sys.exit(1)

    count = 0
    last_print_time = time.time()

    for line in lines:
        line = line.strip()
        if not line:
            continue

        result = evaluate_expression(line)
        print(f"{line} = {result}")

        count += 1
        if N > 0 and count % N == 0:
            current_time = time.time()
            if current_time - last_print_time < 1:
                time.sleep(1 - (current_time - last_print_time))
            last_print_time = time.time()

if __name__ == "__main__":
    main()

import os
import sys
import sqlite3
import json
from datetime import datetime

def main():
    # Token check
    token_file = os.getenv('AUDIT_TOKEN_FILE')
    token = os.getenv('AUDIT_TOKEN')

    if not token_file or not token:
        print("error: authorization failed", file=sys.stderr)
        sys.exit(1)

    try:
        with open(token_file, 'r') as f:
            file_token = f.read().rstrip('\n')
    except (IOError, OSError):
        print("error: authorization failed", file=sys.stderr)
        sys.exit(1)

    if file_token != token:
        print("error: authorization failed", file=sys.stderr)
        sys.exit(1)

    # Query and output
    db_path = None
    table_name = None
    status_text = None

    for i in range(1, len(sys.argv), 2):
        if sys.argv[i] == '--db':
            db_path = sys.argv[i + 1]
        elif sys.argv[i] == '--table':
            table_name = sys.argv[i + 1]
        elif sys.argv[i] == '--status':
            status_text = sys.argv[i + 1]

    if not db_path or not table_name or not status_text:
        print("error: query failed", file=sys.stderr)
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(f"SELECT id, owner, status FROM {table_name} WHERE status = ?", (status_text,))
        rows = cursor.fetchall()
    except sqlite3.Error:
        print("error: query failed", file=sys.stderr)
        sys.exit(1)
    finally:
        if conn:
            conn.close()

    for row in rows:
        print(json.dumps({'id': row[0], 'owner': row[1], 'status': row[2]}))

    # Logging
    audit_log = os.getenv('AUDIT_LOG')
    if audit_log:
        try:
            with open(audit_log, 'a') as log_file:
                log_file.write(f"{datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')}\t{len(rows)}\t{'ok' if rows else 'error'}\n")
        except (IOError, OSError):
            print("error: log failed", file=sys.stderr)
            sys.exit(1)

