import sys
import xml.etree.ElementTree as ET
import sqlite3
import re

def parse_config(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    table = root.get('table')
    columns = []
    for column in root.findall('column'):
        columns.append({
            'name': column.get('name'),
            'source': column.get('source')
        })
    return table, columns

def evaluate_expression(expression, row):
    safe_dict = {k: (str(v) if v is not None else 'NULL') for k, v in row.items()}
    try:
        return eval(expression, {"__builtins__": None}, safe_dict)
    except Exception:
        return 'NULL'

def main(config_file, db_file):
    table, columns = parse_config(config_file)

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    cursor.execute(f"PRAGMA table_info({table})")
    column_names = [info[1] for info in cursor.fetchall()]

    print(','.join(column['name'] for column in columns))

    cursor.execute(f"SELECT * FROM {table}")
    for row in cursor.fetchall():
        row_dict = dict(zip(column_names, row))
        output = []
        for column in columns:
            if column['source'] in column_names:
                value = row_dict[column['source']]
            else:
                value = evaluate_expression(column['source'], row_dict)
            if value is None:
                value = ''
            elif isinstance(value, (int, float)):
                value = f"{value:.10g}"
            else:
                value = str(value)
                if any(c in value for c in [',', '"', '\n']):
                    value = '"' + value.replace('"', '""') + '"'
            output.append(value)
        print(','.join(output))

    conn.close()

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

import sys
import xml.etree.ElementTree as ET
import sqlite3
import json
import concurrent.futures

def execute_query(db_path, query_id, query_text):
    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(query_text)
            row_count = len(cursor.fetchall())
            return {"id": query_id, "row_count": row_count}
    except Exception as e:
        return {"id": query_id, "error": str(e)}

def main(config_file):
    tree = ET.parse(config_file)
    root = tree.getroot()
    db_path = root.get('db')
    max_parallel = int(root.get('max_parallel'))

    queries = [(query.get('id'), query.text) for query in root.findall('query')]

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_parallel) as executor:
        futures = [executor.submit(execute_query, db_path, query_id, query_text) for query_id, query_text in queries]
        for future in concurrent.futures.as_completed(futures):
            print(json.dumps(future.result()))

if __name__ == "__main__":
    main(sys.argv[1])

import sys
import time
import sqlite3
import ast
import operator

def evaluate_expression(expression, row_values):
    operators = {
        ast.Add: operator.add
    }

    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            return row_values[node.id]
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def main():
    rules_file = sys.argv[1]
    db_file = sys.argv[2]
    max_rows_per_second = int(sys.argv[3])

    with open(rules_file, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    table_name = lines[0].strip()
    columns = lines[1].strip().split(',')
    rules = [line.strip().split('\t') for line in lines[2:] if line.strip()]

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    query = f"SELECT {', '.join(columns)} FROM {table_name}"
    cursor.execute(query)

    rule_counts = {rule[0]: 0 for rule in rules}
    last_read_time = time.time()

    for row in cursor:
        row_values = dict(zip(columns, row))
        for rule_name, expression in rules:
            if evaluate_expression(expression, row_values) > 0:
                rule_counts[rule_name] += 1

        current_time = time.time()
        elapsed_time = current_time - last_read_time
        if elapsed_time < 1 / max_rows_per_second:
            time.sleep(1 / max_rows_per_second - elapsed_time)
        last_read_time = time.time()

    for rule_name, count in rule_counts.items():
        print(f"{rule_name}\t{count}")

    conn.close()

if __name__ == "__main__":
    main()

