import sys
import os
import json
import time
import hmac
import hashlib
import base64

def issue_token(username, expires):
    key = os.getenv('TOKEN_TOOL_KEY')
    if not key:
        sys.exit(1)
    message = f"{username}:{expires}".encode()
    signature = hmac.new(key.encode(), message, hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(message + signature).decode()
    print(token)

def check_token(token):
    key = os.getenv('TOKEN_TOOL_KEY')
    if not key:
        sys.exit(1)
    try:
        decoded = base64.urlsafe_b64decode(token.encode())
        message, signature = decoded[:-32], decoded[-32:]
        if hmac.new(key.encode(), message, hashlib.sha256).digest() != signature:
            sys.exit(1)
        username, expires = message.decode().split(':')
        expires = int(expires)
        if expires < int(time.time()):
            sys.exit(1)
        with open('users.json', 'r') as f:
            users = json.load(f)
        if username not in users:
            sys.exit(1)
        print(f"{username} {users[username]}")
    except:
        sys.exit(1)

