import json
import hashlib
import ast
import operator

def evaluate_expression(expression):
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul}
    def parse_expr(expr):
        tokens = expr.replace('(', ' ( ').replace(')', ' ) ').split()
        def parse():
            if tokens[0] == '(':
                tokens.pop(0)
                result = parse_expr(' '.join(tokens))
                tokens.pop(0)  # Remove closing parenthesis
                return result
            else:
                return int(tokens.pop(0))
        result = parse()
        while tokens:
            op = tokens.pop(0)
            if op in ops:
                result = ops[op](result, parse())
        return result
    return parse_expr(expression)

