    for task in tasks:
        url = task['url']
        expr = task['expr']
        try:
            response = requests.get(url)
            if response.status_code < 200 or response.status_code > 299:
                result = "error"
            else:
                try:
                    data = response.json()
                    result = eval(expr, {"data": data})
                except (json.JSONDecodeError, SyntaxError, NameError):
