import sys
import os
import xml.etree.ElementTree as ET
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed

def parse_config(file_path):
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
        if root.tag != 'jobs':
            raise ValueError("Root element is not <jobs>")

        max_parallel = int(root.get('max_parallel', 0))
        if max_parallel <= 0:
            raise ValueError("max_parallel is not a positive integer")

        log_file = root.get('log_file')
        if not log_file:
            raise ValueError("log_file is not specified")

        jobs = []
        for job in root.findall('job'):
            job_id = job.get('id')
            command = job.get('command')
            if not job_id or not command:
                raise ValueError("Job is missing id or command")
            jobs.append((job_id, command))

        return max_parallel, log_file, jobs
    except Exception as e:
        print("config error", file=sys.stderr)
        sys.exit(2)

def run_job(job_id, command, log_file):
    with open(log_file, 'a') as log:
        log.write(f"START {job_id}\n")
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError:
            pass
        finally:
            log.write(f"END {job_id}\n")

def main():
    if len(sys.argv) != 2:
        print("config error", file=sys.stderr)
        sys.exit(2)

    config_file = sys.argv[1]
    max_parallel, log_file, jobs = parse_config(config_file)

    completed_jobs = 0
    with ThreadPoolExecutor(max_workers=max_parallel) as executor:
        futures = {executor.submit(run_job, job_id, command, log_file): job_id for job_id, command in jobs}
        for future in as_completed(futures):
            completed_jobs += 1

    print(f"jobs={completed_jobs}")
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import os
import time
import hashlib
from collections import deque

def compute_key(expression):
    return hashlib.sha256(expression.encode('utf-8')).digest()[:16]

def evaluate_expression(expression):
    try:
        result = eval(expression)
        return int(result)
    except ZeroDivisionError:
        return 0

def read_cache(cache_path):
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                key, value = line.strip().split(' ', 1)
                cache[key] = int(value)
    return cache

def write_cache(cache_path, cache):
    with open(cache_path, 'w') as f:
        for key, value in cache.items():
            f.write(f"{key} {value}\n")

def main(input_path, output_path):
    cache_path = 'expr.cache'
    cache = read_cache(cache_path)
    results = []
    uncached_queue = deque()
    current_time = time.time()

    with open(input_path, 'r') as infile:
        for expression in infile:
            expression = expression.strip()
            key = compute_key(expression)
            if key in cache:
                results.append(cache[key])
            else:
                while (uncached_queue and 
                       current_time - uncached_queue[0] >= 1 and 
                       len(uncached_queue) >= 5):
                    time.sleep(0.1)
                uncached_queue.append(time.time())
                result = evaluate_expression(expression)
                cache[key] = result
                results.append(result)

    write_cache(cache_path, cache)

    with open(output_path, 'w') as outfile:
        for result in results:
            outfile.write(f"{result}\n")

