import secrets
import string
import time

def generate_token():
    return ''.join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))

def compute_key(token):
    return ''.join(sorted(token))

def load_tokens():
    if not os.path.exists('tokens.json'):
        return {}
    with open('tokens.json', 'r') as f:
        return json.load(f)

def save_tokens(tokens):
    with open('tokens.json', 'w') as f:
        json.dump(tokens, f)

def issue(email):
    tokens = load_tokens()
    token = generate_token()
    key = compute_key(token)
    tokens[key] = {'email': email, 'expires_at': int(time.time()) + 3600}
    save_tokens(tokens)
    print(token)

def verify(token):
    tokens = load_tokens()
    key = compute_key(token)
    if key in tokens and tokens[key]['expires_at'] > int(time.time()):
        email = tokens[key]['email']
        del tokens[key]
        save_tokens(tokens)
        print(email)
    else:
        print('invalid')

