                        try:
                            result = subprocess.run(
                                [command_name] + command_args,
                                capture_output=True,
                                text=True,
                                check=True
                            )
                            for output_line in result.stdout.splitlines():
                                print(f"OUT: {output_line}")
                        except subprocess.CalledProcessError as e:
                            print(f"ERROR: {e}")
    except FileNotFoundError:
        print("AUTH_FAILED")
        sys.exit(1)

    sys.exit(0)

