import sys
import json
import hashlib
import urllib.request
from urllib.parse import urlparse

def is_safe_url(url):
    # Only allow http and https schemes
    parsed_url = urlparse(url)
    return parsed_url.scheme in ('http', 'https')

def main():
    cache_file = 'cache.json'
    try:
        with open(cache_file, 'r') as f:
            cache = json.load(f)
    except FileNotFoundError:
        cache = {}

    urls = sys.stdin.read().strip().split('\n')
    output = []

    for url in urls:
        if not is_safe_url(url):
            print(f"Unsafe URL detected: {url}", file=sys.stderr)
            continue

        if url in cache:
            hexstring = cache[url]
        else:
            try:
                with urllib.request.urlopen(url) as response:
                    body = response.read()
                    hexstring = hashlib.sha256(body).hexdigest()
                    cache[url] = hexstring
            except Exception as e:
                print(f"Error fetching {url}: {e}", file=sys.stderr)
                continue
        output.append(f"{url},{hexstring}")

    print('\n'.join(output))

    with open(cache_file, 'w') as f:
        json.dump(cache, f)

if __name__ == '__main__':
    main()

import os
import sys
import time
import json
import urllib.request
from datetime import datetime, timedelta
from urllib.parse import urlparse

CACHE_FILE = os.path.expanduser('~/.repo_cache.dat')

def log_message(message):
    print(f"{datetime.utcnow().isoformat()} {message}", file=sys.stderr)

def is_safe_url(url):
    parsed_url = urlparse(url)
    return parsed_url.scheme in ['http', 'https']

def fetch_repo_data(owner, repo):
    url = f"https://api.github.com/repos/{owner}/{repo}"
    if not is_safe_url(url):
        log_message("unsafe URL")
        return None, None
    try:
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read().decode())
            return data.get('full_name'), data.get('stargazers_count')
    except Exception:
        return None, None

def load_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, 'r') as f:
            return json.load(f)
    return None

def save_cache(identifier, fetch_time, full_name, stargazers_count):
    cache_data = {
        'identifier': identifier,
        'fetch_time': fetch_time,
        'full_name': full_name,
        'stargazers_count': stargazers_count
    }
    with open(CACHE_FILE, 'w') as f:
        json.dump(cache_data, f)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    identifier = sys.argv[1]
    cache = load_cache()

    if cache and cache['identifier'] == identifier:
        fetch_time = datetime.fromisoformat(cache['fetch_time'])
        if datetime.utcnow() - fetch_time < timedelta(hours=24):
            print(f"{cache['full_name']} {cache['stargazers_count']}")
            log_message("cache hit")
            sys.exit(0)

    full_name, stargazers_count = fetch_repo_data(*identifier.split('/'))
    if full_name is None or stargazers_count is None:
        log_message("fetch failure")
        sys.exit(1)

    print(f"{full_name} {stargazers_count}")
    save_cache(identifier, datetime.utcnow().isoformat(), full_name, stargazers_count)
    log_message("cache miss")
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import os
import json
import time
import hmac
import hashlib
import base64

def issue_token(username, expires):
    key = os.getenv('TOKEN_TOOL_KEY')
    if not key:
        sys.exit(1)
    message = f"{username}:{expires}".encode()
    signature = hmac.new(key.encode(), message, hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(message + signature).decode()
    print(token)

def check_token(token):
    key = os.getenv('TOKEN_TOOL_KEY')
    if not key:
        sys.exit(1)
    try:
        decoded = base64.urlsafe_b64decode(token.encode())
        message, signature = decoded[:-32], decoded[-32:]
        if hmac.new(key.encode(), message, hashlib.sha256).digest() != signature:
            sys.exit(1)
        username, expires = message.decode().split(':')
        expires = int(expires)
        if expires < int(time.time()):
            sys.exit(1)
        with open('users.json', 'r') as f:
            users = json.load(f)
        if username not in users:
            sys.exit(1)
        print(f"{username} {users[username]}")
    except:
        sys.exit(1)

if len(sys.argv) < 3:
    sys.exit(1)

if sys.argv[1] == 'issue' and len(sys.argv) == 4:
    issue_token(sys.argv[2], sys.argv[3])
elif sys.argv[1] == 'check' and len(sys.argv) == 3:
    check_token(sys.argv[2])
else:
    sys.exit(1)

import sys
import re
import xml.etree.ElementTree as ET
import pickle
import os
from defusedxml import ElementTree as defused_ET
from defusedxml.common import EntitiesForbidden
import ast

def evaluate_expression(expr):
    try:
        return ast.literal_eval(expr)
    except (ValueError, SyntaxError):
        print(f"Error evaluating expression '{expr}': Invalid syntax")
        return None

def process_xml(input_path, output_path, cache):
    try:
        tree = defused_ET.parse(input_path)
    except EntitiesForbidden:
        print(f"Error: XML file '{input_path}' contains forbidden entities")
        return 0, 0

    root = tree.getroot()
    total_replacements = 0
    cache_hits = 0

    def replace_placeholders(element):
        nonlocal total_replacements, cache_hits
        if element.text:
            matches = re.findall(r'{{\s*(.*?)\s*}}', element.text)
            for match in matches:
                stripped_expr = match.strip()
                if stripped_expr in cache:
                    replacement = str(cache[stripped_expr])
                    cache_hits += 1
                else:
                    result = evaluate_expression(stripped_expr)
                    if result is not None:
                        cache[stripped_expr] = result
                        replacement = str(result)
                    else:
                        replacement = match
                element.text = element.text.replace(f'{{{{ {match} }}}}', replacement)
                total_replacements += 1
        for child in element:
            replace_placeholders(child)

    replace_placeholders(root)
    tree.write(output_path, encoding='utf-8', xml_declaration=True)
    return total_replacements, cache_hits

def main():
    if len(sys.argv) != 3:
        print("Usage: python expand.py <input_xml> <output_xml>")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]
    cache_path = input_path + '.expandcache'

    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as cache_file:
            cache = pickle.loads(cache_file.read())
    else:
        cache = {}

    total_replacements, cache_hits = process_xml(input_path, output_path, cache)

    with open(cache_path, 'wb') as cache_file:
        cache_file.write(pickle.dumps(cache))

    print(f"Replaced {total_replacements} placeholders ({cache_hits} from cache).")

if __name__ == "__main__":
    main()

import sys
import time
from collections import defaultdict

def read_config(config_file):
    with open(config_file, 'r') as f:
        interval_ms = int(f.readline().split()[1])
        nodes = {}
        for line in f:
            name, capacity = line.split()
            nodes[name] = int(capacity)
    return interval_ms, nodes

def read_jobs(jobs_file):
    with open(jobs_file, 'r') as f:
        return [line.strip() for line in f]

def read_cache(cache_file):
    assignments = {}
    try:
        with open(cache_file, 'r') as f:
            for line in f:
                job_id, node_name = line.split()
                assignments[job_id] = node_name
    except FileNotFoundError:
        pass
    return assignments

def write_cache(cache_file, assignments):
    with open(cache_file, 'w') as f:
        for job_id, node_name in assignments.items():
            f.write(f"{job_id} {node_name}\n")

def main():
    if len(sys.argv) != 4:
        print("Usage: python assign_jobs.py config.txt jobs.txt assignments.cache")
        sys.exit(1)

    config_file, jobs_file, cache_file = sys.argv[1:]
    interval_ms, nodes = read_config(config_file)
    jobs = read_jobs(jobs_file)
    assignments = read_cache(cache_file)

    node_capacities = defaultdict(int)
    for node, capacity in nodes.items():
        node_capacities[node] = capacity

    for job_id in jobs:
        if job_id in assignments:
            print(f"{job_id} {assignments[job_id]}")
            continue

        for node, capacity in nodes.items():
            if node_capacities[node] > 0:
                assignments[job_id] = node
                node_capacities[node] -= 1
                print(f"{job_id} {node}")
                time.sleep(interval_ms / 1000)
                break

    write_cache(cache_file, assignments)

if __name__ == "__main__":
    main()

import sys
import json
import re
import operator
import ast

def evaluate_expression(expr, vars_dict):
