import json
import time
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
import ast

def evaluate_expression(expression, data):
    try:
        return str(ast.literal_eval(expression))
    except (ValueError, SyntaxError):
        return ''

def render_template(template, data):
    pattern = r'\{\{(.+?)\}\}'
    matches = re.findall(pattern, template)
    rendered = template
    for match in matches:
        rendered = rendered.replace(f'{{{{ {match} }}}}', evaluate_expression(match, data))
    return rendered

def process_object(obj, template):
    time.sleep(0.2)
    return render_template(template, obj)

def main():
    with open('template.html', 'r', encoding='utf-8') as f:
        template = f.read()

    with open('data.json', 'r', encoding='utf-8') as f:
        data_array = json.load(f)

    rendered_strings = []
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for obj in data_array:
            future = executor.submit(process_object, obj, template)
            futures.append(future)

        for future in as_completed(futures):
            rendered_strings.append(future.result())

    with open('report.html', 'w', encoding='utf-8') as f:
        f.write(''.join(rendered_strings))

