        with open(urls_file, 'r') as file:
            urls = [line.strip() for line in file if line.strip() and validate_url(line.strip())]
    except FileNotFoundError:
        print(f"Error: {urls_file} not found.")
        return

    tokens = read_tokens(tokens_file)

    for i, url in enumerate(urls):
        hostname = get_hostname(url)
        if hostname not in tokens:
            print(f"DENIED {url}")
        else:
            token = tokens[hostname]
            headers = {'Authorization': f'Bearer {token}'}
            req = urllib.request.Request(url, headers=headers)
            try:
                context = ssl.create_default_context()
                context.check_hostname = False
                context.verify_mode = ssl.CERT_NONE
                with urllib.request.urlopen(req, timeout=5, context=context) as response:
                    print(f"{response.status} {url}")
            except urllib.error.URLError as e:
                if isinstance(e.reason, ssl.SSLError):
                    print(f"ERROR SSL {url}")
                elif isinstance(e.reason, TimeoutError):
                    print(f"ERROR TIMEOUT {url}")
                else:
                    print(f"ERROR {url}")

        if i < len(urls) - 1:
            time.sleep(0.7)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import re
import ast
import operator

class ExpressionEvaluator:
    def __init__(self, variables):
        self.variables = variables
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.USub: operator.neg
        }

    def evaluate(self, expression):
        try:
            node = ast.parse(expression, mode='eval').body
            return self._evaluate_node(node)
        except Exception as e:
            raise ValueError(f"Invalid expression: {expression}") from e

    def _evaluate_node(self, node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._evaluate_node(node.left)
            right = self._evaluate_node(node.right)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.UnaryOp):
            operand = self._evaluate_node(node.operand)
            op_type = type(node.op)
            if op_type in self.operators:
                return self.operators[op_type](operand)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.Name):
            if node.id in self.variables:
                return self.variables[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

def validate_xml(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        if root.tag != 'calc':
            raise ValueError("Root element must be <calc>")
        for field in root.findall('field'):
            if 'name' not in field.attrib:
                raise ValueError("Each <field> must have a 'name' attribute")
            if field.text is None:
                raise ValueError("Each <field> must contain text")
        return root
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python renderer.py <xml_file>")
        sys.exit(1)

    xml_file = sys.argv[1]
    root = validate_xml(xml_file)

    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if line:
            name, value = line.split('=')
            if not re.match(r'^[a-zA-Z]+$', name):
                raise ValueError(f"Invalid variable name: {name}")
            try:
                variables[name] = float(value)
            except ValueError:
                raise ValueError(f"Invalid value for {name}: {value}")

    evaluator = ExpressionEvaluator(variables)
    for field in root.findall('field'):
        name = field.get('name')
        expression = field.text.strip()
        try:
            result = evaluator.evaluate(expression)
            print(f"{name}={result}")
        except ValueError as e:
            print(f"Error evaluating {name}: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

import sys
import os
import json
import secrets
import re
from pathlib import Path

def evaluate_expression(expression, context):
    allowed_names = {
        '__builtins__': None,
        '__name__': None,
        '__doc__': None,
        '__package__': None,
        '__loader__': None,
        '__spec__': None,
        '__annotations__': None,
        '__file__': None,
        '__cached__': None,
    }
    allowed_names.update(context)
    try:
        return eval(expression, {"__builtins__": None}, allowed_names)
    except Exception:
        return None

def sanitize_path(path):
    sanitized = Path(path).resolve()
    if not sanitized.is_absolute() or not sanitized.exists():
        raise ValueError("Invalid path")
    return sanitized

def main():
    recipe_file = sys.stdin.readline().strip()
    output_file = sys.stdin.readline().strip()

    try:
        recipe_file = sanitize_path(recipe_file)
        output_file = sanitize_path(output_file)
    except ValueError:
        print("error", file=sys.stderr)
        sys.exit(1)

    context = {}

    try:
        with open(recipe_file, 'r', encoding='utf-8') as f:
            for line in f:
                match = re.match(r'(\w+)\s*=\s*(.+)', line.strip())
                if match:
                    name, expression = match.groups()
                    result = evaluate_expression(expression, context)
                    if result is None:
                        print("error", file=sys.stderr)
                        sys.exit(1)
                    context[name] = result
    except FileNotFoundError:
        print("error", file=sys.stderr)
        sys.exit(1)
    except Exception:
        print("error", file=sys.stderr)
        sys.exit(1)

    run_id = secrets.token_hex(16)

    output = {
        "run_id": run_id,
        "results": context
    }

    try:
        with open(output_file, 'w', encoding='utf-8') as f:
