import sys
import xml.etree.ElementTree as ET
import sqlite3
import re
import ast
import operator

def parse_config(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    table = root.get('table')
    columns = []
    for column in root.findall('column'):
        columns.append({
            'name': column.get('name'),
            'source': column.get('source')
        })
    return table, columns

def evaluate_expression(expression, row):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Name: lambda: row.get(node.id, 'NULL'),
        ast.Num: lambda: node.n,
        ast.Expression: lambda: eval_node(node.body)
    }

    def eval_node(node):
        if type(node) in allowed_operators:
            return allowed_operators[type(node)]()
        else:
            raise ValueError("Unsupported operation")

    try:
        tree = ast.parse(expression, mode='eval')
        return eval_node(tree.body)
    except Exception:
        return 'NULL'

def main(config_file, db_file):
    table, columns = parse_config(config_file)

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    cursor.execute("PRAGMA table_info(?)", (table,))
    column_names = [info[1] for info in cursor.fetchall()]

    print(','.join(column['name'] for column in columns))

    cursor.execute("SELECT * FROM ?", (table,))
    for row in cursor.fetchall():
        row_dict = dict(zip(column_names, row))
        output = []
        for column in columns:
            if column['source'] in column_names:
                value = row_dict[column['source']]
            else:
                value = evaluate_expression(column['source'], row_dict)
            if value is None:
                value = ''
            elif isinstance(value, (int, float)):
                value = f"{value:.10g}"
            else:
                value = str(value)
                if any(c in value for c in [',', '"', '\n']):
                    value = '"' + value.replace('"', '""') + '"'
            output.append(value)
        print(','.join(output))

    conn.close()

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

import sys
import xml.etree.ElementTree as ET
import sqlite3
import json
import concurrent.futures
import os
import re

def sanitize_query(query_text):
    # Basic sanitation to prevent SQL injection
    if not re.match(r'^SELECT\s+.*$', query_text, re.IGNORECASE):
        raise ValueError("Invalid query format")
    return query_text

def sanitize_id(query_id):
    # Basic sanitation to prevent injection in query IDs
    if not re.match(r'^[a-zA-Z0-9_-]+$', query_id):
        raise ValueError("Invalid query ID")
    return query_id

def sanitize_db_path(db_path):
    # Prevent path traversal by ensuring the path is absolute and within a safe directory
    safe_root = '/safe/db/directory'
    abs_path = os.path.abspath(db_path)
    if not abs_path.startswith(safe_root):
        raise ValueError("Invalid database path")
    return abs_path

def execute_query(db_path, query_id, query_text):
    try:
        sanitized_query = sanitize_query(query_text)
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(sanitized_query)
            row_count = len(cursor.fetchall())
            return {"id": sanitize_id(query_id), "row_count": row_count}
    except Exception as e:
        return {"id": sanitize_id(query_id), "error": "An error occurred"}

def main(config_file):
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
        db_path = sanitize_db_path(root.get('db'))
        max_parallel = int(root.get('max_parallel'))
        if max_parallel <= 0:
            raise ValueError("max_parallel must be a positive integer")

        queries = [(query.get('id'), query.text) for query in root.findall('query')]

        with concurrent.futures.ThreadPoolExecutor(max_workers=max_parallel) as executor:
            futures = [executor.submit(execute_query, db_path, query_id, query_text) for query_id, query_text in queries]
            for future in concurrent.futures.as_completed(futures):
                print(json.dumps(future.result()))

    except ET.ParseError:
        print(json.dumps({"error": "Malformed XML"}))
    except Exception as e:
        print(json.dumps({"error": str(e)}))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(json.dumps({"error": "Usage: python run_queries.py config.xml"}))
    else:
        main(sys.argv[1])

import sys
import sqlite3
import re
import ast
import operator

def evaluate_expression(expression, row):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    def eval_expr(node):
        if isinstance(node, ast.BinOp):
            left = eval_expr(node.left)
            right = eval_expr(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            return float(row[node.id])
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    tree = ast.parse(expression, mode='eval')
    return str(eval_expr(tree.body))

def main():
    if len(sys.argv) < 3:
        print("Usage: python report.py <database> <table> [column=value]", file=sys.stderr)
        sys.exit(1)

    db_path, table_name = sys.argv[1], sys.argv[2]
    filter_column, filter_value = None, None

    if len(sys.argv) == 4:
        filter_column, filter_value = sys.argv[3].split('=', 1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
        if not cursor.fetchone():
            raise ValueError(f"Table {table_name} does not exist in the database.")

        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [col[1] for col in cursor.fetchall()]

        query = f"SELECT * FROM {table_name}"
        params = ()
        if filter_column:
            if filter_column not in columns:
                raise ValueError(f"Column {filter_column} does not exist in the table.")
            query += f" WHERE {filter_column} = ?"
            params = (filter_value,)

        cursor.execute(query, params)
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        conn.close()

    template = sys.stdin.read()

    for row in rows:
        row_dict = dict(zip(columns, row))
        rendered_html = re.sub(r'{{(.*?)}}', lambda m: evaluate_expression(m.group(1), row_dict), template)
        print(rendered_html)

if __name__ == "__main__":
    main()

import sqlite3
import time
import os
import html
import re

def read_terms(file_path):
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File {file_path} not found.")
    with open(file_path, 'r') as file:
        return [line.strip() for line in file.readlines() if line.strip()]

def query_database(term, db_path):
    if not os.path.isfile(db_path):
        raise FileNotFoundError(f"Database file {db_path} not found.")
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    query = "SELECT id, name, price, stock FROM items WHERE name LIKE ?"
    cursor.execute(query, ('%' + term + '%',))
    results = cursor.fetchall()
    conn.close()
    return results

def escape_html(text):
    return html.escape(text)

def write_html_report(results, terms, output_path):
    with open(output_path, 'w') as file:
        file.write('<table>\n')
        file.write('<tr><th>Term</th><th>ID</th><th>Name</th><th>Price</th><th>Stock</th></tr>\n')
        for term in terms:
            for row in results[term]:
                file.write(f'<tr><td>{escape_html(term)}</td><td>{escape_html(str(row[0]))}</td><td>{escape_html(row[1])}</td><td>{escape_html(str(row[2]))}</td><td>{escape_html(str(row[3]))}</td></tr>\n')
        file.write('</table>')

def main():
    terms_file = 'terms.txt'
    db_file = 'data.db'
    report_file = 'report.html'

    try:
        terms = read_terms(terms_file)
        results = {}

        start_time = time.time()
        query_count = 0

        for term in terms:
            if query_count >= 5:
                elapsed = time.time() - start_time
                if elapsed < 1:
                    time.sleep(1 - elapsed)
                start_time = time.time()
                query_count = 0

            results[term] = query_database(term, db_file)
            query_count += 1

        write_html_report(results, terms, report_file)
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == '__main__':
    main()

import sys
import sqlite3
import csv
import datetime
import re
import ast
import operator

def parse_where(where):
    match = re.match(r'(\w+)\s*=\s*(.+)', where)
    if not match:
        raise ValueError("Invalid WHERE clause")
    column, value = match.groups()
    if value.startswith("'") and value.endswith("'"):
        value = value[1:-1]
    else:
        try:
            value = float(value)
        except ValueError:
            raise ValueError("Invalid literal in WHERE clause")
    return column, value

def safe_eval(node, allowed_names):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body, allowed_names)
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left, allowed_names)
        right = safe_eval(node.right, allowed_names)
        op = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv
        }.get(type(node.op))
        if op is None:
            raise ValueError("Unsupported operation")
        return op(left, right)
    elif isinstance(node, ast.Name):
        if node.id not in allowed_names:
            raise ValueError(f"Use of disallowed name '{node.id}'")
        return allowed_names[node.id]
    elif isinstance(node, ast.Num):
        return node.n
    else:
        raise ValueError("Unsupported expression")

def evaluate_formula(formula, row):
    try:
        tree = ast.parse(formula, mode='eval')
        return safe_eval(tree, row)
    except Exception as e:
        raise ValueError(f"Invalid formula: {str(e)}")

def main():
    if len(sys.argv) != 5 or sys.argv[2] != '--where' or sys.argv[4] != '--formula':
        print("Usage: python filter_sales.py db_path --where VALUE --formula VALUE", file=sys.stderr)
        sys.exit(1)

    db_path, where, formula = sys.argv[1], sys.argv[3], sys.argv[5]

    try:
        column, value = parse_where(where)
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='sales'")
        if cursor.fetchone() is None:
            raise ValueError("Table 'sales' does not exist")

        cursor.execute(f"SELECT id, region, amount FROM sales WHERE {column} = ?", (value,))
        rows = cursor.fetchall()

        writer = csv.writer(sys.stdout)
        writer.writerow(['id', 'region', 'computed'])

        for row in rows:
            row_dict = {'id': row[0], 'region': row[1], 'amount': row[2]}
            computed = evaluate_formula(formula, row_dict)
            writer.writerow([row[0], row[1], f"{computed:.2f}"])

        conn.close()

        timestamp = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        with open('query.log', 'a') as log:
            log.write(f"{timestamp} | OK | {len(rows)}\n")

        sys.exit(0)

    except Exception as e:
        timestamp = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        with open('query.log', 'a') as log:
            log.write(f"{timestamp} | ERROR | {str(e)}\n")

        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import time
import sqlite3
import ast
import operator
import re

def evaluate_expression(expression, row_values):
    operators = {
        ast.Add: operator.add
    }

    def eval_node(node):
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return operators[type(node.op)](left, right)
        elif isinstance(node, ast.Name):
            if node.id not in row_values:
                raise ValueError(f"Invalid column name: {node.id}")
            return row_values[node.id]
        elif isinstance(node, ast.Num):
            return node.n
        else:
            raise ValueError("Unsupported expression")

    tree = ast.parse(expression, mode='eval')
    return eval_node(tree.body)

def sanitize_table_name(name):
    if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
        raise ValueError("Invalid table name")
    return name

def sanitize_column_names(names):
    sanitized = []
    for name in names:
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
            raise ValueError(f"Invalid column name: {name}")
        sanitized.append(name)
    return sanitized

def main():
    if len(sys.argv) != 4:
        print("Usage: python apply_rules.py rules.txt data.sqlite3 --max-rows-per-second N")
        sys.exit(1)

    rules_file = sys.argv[1]
    db_file = sys.argv[2]
    max_rows_per_second = int(sys.argv[3])

    if max_rows_per_second <= 0:
        print("Error: max_rows_per_second must be greater than 0")
        sys.exit(1)

    try:
        with open(rules_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except IOError:
        print("Error: Unable to read the rules file")
        sys.exit(1)

    if len(lines) < 2:
        print("Error: Rules file must contain at least two lines")
        sys.exit(1)

    table_name = sanitize_table_name(lines[0].strip())
    columns = sanitize_column_names(lines[1].strip().split(','))
    rules = [line.strip().split('\t') for line in lines[2:] if line.strip()]

    if not rules:
        print("Error: No rules found in the rules file")
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
    except sqlite3.Error:
        print("Error: Unable to connect to the database")
        sys.exit(1)

    try:
        query = f"SELECT {', '.join(columns)} FROM {table_name}"
        cursor.execute(query)
    except sqlite3.Error:
        print("Error: Unable to execute the query")
        sys.exit(1)

    rule_counts = {rule[0]: 0 for rule in rules}
    last_read_time = time.time()

    try:
        for row in cursor:
            row_values = dict(zip(columns, row))
            for rule_name, expression in rules:
                try:
                    if evaluate_expression(expression, row_values) > 0:
                        rule_counts[rule_name] += 1
                except ValueError:
                    print(f"Error: Invalid expression for rule '{rule_name}'")
                    sys.exit(1)

            current_time = time.time()
            elapsed_time = current_time - last_read_time
            if elapsed_time < 1 / max_rows_per_second:
                time.sleep(1 / max_rows_per_second - elapsed_time)
            last_read_time = time.time()
    except KeyboardInterrupt:
        pass
    finally:
        conn.close()

    for rule_name, count in rule_counts.items():
        print(f"{rule_name}\t{count}")

if __name__ == "__main__":
    main()

import sys
import json
import sqlite3
import time
from collections import deque

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python inventory_report.py <database_file>\n")
        sys.exit(1)

    db_path = sys.argv[1]
    query_times = deque()
    query_failed = False

    for line_number, line in enumerate(sys.stdin, start=1):
        line = line.strip()
        if not line:
            continue

        try:
            query_data = json.loads(line)
        except json.JSONDecodeError:
            sys.stderr.write(f"ERROR {line_number}\n")
            continue

        # Validate JSON keys and values
        valid_keys = {"id", "name", "quantity", "price"}
        if not all(key in valid_keys for key in query_data.keys()):
            sys.stderr.write(f"ERROR {line_number}\n")
            continue

        while len(query_times) >= 3 and time.time() - query_times[0] < 1:
            time.sleep(0.1)

        query_times.append(time.time())
        if len(query_times) > 3:
            query_times.popleft()

        sys.stderr.write(f"INFO start {line_number}\n")

        try:
            with sqlite3.connect(db_path, timeout=5) as conn:
                cursor = conn.cursor()
                query = "SELECT id, name, quantity, price FROM items WHERE " + " AND ".join(
                    f"{key} = ?" for key in query_data.keys()
                )
                cursor.execute(query, tuple(query_data.values()))
                rows = cursor.fetchall()

                for row in rows:
                    print(json.dumps(dict(zip(["id", "name", "quantity", "price"], row))))

                sys.stderr.write(f"INFO done {line_number} {len(rows)}\n")
        except sqlite3.Error:
            sys.stderr.write(f"ERROR {line_number}\n")
            query_failed = True

    if query_failed:
        sys.exit(1)
    sys.exit(0)

