import sys
import urllib.request
import json
import hashlib
import hmac
import re
import time

def validate_url(url):
    # Basic URL validation
    if not re.match(r'^https?://', url):
        raise ValueError("Invalid URL scheme")
    if len(url) > 2048:
        raise ValueError("URL too long")

def validate_json(data):
    # Validate JSON structure and content
    if not isinstance(data, dict):
        raise ValueError("Invalid JSON structure")
    if not all(k in data for k in ('expression', 'hash_algorithm', 'digest')):
        raise ValueError("Missing required fields in JSON")
    if not isinstance(data['expression'], str) or not isinstance(data['hash_algorithm'], str) or not isinstance(data['digest'], str):
        raise ValueError("Invalid field types in JSON")
    if not re.match(r'^[0-9+\-*\s()]+$', data['expression']):
        raise ValueError("Invalid characters in expression")
    if data['hash_algorithm'] not in hashlib.algorithms_available:
        raise ValueError("Unsupported hash algorithm")
    if not re.match(r'^[a-fA-F0-9]+$', data['digest']):
        raise ValueError("Invalid digest format")

def secure_compare(a, b):
    # Constant-time comparison to prevent timing attacks
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def evaluate_expression(expression):
    # Use a safer evaluation method
    try:
        return eval(expression, {"__builtins__": None}, {})
    except Exception:
        raise ValueError("Invalid expression")

def fetch_json(url):
    # Fetch JSON with SSL verification
    context = ssl.create_default_context()
    with urllib.request.urlopen(url, context=context) as response:
        return json.loads(response.read().decode())

def main():
    if len(sys.argv) != 2:
        print("Usage: python remote_calc.py <url>")
        sys.exit(1)

    url = sys.argv[1]
    try:
        validate_url(url)
        data = fetch_json(url)
        validate_json(data)

        expression = data['expression']
        hash_algorithm = data['hash_algorithm']
        expected_digest = data['digest']

        computed_digest = hashlib.new(hash_algorithm, expression.encode('utf-8')).hexdigest()

        if secure_compare(computed_digest, expected_digest):
            result = evaluate_expression(expression)
            print(result)
        else:
            print('invalid')
    except Exception as e:
        print(f"Error: {str(e)}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import json
import time
import requests
from itertools import islice
import logging
from urllib.parse import urlparse

logging.basicConfig(level=logging.INFO)

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def safe_eval(expr, data):
    allowed_names = {
        '__builtins__': None,
        'data': data
    }
    try:
        return eval(expr, {"__builtins__": None}, allowed_names)
    except Exception:
        return "error"

def process_tasks(tasks):
    results = []
    for task in tasks:
        url = task['url']
        expr = task['expr']
        if not is_valid_url(url):
            result = "error"
        else:
            try:
                response = requests.get(url, timeout=5, verify=True)
                if response.status_code < 200 or response.status_code > 299:
                    result = "error"
                else:
                    try:
                        data = response.json()
                        result = safe_eval(expr, data)
                    except (json.JSONDecodeError, SyntaxError, NameError):
                        result = "error"
            except requests.RequestException as e:
                logging.error(f"Request failed for {url}: {e}")
                result = "error"
        results.append({"url": url, "result": result})
    return results

def main():
    with open('tasks.json', 'r') as f:
        tasks = json.load(f)

    results = []
    for batch in iter(lambda: list(islice(tasks, 4)), []):
        batch_results = process_tasks(batch)
        results.extend(batch_results)
        for result in batch_results:
            print(json.dumps(result))
        if len(tasks) > 4:
            time.sleep(1)

if __name__ == "__main__":
    main()

