import sys
import time
import ast
import operator
from collections import defaultdict
from threading import Lock, Semaphore

def read_tokens(tokens_path):
    tokens = {}
    with open(tokens_path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line:
                continue
            token, budget = line.rsplit(' ', 1)
            tokens[token] = int(budget)
    return tokens

class SafeEvaluator:
    def __init__(self):
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.FloorDiv: operator.floordiv,
            ast.Mod: operator.mod,
            ast.USub: operator.neg,
        }

    def eval(self, expr):
        try:
            return self._eval_expr(ast.parse(expr, mode='eval').body)
        except Exception:
            return None

    def _eval_expr(self, node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._eval_expr(node.left)
            right = self._eval_expr(node.right)
            if left is None or right is None:
                return None
            return self.operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = self._eval_expr(node.operand)
            if operand is None:
                return None
            return self.operators[type(node.op)](operand)
        else:
            return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python gateway.py RATE TOKENS_PATH")
        sys.exit(1)

    rate = int(sys.argv[1])
    tokens_path = sys.argv[2]

    tokens = read_tokens(tokens_path)
    token_locks = {token: Lock() for token in tokens}
    allow_semaphore = Semaphore(rate)

    evaluator = SafeEvaluator()

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        token, expression = line.rsplit(' ', 1)
        if token not in tokens:
            print(f"deny {token}")
            continue

        with token_locks[token]:
            remaining_budget = tokens[token]
            cost = evaluator.eval(expression)

            if cost is None or cost > remaining_budget:
                print(f"deny {token}")
            else:
                tokens[token] -= cost
                allow_semaphore.acquire()
                print(f"allow {token} {tokens[token]}")
                allow_semaphore.release()

if __name__ == "__main__":
    main()

import os
import sys
import time
import json
import requests
from datetime import datetime, timedelta
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    job_file = sys.argv[1]
    api_token = os.environ.get('API_TOKEN')
    if not api_token:
        sys.exit(1)

    if not os.path.isfile(job_file):
        print('error message=Invalid file path', file=sys.stderr)
        sys.exit(1)

    with open(job_file, 'r', encoding='utf-8') as f:
        job_ids = [line.strip() for line in f if line.strip()]

    headers = {
        'Authorization': f'Bearer {api_token}',
        'Content-Type': 'application/json'
    }

    request_count = 0
    last_request_time = datetime.now()

    url = 'https://api.example.com/jobs'
    if not is_valid_url(url):
        print('error message=Invalid API URL', file=sys.stderr)
        sys.exit(1)

    for job_id in job_ids:
        current_time = datetime.now()
        if current_time - last_request_time >= timedelta(seconds=1):
            request_count = 0
            last_request_time = current_time

        if request_count >= 5:
            time_to_wait = 1 - (current_time - last_request_time).total_seconds()
            if time_to_wait > 0:
                time.sleep(time_to_wait)
            request_count = 0
            last_request_time = datetime.now()

        try:
            response = requests.post(
                url,
                headers=headers,
                data=json.dumps({'job_id': job_id}),
                verify=True
            )
            if response.status_code == 200:
