import sys
import os
import hashlib
import ast
import signal

class TimeoutException(Exception):
    pass

def timeout_handler(signum, frame):
    raise TimeoutException

def safe_eval(node, namespace):
    if isinstance(node, ast.Expression):
        return safe_eval(node.body, namespace)
    elif isinstance(node, ast.Name):
        if node.id in namespace:
            return namespace[node.id]
        else:
            raise NameError(f"name '{node.id}' is not defined")
    elif isinstance(node, ast.Load):
        return safe_eval(node.value, namespace)
    elif isinstance(node, ast.BinOp):
        left = safe_eval(node.left, namespace)
        right = safe_eval(node.right, namespace)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.UnaryOp):
        operand = safe_eval(node.operand, namespace)
        if isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.USub):
            return -operand
    elif isinstance(node, ast.Call):
        func = safe_eval(node.func, namespace)
        args = [safe_eval(arg, namespace) for arg in node.args]
        return func(*args)
    else:
        raise ValueError(f"Unsupported operation: {ast.dump(node)}")

def main():
    input_data = sys.stdin.buffer.read()
    first_newline = input_data.find(b'\n')
    if first_newline == -1:
        sys.stderr.write("ERROR: Invalid input format\n")
        sys.exit(1)

    header = input_data[:first_newline].decode('utf-8')
    if not header.startswith('check='):
        sys.stderr.write("ERROR: Invalid input format\n")
        sys.exit(1)

    expected_check = header[6:]
    body = input_data[first_newline + 1:]

    salt = os.getenv('RECIPE_SALT', '')
    if not salt:
        sys.stderr.write("ERROR: RECIPE_SALT environment variable not set\n")
        sys.exit(1)

    computed_check = hashlib.sha256(body + salt.encode('utf-8')).hexdigest()
    if computed_check != expected_check:
        sys.stderr.write("ERROR: check mismatch\n")
        sys.exit(1)

    lines = body.decode('utf-8').splitlines()
    namespace = {}

    for i, line in enumerate(lines, start=1):
        line = line.strip()
        if not line:
            continue

        if '=' not in line:
            sys.stderr.write(f"ERROR line {i}: Invalid assignment\n")
            sys.exit(1)

        name, expression = line.split('=', 1)
        name = name.strip()
        expression = expression.strip()

        if not name.isidentifier():
            sys.stderr.write(f"ERROR line {i}: Invalid variable name\n")
            sys.exit(1)

        try:
            tree = ast.parse(expression, mode='eval')
            signal.signal(signal.SIGALRM, timeout_handler)
            signal.alarm(1)  # 1 second timeout
            value = safe_eval(tree.body, namespace)
            signal.alarm(0)
            print(f"{name}={value}")
            sys.stderr.write(f"OK {name}={value}\n")
            namespace[name] = value
        except TimeoutException:
            sys.stderr.write(f"ERROR line {i}: Evaluation timed out\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"ERROR line {i}: {str(e)}\n")
            sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import time
import hashlib
from collections import deque
import re

def compute_key(expression):
    return hashlib.sha256(expression.encode('utf-8')).hexdigest()

def evaluate_expression(expression):
    try:
        # Use a safe eval by restricting the allowed functions and operators
        allowed_names = {
            '__builtins__': None,
        }
        result = eval(expression, {"__builtins__": None}, allowed_names)
        return int(result)
    except ZeroDivisionError:
        return 0
    except Exception:
        return None

def validate_expression(expression):
    # Validate that the expression contains only allowed characters
    if not re.match(r'^[\d\s\(\)\+\-\*/]+$', expression):
        return False
    return True

def read_cache(cache_path):
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            for line in f:
                key, value = line.strip().split(' ', 1)
                cache[key] = int(value)
    return cache

def write_cache(cache_path, cache):
    with open(cache_path, 'w') as f:
        for key, value in cache.items():
            f.write(f"{key} {value}\n")

def main(input_path, output_path):
    cache_path = os.path.join(os.getcwd(), 'expr.cache')
    cache = read_cache(cache_path)
    results = []
    uncached_queue = deque()
    current_time = time.time()

    try:
        with open(input_path, 'r') as infile:
            for expression in infile:
                expression = expression.strip()
                if not validate_expression(expression):
                    results.append(None)
                    continue

                key = compute_key(expression)
                if key in cache:
                    results.append(cache[key])
                else:
                    while (uncached_queue and 
                           current_time - uncached_queue[0] >= 1 and 
                           len(uncached_queue) >= 5):
                        time.sleep(0.1)
                    uncached_queue.append(time.time())
                    result = evaluate_expression(expression)
                    if result is not None:
                        cache[key] = result
                        results.append(result)
                    else:
                        results.append(None)

        write_cache(cache_path, cache)

        with open(output_path, 'w') as outfile:
            for result in results:
                if result is not None:
                    outfile.write(f"{result}\n")
                else:
                    outfile.write("Invalid expression\n")

    except IOError as e:
        print(f"Error handling files: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python evalcache.py <input_path> <output_path>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

import sys
import json
import re
from datetime import datetime
import os
import ast

def log_message(message):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_path = os.path.abspath('render.log')
    try:
        with open(log_path, 'a', encoding='utf-8') as log_file:
            log_file.write(f"{timestamp} {message}\n")
    except Exception as e:
        print(f"ERROR: Could not write to log file: {str(e)}", file=sys.stderr)
        sys.exit(1)

def safe_eval(expr, values):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expr, mode='eval')
        # Compile the AST into a code object
        code = compile(tree, filename="<ast>", mode="eval")
        # Evaluate the code object with the provided values
        return eval(code, {"__builtins__": {}}, values)
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {str(e)}")

def render_template(template, values):
    def replace_placeholder(match):
        expr = match.group(1)
        try:
            result = safe_eval(expr, values)
            return f"{result:.2f}"
        except ValueError as e:
            raise ValueError(f"Invalid expression: {str(e)}")

    return re.sub(r'\{\{(.*?)\}\}', replace_placeholder, template)

def main():
    if len(sys.argv) != 3:
        log_message("ERROR Incorrect number of arguments")
        sys.exit(1)

    template_path, values_path = sys.argv[1], sys.argv[2]

    try:
        template_path = os.path.abspath(template_path)
        with open(template_path, 'r', encoding='utf-8') as template_file:
            template = template_file.read()
    except Exception as e:
        log_message(f"ERROR Could not read template file: {str(e)}")
        sys.exit(1)

    try:
        values_path = os.path.abspath(values_path)
        with open(values_path, 'r', encoding='utf-8') as values_file:
            values = json.load(values_file)
    except Exception as e:
        log_message(f"ERROR Could not read values file: {str(e)}")
        sys.exit(1)

    if not isinstance(values, dict) or not all(isinstance(v, (int, float)) for v in values.values()):
        log_message("ERROR VALUES_PATH is not a JSON object with numeric values")
        sys.exit(1)

    try:
        rendered_html = render_template(template, values)
        print(rendered_html)
        log_message(f"INFO rendered {template_path}")
    except ValueError as e:
        log_message(f"ERROR {str(e)}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import json
import time
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
import ast

def evaluate_expression(expression, data):
    try:
        # Parse the expression into an AST
        tree = ast.parse(expression, mode='eval')
        # Compile the AST into a code object
        code = compile(tree, filename="<ast>", mode="eval")
        # Evaluate the code object with the provided data as the local namespace
        return str(eval(code, {}, data))
    except Exception:
        return ''

def render_template(template, data):
    pattern = r'\{\{(.+?)\}\}'
    matches = re.findall(pattern, template)
    rendered = template
    for match in matches:
        rendered = rendered.replace(f'{{{{ {match} }}}}', evaluate_expression(match, data))
    return rendered

def process_object(obj, template):
    time.sleep(0.2)
    return render_template(template, obj)

def main():
    try:
        with open('template.html', 'r', encoding='utf-8') as f:
            template = f.read()
    except FileNotFoundError:
        print("Error: template.html file not found.")
        return
    except Exception as e:
        print(f"Error reading template.html: {e}")
        return

    try:
        with open('data.json', 'r', encoding='utf-8') as f:
            data_array = json.load(f)
    except FileNotFoundError:
        print("Error: data.json file not found.")
        return
    except json.JSONDecodeError:
        print("Error: data.json is not a valid JSON file.")
        return
    except Exception as e:
        print(f"Error reading data.json: {e}")
        return

    if not isinstance(data_array, list):
        print("Error: data.json must contain a JSON array.")
        return

    rendered_strings = []
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = []
        for obj in data_array:
            if not isinstance(obj, dict):
                print("Error: Each item in data.json must be a JSON object.")
                return
            future = executor.submit(process_object, obj, template)
            futures.append(future)

        for future in as_completed(futures):
            rendered_strings.append(future.result())

    try:
        with open('report.html', 'w', encoding='utf-8') as f:
            f.write(''.join(rendered_strings))
    except Exception as e:
        print(f"Error writing report.html: {e}")

if __name__ == '__main__':
    main()

import sys
import subprocess
import concurrent.futures
import html
import re
import os

def is_valid_hostname(hostname):
    if len(hostname) > 255:
        return False
    if hostname[-1] == ".":
        hostname = hostname[:-1]
    allowed = re.compile(r"(?!-)[A-Z\d-]{1,63}(?<!-)$", re.IGNORECASE)
    return all(allowed.match(x) for x in hostname.split("."))

def ping_hostname(hostname):
    if not is_valid_hostname(hostname):
        return hostname, 'FAILED', 'Invalid hostname'
    try:
        result = subprocess.run(['ping', '-c', '1', hostname], capture_output=True, text=True, check=True)
        status = 'OK'
        output = result.stdout
    except subprocess.CalledProcessError as e:
        status = 'FAILED'
        output = e.stdout or e.stderr
    except Exception as e:
        status = 'FAILED'
        output = str(e)
    return hostname, status, output

def main():
    hostnames = [line.strip() for line in sys.stdin if line.strip()]
    if not hostnames:
        print("Error: No hostnames provided", file=sys.stderr)
        sys.exit(1)

    results = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as executor:
        future_to_hostname = {executor.submit(ping_hostname, hostname): hostname for hostname in hostnames}
        for future in concurrent.futures.as_completed(future_to_hostname):
            results.append(future.result())

    try:
        with open('report.html', 'w') as report_file:
            report_file.write('<table border="1">\n')
            report_file.write('<tr><th>Host</th><th>Status</th><th>Output</th></tr>\n')
            for hostname, status, output in results:
                report_file.write(f'<tr><td>{html.escape(hostname)}</td><td>{status}</td><td>{html.escape(output)}</td></tr>\n')
            report_file.write('</table>\n')
    except IOError as e:
        print(f"Error: Unable to write to report.html: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open('run.log', 'w') as log_file:
            for hostname, status, _ in results:
                log_file.write(f'{hostname} {status}\n')
    except IOError as e:
        print(f"Error: Unable to write to run.log: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

